	["/eui camp [status | panel | announce | ask | share | finds]"] = "/eui camp [status | panel | announce | ask | share | finds]",
	["/eui chat mute <channel>; <name>, unmute <channel>; <name>, filters, mutes, colors, alerts, alert <word>"] = "/eui chat mute <channel>; <name>, unmute <channel>; <name>, filters, mutes, colors, alerts, alert <word>",
	["/eui clickcast changes or removes these clicks."] = "/eui clickcast ändert oder entfernt diese Klicks.",
