	["1 px borders"] = "1-px-Ränder",
	["1 px borders around the window and each bar."] = "1-px-Ränder um das Fenster und jede Leiste.",
	["1 sec"] = "1 Sek.",
	["1 second"] = "1 Sekunde",
	["1 to 3 or the bar: pick a tower. Click: build or train. Right-click: sell. Space: next wave. P: pause."] = "1 bis 3 oder die Leiste: Turm wählen. Klick: bauen oder ausbilden. Rechtsklick: verkaufen. Leertaste: nächste Welle. P: Pause.",
	["1 to 9 pick the numbered choice or reward while the panel shows. Off: those keys stay on your action bars."] = "1 bis 9 wählen die nummerierte Option oder Belohnung, solange das Panel angezeigt wird. Aus: Diese Tasten bleiben auf Euren Aktionsleisten.",
	["1 whisper"] = "1 Flüsternachricht",
	["10 questions"] = "10 Fragen",
	["10 x 10"] = "10 x 10",
	["100% is normal running speed."] = "100% ist die normale Laufgeschwindigkeit.",
	["110 % (melee)"] = "110 % (Nahkampf)",
	["12 hour"] = "12-Stunden",
	["130 % (ranged)"] = "130 % (Distanz)",
	["16 cards"] = "16 Karten",
	["16 x 16, 40 mines"] = "16 x 16, 40 Minen",
	["1h 5m"] = "1h 5m",
	["200 px list with title, level and background."] = "200-px-Liste mit Titel, Stufe und Hintergrund.",
	["2004 nostalgia: the game's own sounds and a gold fantasy font, no banner."] = "Nostalgie von 2004: die eigenen Klänge des Spiels und eine goldene Fantasy-Schrift, kein Banner.",
	["220 px bars with the icon left and the time right."] = "220-px-Leisten mit dem Symbol links und der Zeit rechts.",
	["24 cards"] = "24 Karten",
	["24 h"] = "24 Std.",
	["24 hour"] = "24-Stunden",
	["24-hour or 12-hour time is set once for every EldoUI clock, on the General page (Clock and durability)."] = "Das 24- oder 12-Stunden-Format wird einmal für jede EldoUI-Uhr festgelegt, auf der Seite Allgemein (Uhr und Haltbarkeit).",
	["25 questions"] = "25 Fragen",
	["277 px power bar with pips on top, the current value and the spell cost while casting."] = "277-px-Ressourcenleiste mit Punkten oben, dem aktuellen Wert und den Zauberkosten beim Wirken.",
	["28 px icons without the glow, faded until the mouse is on the bar."] = "28-px-Symbole ohne Leuchten, verblasst, bis die Maus auf der Leiste ist.",
	["29 mana every 5 sec"] = "29 Mana alle 5 Sek.",
	["3 px between bars and the largest text, easy to read at a glance."] = "3 px zwischen den Leisten und der größte Text, auf einen Blick gut lesbar.",
	["3 x 3"] = "3 x 3",
	["30 px icons in a row, glow while a buff is missing."] = "30-px-Symbole in einer Reihe, Leuchten, solange ein Stärkungszauber fehlt.",
	["30 px icons stacked top to bottom."] = "30-px-Symbole von oben nach unten gestapelt.",
	["30 x 16, 99 mines"] = "30 x 16, 99 Minen",
	["32 px buffs in rows of 12 with time under them, 40 px debuffs below."] = "32-px-Stärkungszauber in Reihen zu 12 mit der Zeit darunter, 40-px-Schwächungszauber darunter.",
	["36 cards"] = "36 Karten",
	["36 px buttons with 2 px gaps on the three main rows, and smaller text."] = "36-px-Aktionstasten mit 2 px Abstand in den drei Hauptreihen und kleinerem Text.",
	["36 px icons with a swipe and the time on them; missing auras show faded."] = "36-px-Symbole mit Wischeffekt und der Zeit darauf; fehlende Auren werden verblasst angezeigt.",
	["4 px between bars, larger text."] = "4 px zwischen den Leisten, größerer Text.",
	["4 runes"] = "4 Runen",
	["4 x 4"] = "4 x 4",
	["4.5 under 10 s"] = "4,5 unter 10 s",
	["440 x 200 with 13 pt text and the edit box below."] = "440 x 200 mit 13-pt-Text und dem Eingabefeld darunter.",
	["480 x 380 for busy guilds, with saved history."] = "480 x 380 für aktive Gilden, mit gespeichertem Verlauf.",
	["5 x 5"] = "5 x 5",
	["5% of a level as rested XP"] = "5% einer Stufe als erholte EP",
	["52 px buttons on the three main rows and bigger text, for big screens."] = "52-px-Aktionstasten in den drei Hauptreihen und größerer Text, für große Bildschirme.",
	["557 x 282, accent underline on the active tab, edit box over the tabs."] = "557 x 282, Akzentunterstrich am aktiven Reiter, Eingabefeld über den Reitern.",
	["557 x 300 with 16 pt outlined text."] = "557 x 300 mit 16-pt-Text mit Kontur.",
	["6 runes"] = "6 Runen",
	["6 x 6"] = "6 x 6",
	["64 px icon that pops in, holds for a moment and fades."] = "64-px-Symbol, das aufploppt, kurz stehen bleibt und verblasst.",
	["7 x 7"] = "7 x 7",
	["700 x 260 for long lines."] = "700 x 260 für lange Zeilen.",
	["8 x 8"] = "8 x 8",
	["9 x 9"] = "9 x 9",
	["9 x 9, 10 mines"] = "9 x 9, 10 Minen",
	[":) :D ;) :( :P <3 and other text smileys show as emoji when they stand alone, so addresses and times like 12:30 stay as they are. What you send is not changed."] = ":) :D ;) :( :P <3 und andere Text-Smileys werden als Emoji angezeigt, wenn sie allein stehen, damit Adressen und Uhrzeiten wie 12:30 bleiben, wie sie sind. Was Ihr sendet, wird nicht verändert.",
	["<%s> is already muted."] = "<%s> ist bereits stummgeschaltet.",
	["<%s> is muted."] = "<%s> ist stummgeschaltet.",
	["<%s> is no longer muted."] = "<%s> ist nicht mehr stummgeschaltet.",
	["<%s> is not muted."] = "<%s> ist nicht stummgeschaltet.",
	["<id>  play a sound from the media library (eldo:Tada, kit:READY_CHECK, lsm:Air Horn)"] = "<id>  einen Sound aus der Medienbibliothek abspielen (eldo:Tada, kit:READY_CHECK, lsm:Air Horn)",
	["<spell> | off  print each charge that comes back for one of your spells"] = "<spell> | off  jede Aufladung, die für einen Eurer Zauber zurückkommt, im Chat ausgeben",
	["<text>  search the items of all your characters"] = "<text>  die Gegenstände all Eurer Charaktere durchsuchen",
	["<text>  search the selected chat window"] = "<text>  das ausgewählte Chatfenster durchsuchen",
	["? free"] = "? frei",
	["A !EUR1! string of this route to copy and paste to others."] = "Ein !EUR1!-String dieser Route zum Kopieren und Weitergeben an andere.",
	["A \"Reset\" button for the leader is on the Raid Tools bar (Group > Raid Tools > Reset instances, off by default)."] = "Eine Schaltfläche „Zurücksetzen“ für den Anführer befindet sich auf der Leiste der Schlachtzugswerkzeuge (Gruppe > Schlachtzugswerkzeuge > Instanzen zurücksetzen, standardmäßig aus).",
	["A Check ranks button on the spellbook page: left-click lists and lights up the lower ranks, right-click shows the changes to apply."] = "Eine Schaltfläche „Ränge prüfen“ auf der Zauberbuchseite: Linksklick listet die niedrigeren Ränge auf und hebt sie hervor, Rechtsklick zeigt die anzuwendenden Änderungen.",
	["A Copy button on the chat's side rail: the selected window as plain text."] = "Eine Schaltfläche „Kopieren“ an der Seitenleiste des Chats: das ausgewählte Fenster als reiner Text.",
	["A Find button on the chat's side rail that searches the selected window."] = "Eine Schaltfläche „Suchen“ an der Seitenleiste des Chats, die das ausgewählte Fenster durchsucht.",
	["A Planner button on Blizzard's Legacy window that opens this planner beside it."] = "Eine Schaltfläche „Planer“ in Blizzards Vermächtnisfenster, die diesen Planer daneben öffnet.",
	["A bar counting down to the gates opening."] = "Eine Leiste, die bis zum Öffnen der Tore herunterzählt.",
	["A bar for each base, tower or graveyard being taken, in the attacker's color. Uses the game's own time when the map reports one."] = "Eine Leiste für jede Basis, jeden Turm und jeden Friedhof, die gerade eingenommen werden, in der Farbe des Angreifers. Nutzt die Zeit des Spiels, wenn die Karte eine meldet.",
	["A bar for main-hand swings."] = "Eine Leiste für Schläge mit der Waffenhand.",
	["A bar for off-hand swings."] = "Eine Leiste für Schläge mit der Schildhand.",
	["A bar for ranged and wand shots."] = "Eine Leiste für Distanz- und Zauberstabschüsse.",
	["A bar per queue with the game's estimated wait. It shows \"-\" once the estimate has passed."] = "Eine Leiste pro Warteschlange mit der geschätzten Wartezeit des Spiels. Sie zeigt „-“, sobald die Schätzung verstrichen ist.",
	["A bigger counter and typing line."] = "Ein größerer Zähler und eine größere Schreibzeile.",
	["A bigger game window for a high resolution or a far screen."] = "Ein größeres Spielfenster für eine hohe Auflösung oder einen weit entfernten Bildschirm.",
	["A bright line along the edge of the swipe."] = "Eine helle Linie entlang der Kante des Wischeffekts.",
	["A bronze frame and bronze names, to match the WoW Forever art style."] = "Ein bronzener Rahmen und bronzene Namen, passend zum Grafikstil von WoW Forever.",
	["A buff of yours that changes a spell glows on that spell's buttons while you have it, such as Maelstrom Weapon on Lightning Bolt. Its look is on the Glows page (Spell cues: buff)."] = "Ein Stärkungszauber von Euch, der einen Zauber verändert, leuchtet auf den Aktionstasten dieses Zaubers, solange Ihr ihn habt, etwa Waffe des Mahlstroms auf Blitzschlag. Seine Optik steht auf der Seite „Leuchteffekte“ (Zauberhinweise: Stärkungszauber).",
	["A built-in section: the game's item types fill it. Your own categories come first, then the built-in sections; drop an item on its title to keep it here."] = "Ein eingebauter Abschnitt: Die Gegenstandsarten des Spiels füllen ihn. Eure eigenen Kategorien kommen zuerst, dann die eingebauten Abschnitte; legt einen Gegenstand auf seinem Titel ab, um ihn hier zu behalten.",
	["A burst of guild join, leave, online and offline lines shows as one line per kind, such as \"5 more came online: Name, Name ...\". Point at [all] for every name. Off by default."] = "Eine Flut von Gildenzeilen zu Beitritt, Austritt, online und offline wird als eine Zeile pro Art angezeigt, etwa „5 weitere sind online gekommen: Name, Name ...“. Zeigt auf [alle] für jeden Namen. Standardmäßig aus.",
	["A button for a mount: the best mount item in your bags, or a mount from your collection (right-click picks which)."] = "Eine Schaltfläche für ein Reittier: der beste Reittiergegenstand in Euren Taschen oder ein Reittier aus Eurer Sammlung (Rechtsklick wählt, welches).",
	["A button for bandages."] = "Eine Schaltfläche für Verbände.",
	["A button for drinks."] = "Eine Schaltfläche für Getränke.",
	["A button for food."] = "Eine Schaltfläche für Essen.",
	["A button for healing potions."] = "Eine Schaltfläche für Heiltränke.",
	["A button for healthstones."] = "Eine Schaltfläche für Gesundheitssteine.",
	["A button for mana potions."] = "Eine Schaltfläche für Manatränke.",
	["A button for your Hearthstone, with its cooldown."] = "Eine Schaltfläche für Euren Ruhestein, mit seiner Abklingzeit.",
	["A button for your conjured mana gem, with its cooldown. It stays on the bar while you carry none, so you see when to conjure one."] = "Eine Schaltfläche für Euren herbeigezauberten Manaedelstein, mit seiner Abklingzeit. Sie bleibt auf der Leiste, auch wenn Ihr keinen dabeihabt, damit Ihr seht, wann Ihr einen herbeizaubern solltet.",
	["A button glows while the effect it put on you or your target lasts, such as a damage or heal over time, a shield or a seal. Its look is on the Glows page (Spell cues: your effect)."] = "Eine Aktionstaste leuchtet, solange der Effekt anhält, den sie auf Euch oder Euer Ziel gelegt hat, etwa Schaden oder Heilung über Zeit, ein Schild oder ein Siegel. Ihre Optik steht auf der Seite „Leuchteffekte“ (Zauberhinweise: Euer Effekt).",
	["A calm screen with your character, zone, away time and whispers while you are marked Away."] = "Ein ruhiger Bildschirm mit Eurem Charakter, Gebiet, Abwesenheitsdauer und Flüsternachrichten, solange Ihr als abwesend markiert seid.",
	["A camera distance per situation; the first that applies wins, in the order below. Otherwise the camera goes back to your own distance."] = "Eine Kameraentfernung pro Situation; die erste zutreffende gilt, in der Reihenfolge unten. Sonst kehrt die Kamera zu Eurer eigenen Entfernung zurück.",
	["A capture must be taken."] = "Ihr müsst schlagen.",
	["A card in the alert lane when someone dies. The game decides which deaths it announces (its own Hardcore death alert setting: guild or all)."] = "Eine Karte in der Warnspalte, wenn jemand stirbt. Das Spiel entscheidet, welche Tode es ankündigt (seine eigene Einstellung für Hardcore-Todeswarnungen: Gilde oder alle).",
	["A character name the menu lists first as Banker when that player can take the item."] = "Ein Charaktername, den das Menü zuerst als Bankier aufführt, wenn dieser Spieler den Gegenstand erhalten kann.",
	["A character name the menu lists first as Disenchanter when that player can take the item."] = "Ein Charaktername, den das Menü zuerst als Entzauberer aufführt, wenn dieser Spieler den Gegenstand erhalten kann.",
	["A chat line the first time in a session that Auto switches to the game's party and raid frames."] = "Eine Chatzeile, wenn Automatisch in einer Sitzung zum ersten Mal zu den Gruppen- und Schlachtzugsrahmen des Spiels wechselt.",
	["A chat line when Edit Mode opens and a frame is placed by both EldoUI and Edit Mode."] = "Eine Chatzeile, wenn der Bearbeitungsmodus geöffnet wird und ein Rahmen sowohl von EldoUI als auch vom Bearbeitungsmodus platziert wird.",
	["A check lists each slot with a lower rank in chat (only you see it): where it is, its rank and the highest rank you know."] = "Eine Prüfung listet jeden Platz mit einem niedrigeren Rang im Chat auf (nur Ihr seht es): wo er ist, seinen Rang und den höchsten Rang, den Ihr kennt.",
	["A class icon before each name."] = "Ein Klassensymbol vor jedem Namen.",
	["A class or role icon on the frame's top right corner. Round in the Blizzard and Classic skins, square in Modern (Layout and style > Appearance)."] = "Ein Klassen- oder Rollensymbol in der oberen rechten Ecke des Rahmens. Rund in den Skins Blizzard und Classic, eckig in Modern (Layout und Stil > Erscheinungsbild).",
	["A class spell's icon and four names: which one is it?"] = "Das Symbol eines Klassenzaubers und vier Namen: Welcher ist es?",
	["A clock swipe over the big icon as the time runs out."] = "Ein Uhrzeiger-Wischeffekt über dem großen Symbol, während die Zeit abläuft.",
	["A coin, a darker icon, both, or nothing. Live bag marks follow Merchant's junk rules while that module is on, and mark gray items while it is off."] = "Eine Münze, ein dunkleres Symbol, beides oder nichts. Markierungen in den aktuellen Taschen folgen den Plunderregeln des Moduls Händler, solange es an ist, und markieren graue Gegenstände, solange es aus ist.",
	["A color for the whole bar from a stack count up. Later ranges win."] = "Eine Farbe für die ganze Leiste ab einer Stapelanzahl. Spätere Bereiche haben Vorrang.",
	["A color of its own once the bar is full."] = "Eine eigene Farbe, sobald die Leiste voll ist.",
	["A color per chat type (say, guild, party ...) and per joined channel. Channels keep their color when their number changes."] = "Eine Farbe pro Chatart (Sagen, Gilde, Gruppe ...) und pro beigetretenem Kanal. Kanäle behalten ihre Farbe, wenn sich ihre Nummer ändert.",
	["A color per pip"] = "Eine Farbe pro Punkt",
	["A colored border on buttons that hold an item you are wearing (trinkets, for example)."] = "Ein farbiger Rand an Aktionstasten, die einen Gegenstand enthalten, den Ihr tragt (zum Beispiel Schmuckstücke).",
	["A column at the side of the screen."] = "Eine Spalte am Bildschirmrand.",
	["A cross"] = "Ein Kreuz",
	["A crown"] = "Eine Krone",
	["A daily limit to count against as well. Forever has none."] = "Zusätzlich ein Tageslimit, gegen das gezählt wird. Forever hat keines.",
	["A dark box behind each bar."] = "Ein dunkler Hintergrund hinter jeder Leiste.",
	["A dialog view for quest and gossip NPCs: big readable text, numbered choices, Space to go on and Esc to leave."] = "Eine Dialogansicht für Quest- und Gesprächs-NPCs: großer, gut lesbarer Text, nummerierte Optionen, Leertaste zum Fortfahren und Esc zum Verlassen.",
	["A draw."] = "Unentschieden.",
	["A farming session bar: time, looted gold, item value and XP, each per hour, with sessions saved per zone."] = "Eine Leiste für Farmsitzungen: Zeit, geplündertes Gold, Gegenstandswert und EP, jeweils pro Stunde, mit pro Gebiet gespeicherten Sitzungen.",
	["A few seconds after login, prints a chat line for each character with mail that is returned or deleted soon, on every realm."] = "Einige Sekunden nach dem Einloggen erscheint für jeden Charakter, dessen Post bald zurückgeschickt oder gelöscht wird, eine Chatzeile, auf jedem Realm.",
	["A few seconds after login, prints a chat line for each character with running auctions who has not visited the auction house for a while."] = "Einige Sekunden nach dem Einloggen erscheint für jeden Charakter mit laufenden Auktionen, der eine Weile nicht im Auktionshaus war, eine Chatzeile.",
	["A fish"] = "Ein Fisch",
	["A fixed amount"] = "Ein fester Betrag",
	["A flash when the game lights up a spell, and your buffs on the spells they change. Nothing is guessed or cast for you."] = "Ein Aufblitzen, wenn das Spiel einen Zauber hervorhebt, und Eure Stärkungszauber auf den Zaubern, die sie verändern. Nichts wird geraten oder für Euch gewirkt.",
	["A flat EldoUI border behind every icon."] = "Ein flacher EldoUI-Rand hinter jedem Symbol.",
	["A friend comes online"] = "Ein Freund kommt online",
	["A full panel in your art style, bronze under WoW Forever."] = "Ein volles Panel in Eurem Grafikstil, unter WoW Forever bronzen.",
	["A full scan is possible again in %d min."] = "Ein vollständiger Scan ist in %d Min. wieder möglich.",
	["A gem"] = "Ein Edelstein",
	["A glow around the pulse icon. Its look is on the Glows page (Cooldown pulse)."] = "Ein Leuchten um das Pulssymbol. Seine Optik steht auf der Seite „Leuchteffekte“ (Abklingzeitpuls).",
	["A glow on the big icon from the danger time. Its look is on the Glows page (Encounter Timeline)."] = "Ein Leuchten auf dem großen Symbol ab der Gefahrenzeit. Seine Optik steht auf der Seite „Leuchteffekte“ (Begegnungszeitleiste).",
	["A glow round the bar during the cast, in the theme color. Its style is set on the Glows page."] = "Ein Leuchten um die Leiste während des Zauberns, in der Themenfarbe. Sein Stil wird auf der Seite „Leuchteffekte“ festgelegt.",
	["A glow while a member has an aura the game marks as a boss aura. Style and color on the Glows page."] = "Ein Leuchten, solange ein Mitglied eine Aura hat, die das Spiel als Bossaura markiert. Stil und Farbe auf der Seite „Leuchteffekte“.",
	["A goblet"] = "Ein Kelch",
	["A green arrow on items that beat what you wear (Upgrades module)."] = "Ein grüner Pfeil auf Gegenständen, die besser sind als das, was Ihr tragt (Modul Verbesserungen).",
	["A group member levels up"] = "Ein Gruppenmitglied steigt eine Stufe auf",
	["A heart"] = "Ein Herz",
	["A house"] = "Ein Haus",
	["A key"] = "Ein Schlüssel",
	["A large 96 px icon with a longer hold, hard to miss."] = "Ein großes 96-px-Symbol, das länger stehen bleibt, schwer zu übersehen.",
	["A large search line with the screen dimmed behind it."] = "Eine große Suchzeile mit abgedunkeltem Bildschirm dahinter.",
	["A line at the moment the hourly count drops below the limit again."] = "Eine Zeile in dem Moment, in dem die stündliche Zählung wieder unter das Limit fällt.",
	["A line that shows while a value is low. The game works out when; EldoUI only draws the line. No sound. Off by default."] = "Eine Zeile, die erscheint, solange ein Wert niedrig ist. Das Spiel ermittelt, wann; EldoUI zeichnet nur die Zeile. Kein Sound. Standardmäßig aus.",
	["A line that shows while your health is below the percent on the Warnings tab. The game works out when; EldoUI only draws it. No sound."] = "Eine Zeile, die erscheint, solange Eure Gesundheit unter dem Prozentwert auf dem Reiter Warnungen liegt. Das Spiel ermittelt, wann; EldoUI zeichnet sie nur. Kein Sound.",
	["A line that shows while your mana is below the percent on the Warnings tab. No sound."] = "Eine Zeile, die erscheint, solange Euer Mana unter dem Prozentwert auf dem Reiter Warnungen liegt. Kein Sound.",
	["A line that shows while your pet's health is below the percent on the Warnings tab. No sound."] = "Eine Zeile, die erscheint, solange die Gesundheit Eures Begleiters unter dem Prozentwert auf dem Reiter Warnungen liegt. Kein Sound.",
	["A line when an entry turns out to be the same run as the one before."] = "Eine Zeile, wenn sich ein Eintrag als derselbe Durchlauf wie der vorherige herausstellt.",
	["A line when you enter a battleground or arena, which never counts toward the limit."] = "Eine Zeile, wenn Ihr ein Schlachtfeld oder eine Arena betretet, was nie zum Limit zählt.",
	["A line where you would take aggro: 110 % of the tank's threat in melee, 130 % at range (Blizzard's rule)."] = "Eine Linie, ab der Ihr die Aggro ziehen würdet: 110 % der Bedrohung des Tanks im Nahkampf, 130 % auf Distanz (Blizzards Regel).",
	["A line with the hourly count when you enter a dungeon, with links to the log and to remove the entry."] = "Eine Zeile mit der stündlichen Zählung, wenn Ihr einen Dungeon betretet, mit Links zum Protokoll und zum Entfernen des Eintrags.",
	["A lock on an item"] = "Ein Schloss auf einem Gegenstand",
	["A look sets how the bars look, never where they sit. Pick one per talent group to switch with your talents; save your own into slot A or B."] = "Eine Optik legt fest, wie die Leisten aussehen, nie, wo sie sitzen. Wählt eine pro Talentgruppe, um mit Euren Talenten zu wechseln; speichert Eure eigene in Platz A oder B.",
	["A macro conditional that replaces when these frames show, for example \"[group:raid] show; hide\". End it with show or hide. Empty = EldoUI's own rule."] = "Eine Makrobedingung, die ersetzt, wann diese Rahmen erscheinen, zum Beispiel \"[group:raid] show; hide\". Beendet sie mit show oder hide. Leer = EldoUIs eigene Regel.",
	["A mark on item buttons and a tooltip line that say whether you have an item's appearance, and set progress in the Loot Guide."] = "Eine Markierung auf Gegenstandsschaltflächen und eine Tooltipzeile, die zeigen, ob Ihr die Vorlage eines Gegenstands habt, dazu der Set-Fortschritt im Loot Guide.",
	["A marker for every pack of mobs, from the Classic spawn data."] = "Eine Markierung für jede Gegnergruppe, aus den Classic-Spawndaten.",
	["A message closed with Escape, or open during a loading screen, comes back with Ctrl+Shift+Z for this long. Secure commands (/cast and the like) are never kept."] = "Eine mit Escape geschlossene oder während eines Ladebildschirms offene Nachricht kommt so lange mit Strg+Umschalt+Z zurück. Sichere Befehle (/cast und Ähnliches) werden nie aufbewahrt.",
	["A mill: take one of the %s's pieces."] = "Eine Mühle: Nehmt einen Stein der %s.",
	["A month of lockout resets, cooldowns, calendar events, mail and auctions for your characters."] = "Ein Monat mit Sperr-Resets, Abklingzeiten, Kalenderereignissen, Post und Auktionen Eurer Charaktere.",
	["A moon"] = "Ein Mond",
	["A mover for BigWigs' messages. BigWigs can't follow it live: send the anchors again after you move it."] = "Ein Verschiebefeld für die Nachrichten von BigWigs. BigWigs kann ihm nicht live folgen: Sendet die Anker nach dem Verschieben erneut.",
	["A mover for BigWigs' pull and encounter countdown, right above your character in every layout. Like the messages, BigWigs gets its spot when you send the anchors."] = "Ein Verschiebefeld für den Pull- und Begegnungs-Countdown von BigWigs, in jedem Layout direkt über Eurem Charakter. Wie bei den Nachrichten bekommt BigWigs seinen Platz, wenn Ihr die Anker sendet.",
	["A mushroom"] = "Ein Pilz",
	["A name for the search. The same name again replaces it."] = "Ein Name für die Suche. Derselbe Name ersetzt sie.",
	["A name for this group, shown in the Group list above."] = "Ein Name für diese Gruppe, angezeigt in der Gruppenliste oben.",
	["A name for this panel, shown in the list above."] = "Ein Name für dieses Panel, angezeigt in der Liste oben.",
	["A narrow box with small rows and no second line."] = "Ein schmales Fenster mit kleinen Zeilen und ohne zweite Zeile.",
	["A narrow panel with small text, all of it at once."] = "Ein schmales Panel mit kleinem Text, alles auf einmal.",
	["A new horizontal panel with three slots (clock, gold, durability) at the top of the screen. Change it below."] = "Ein neues waagerechtes Panel mit drei Plätzen (Uhr, Gold, Haltbarkeit) oben am Bildschirm. Ändert es unten.",
	["A new panel in Dashboard display: durability, bag space, your tracked currencies, the reputation you watch and your professions, each as a row with a bar. Change its rows below."] = "Ein neues Panel in der Dashboard-Anzeige: Haltbarkeit, Taschenplatz, Eure verfolgten Währungen, der beobachtete Ruf und Eure Berufe, jeweils als Zeile mit Leiste. Ändert seine Zeilen unten.",
	["A new vertical panel with eight character stats picked for your class. In combat the game hides some stats; they show a dash until the fight ends."] = "Ein neues senkrechtes Panel mit acht für Eure Klasse gewählten Charakterwerten. Im Kampf verbirgt das Spiel einige Werte; sie zeigen einen Strich, bis der Kampf endet.",
	["A note before your camp buffs run out, and one when they end while you are still near a fire."] = "Ein Hinweis, bevor Eure Lagereffekte ablaufen, und einer, wenn sie enden, während Ihr noch in der Nähe eines Feuers seid.",
	["A note when the session's gold plus item value reaches this much."] = "Ein Hinweis, wenn das Gold der Sitzung plus Gegenstandswert diesen Betrag erreicht.",
	["A notice with a Show button when someone in your group sends you a route."] = "Ein Hinweis mit einer Schaltfläche „Anzeigen“, wenn Euch jemand aus Eurer Gruppe eine Route sendet.",
	["A panel behind the text in your art style."] = "Ein Panel hinter dem Text in Eurem Grafikstil.",
	["A percentage"] = "Ein Prozentsatz",
	["A phrase matches only as a whole word: \"gold\" hides \"buy gold\" but not \"goldfish\"."] = "Eine Phrase trifft nur als ganzes Wort zu: „gold“ blendet „gold kaufen“ aus, aber nicht „Goldfisch“.",
	["A picture behind the chat text: a background from EldoUI's media list (SharedMedia packs add more), or your own file."] = "Ein Bild hinter dem Chattext: ein Hintergrund aus der Medienliste von EldoUI (SharedMedia-Pakete fügen weitere hinzu) oder Eure eigene Datei.",
	["A picture on the left of each party frame. A member out of view or offline shows the 2D portrait instead of the model."] = "Ein Bild links neben jedem Gruppenrahmen. Ein Mitglied außer Sicht oder offline zeigt statt des Modells das 2D-Porträt.",
	["A potion"] = "Ein Trank",
	["A profession skill rises"] = "Eine Berufsfertigkeit steigt",
	["A quest is ready to turn in"] = "Eine Quest ist bereit zur Abgabe",
	["A quest link's tooltip says which of your characters have the quest, are ready to turn it in or completed it."] = "Der Tooltip eines Questlinks zeigt, welche Eurer Charaktere die Quest haben, sie abgeben können oder sie abgeschlossen haben.",
	["A quest objective is done"] = "Ein Questziel ist erfüllt",
	["A quest or recipe of yours needs this item, so EldoUI's junk selling and Move these leave it alone."] = "Eine Quest oder ein Rezept von Euch braucht diesen Gegenstand, daher lassen der Plunderverkauf von EldoUI und „Diese verschieben“ ihn in Ruhe.",
	["A rare catch!"] = "Ein seltener Fang!",
	["A ready-made set of the text settings below. Changing one of them turns this to Custom. Bars with their own text settings (Bars tab) keep those."] = "Ein fertiger Satz der Texteinstellungen unten. Ändert Ihr eine davon, wechselt dies zu Benutzerdefiniert. Leisten mit eigenen Texteinstellungen (Reiter Leisten) behalten diese.",
	["A recipe, or the item it makes. Empty shows every shared recipe."] = "Ein Rezept oder der Gegenstand, den es herstellt. Leer zeigt jedes geteilte Rezept.",
	["A red \"Binds when picked up\" line on items that bind when you win them."] = "Eine rote Zeile „Wird beim Aufheben gebunden“ auf Gegenständen, die gebunden werden, wenn Ihr sie gewinnt.",
	["A regular whisper must match this text exactly, including case and spaces. Leave empty to pause invites."] = "Ein normales Flüstern muss genau diesem Text entsprechen, einschließlich Groß- und Kleinschreibung und Leerzeichen. Lasst es leer, um Einladungen zu pausieren.",
	["A reputation standing rises"] = "Ein Rufrang steigt",
	["A ring that follows the mouse cursor."] = "Ein Ring, der dem Mauszeiger folgt.",
	["A route from your group"] = "Eine Route aus Eurer Gruppe",
	["A route keeps at most %d arrows."] = "Eine Route enthält höchstens %d Pfeile.",
	["A route keeps at most %d lines."] = "Eine Route enthält höchstens %d Linien.",
	["A route keeps at most %d notes."] = "Eine Route enthält höchstens %d Notizen.",
	["A row of filters above the Overview: faction, level, fully rested, mail and lockouts."] = "Eine Reihe Filter über der Übersicht: Fraktion, Stufe, voll erholt, Post und Sperren.",
	["A row of your bags (or bank tabs) under the search box: click one to hide or show its slots, drag bags in and out, right-click for the game's bag options."] = "Eine Reihe Eurer Taschen (oder Bankreiter) unter dem Suchfeld: Klickt eine an, um ihre Plätze aus- oder einzublenden, zieht Taschen hinein und heraus, Rechtsklick für die Taschenoptionen des Spiels.",
	["A sample cast with the theme: it fills, gets pushed back once, then finishes or is interrupted, in turn."] = "Ein Beispielzauber mit dem Thema: Er füllt sich, wird einmal verzögert und wird dann abwechselnd beendet oder unterbrochen.",
	["A sample essential row in its icon size, spacing, zoom, borders and keybinds."] = "Eine essenzielle Beispielreihe in ihrer Symbolgröße, ihrem Abstand, Zoom, ihren Rändern und Tastenbelegungen.",
	["A sample line with your emoji settings, and whether the emoji folder is ready."] = "Eine Beispielzeile mit Euren Emoji-Einstellungen und ob der Emoji-Ordner bereit ist.",
	["A sample of the timeline in your current look, the boss mod the timers come from and what reached the timeline this session."] = "Ein Beispiel der Zeitleiste in Eurer aktuellen Optik, der Bossmod, von dem die Timer stammen, und was in dieser Sitzung die Zeitleiste erreicht hat.",
	["A sample party in your party frames' size, growth and colors."] = "Eine Beispielgruppe in Größe, Wachstumsrichtung und Farben Eurer Gruppenrahmen.",
	["A second bar with its own datatexts. It sits in the top edge of the chat window, or on its own mover."] = "Eine zweite Leiste mit eigenen Datentexten. Sie sitzt am oberen Rand des Chatfensters oder auf einem eigenen Verschiebefeld.",
	["A second color from a higher stack count up."] = "Eine zweite Farbe ab einer höheren Stapelanzahl.",
	["A second column with each tank's target."] = "Eine zweite Spalte mit dem Ziel jedes Tanks.",
	["A second gain of the same item, money or faction while its row is still shown adds to that row instead of opening a new one."] = "Erhaltet Ihr denselben Gegenstand, dasselbe Geld oder Ruf derselben Fraktion erneut, während seine Zeile noch angezeigt wird, wird es zu dieser Zeile addiert, statt eine neue zu öffnen.",
	["A second line under the name with where the item is worn and what kind it is."] = "Eine zweite Zeile unter dem Namen mit dem Ort, an dem der Gegenstand getragen wird, und seiner Art.",
	["A second panel on the right for chosen kinds of messages, such as loot, so the main chat stays readable."] = "Ein zweites Panel rechts für ausgewählte Nachrichtenarten wie Beute, damit der Hauptchat lesbar bleibt.",
	["A see-through page in the heading font, text at reading pace, no model."] = "Eine durchscheinende Seite in der Überschriftenschrift, Text im Lesetempo, kein Modell.",
	["A see-through panel behind the counters."] = "Ein durchscheinendes Panel hinter den Zählern.",
	["A see-through panel behind the list."] = "Ein durchscheinendes Panel hinter der Liste.",
	["A session counts looted gold, items and their worth, and XP, also per hour. Stop saves it in the session history. Also: /eui farm."] = "Eine Sitzung zählt geplündertes Gold, Gegenstände und ihren Wert sowie EP, auch pro Stunde. Stopp speichert sie im Sitzungsverlauf. Auch: /eui farm.",
	["A shield"] = "Ein Schild",
	["A shine sweeping over the filled part of the bar."] = "Ein Glanz, der über den gefüllten Teil der Leiste streicht.",
	["A short bar after a flag capture until the flags return (Warsong Gulch)."] = "Eine kurze Leiste nach einer Flaggeneroberung, bis die Flaggen zurückkehren (Kriegshymnenschlucht).",
	["A short card or row for each item, money, reputation, currency and skill-up you gain."] = "Eine kurze Karte oder Zeile für jeden Gegenstand, jedes Geld, jeden Ruf, jede Währung und jeden Fertigkeitsanstieg, den Ihr erhaltet.",
	["A short line when combat ends."] = "Eine kurze Zeile, wenn der Kampf endet.",
	["A short line when combat starts."] = "Eine kurze Zeile, wenn der Kampf beginnt.",
	["A short note naming a camp buff when you gain it."] = "Ein kurzer Hinweis, der einen Lagereffekt nennt, wenn Ihr ihn erhaltet.",
	["A short note under or after the result (the settings page, a macro's kind, a stack size)."] = "Eine kurze Notiz unter oder nach dem Ergebnis (die Einstellungsseite, die Art eines Makros, eine Stapelgröße).",
	["A short notice at the mailbox, the auction house and the trade window while the game reports Self-Found for this character."] = "Ein kurzer Hinweis am Briefkasten, im Auktionshaus und im Handelsfenster, solange das Spiel für diesen Charakter „Selbstgefunden“ meldet.",
	["A short orange pulse when a cast is pushed back or a channel changes."] = "Ein kurzes orangefarbenes Pulsieren, wenn ein Zauber verzögert wird oder sich eine Kanalisierung ändert.",
	["A short streak of light behind the spark."] = "Ein kurzer Lichtstreif hinter dem Funken.",
	["A short text on or next to the icon: plain words or text tags, such as [cd:name], [cd:key] or [power:percent]. Empty shows nothing."] = "Ein kurzer Text auf oder neben dem Symbol: einfache Wörter oder Text-Tags wie [cd:name], [cd:key] oder [power:percent]. Leer zeigt nichts.",
	["A short word at the bottom: New, Look or Have."] = "Ein kurzes Wort unten: Neu, Aussehen oder Vorhanden.",
	["A side"] = "Eine Seite",
	["A slot is free again: %d/%d this hour (estimate)."] = "Ein Platz ist wieder frei: %d/%d in dieser Stunde (geschätzt).",
	["A small 44 px icon without name that fades quickly."] = "Ein kleines 44-px-Symbol ohne Namen, das schnell verblasst.",
	["A small Games box shows while you fly a flight path. Click it to open the games; right-click puts it away for this flight."] = "Ein kleines Feld „Spiele“ erscheint, während Ihr eine Flugroute fliegt. Klickt darauf, um die Spiele zu öffnen; Rechtsklick legt es für diesen Flug weg.",
	["A small arrow at the bar's right end: click folds the bar to a tab, right-click hides it."] = "Ein kleiner Pfeil am rechten Ende der Leiste: Klick klappt die Leiste zu einem Reiter ein, Rechtsklick blendet sie aus.",
	["A small arrow in the corner of a chat window while it is scrolled up; it turns accent when new lines arrive. Shift + mouse wheel jumps to the top or bottom."] = "Ein kleiner Pfeil in der Ecke eines Chatfensters, solange es hochgescrollt ist; er nimmt die Akzentfarbe an, wenn neue Zeilen eintreffen. Umschalt + Mausrad springt nach oben oder unten.",
	["A small bar with your food, drink, potions, bandage, healthstone, Hearthstone and mount, with counts and cooldowns. One click uses one."] = "Eine kleine Leiste mit Eurem Essen, Getränk, Tränken, Verband, Gesundheitsstein, Ruhestein und Reittier, mit Anzahl und Abklingzeiten. Ein Klick benutzt eines.",
	["A small box behind the time."] = "Ein kleiner Kasten hinter der Zeit.",
	["A small button in the title that posts the items' links to chat when you click it, highest quality first. It shows when there is something to link and a chat to post to."] = "Eine kleine Schaltfläche im Titel, die beim Klicken die Links der Gegenstände in den Chat postet, höchste Qualität zuerst. Sie erscheint, wenn es etwas zu verlinken und einen Chat zum Posten gibt.",
	["A small button in the title that takes every item when you click it."] = "Eine kleine Schaltfläche im Titel, die beim Klicken jeden Gegenstand nimmt.",
	["A small card with the next pulls of your route inside a dungeon. Check pulls off with Done; the next pull is lit on the map. Move it with /eui move."] = "Eine kleine Karte mit den nächsten Pulls Eurer Route in einem Dungeon. Hakt Pulls mit Fertig ab; der nächste Pull wird auf der Karte hervorgehoben. Verschiebt sie mit /eui move.",
	["A small check, question mark or cross in the top right corner."] = "Ein kleines Häkchen, Fragezeichen oder Kreuz in der oberen rechten Ecke.",
	["A small class or race icon (the game's own art) in front of player names. The gear sets their size, offset and where they show."] = "Ein kleines Klassen- oder Volkssymbol (die eigene Grafik des Spiels) vor Spielernamen. Das Zahnrad legt Größe, Versatz und Anzeigeorte fest.",
	["A small colored square in the top right corner."] = "Ein kleines farbiges Quadrat in der oberen rechten Ecke.",
	["A small eye in the top-left corner fades the slots and stats so only the model shows. Click again, or close the window, to bring them back."] = "Ein kleines Auge in der oberen linken Ecke blendet die Plätze und Werte aus, sodass nur das Modell zu sehen ist. Klickt erneut oder schließt das Fenster, um sie zurückzuholen.",
	["A small list of hostile players seen on nameplates, with class color, level and how long ago."] = "Eine kleine Liste feindlicher Spieler, die auf Namensplaketten gesehen wurden, mit Klassenfarbe, Stufe und wie lange es her ist.",
	["A small lock on items an open quest needs, items that start a quest you haven't done, and recipes one of your characters can still learn. On by default."] = "Ein kleines Schloss auf Gegenständen, die eine offene Quest braucht, Gegenständen, die eine Quest starten, die Ihr noch nicht erledigt habt, und Rezepten, die einer Eurer Charaktere noch lernen kann. Standardmäßig an.",
	["A small mark after a quest link: a tick when you have done the quest, the quest icon when it is in your quest log. Nothing when neither or unknown."] = "Eine kleine Markierung nach einem Questlink: ein Haken, wenn Ihr die Quest erledigt habt, das Questsymbol, wenn sie in Eurem Questlog steht. Nichts, wenn keins von beiden zutrifft oder es unbekannt ist.",
	["A small numbered tag on every pull of the route."] = "Eine kleine nummerierte Marke an jedem Pull der Route.",
	["A small panel with your camp buffs and their timers. Move it in move mode (Camp Panel)."] = "Ein kleines Panel mit Euren Lagereffekten und ihren Timern. Verschiebt es im Verschiebemodus (Lager-Panel).",
	["A small red mark on enchantable slots whose item carries no enchant, and a line in the tooltip. Read from the item link."] = "Eine kleine rote Markierung an verzauberbaren Plätzen, deren Gegenstand keine Verzauberung trägt, und eine Zeile im Tooltip. Aus dem Gegenstandslink gelesen.",
	["A small timer with the length of your current fight."] = "Ein kleiner Timer mit der Dauer Eures aktuellen Kampfes.",
	["A small window with one bar per group member on your target's threat table."] = "Ein kleines Fenster mit einer Leiste pro Gruppenmitglied auf der Bedrohungsliste Eures Ziels.",
	["A smaller game window and a box without the time left."] = "Ein kleineres Spielfenster und ein Feld ohne die verbleibende Zeit.",
	["A smile"] = "Ein Lächeln",
	["A soft dark shadow around the icon."] = "Ein weicher dunkler Schatten um das Symbol.",
	["A soft glow on a buff or poison icon while it is missing (out of combat; the game hides auras from addons in combat)."] = "Ein sanftes Leuchten auf einem Stärkungszauber- oder Giftsymbol, solange es fehlt (außerhalb des Kampfes; im Kampf verbirgt das Spiel Auren vor Addons).",
	["A soft shadow under the chat text, so it reads on bright ground."] = "Ein weicher Schatten unter dem Chattext, damit er auf hellem Untergrund lesbar ist.",
	["A sound when a new card or row appears; several at once play it once. Fanfare's loot sounds are separate."] = "Ein Sound, wenn eine neue Karte oder Zeile erscheint; mehrere auf einmal spielen ihn einmal. Die Beutesounds von Fanfare sind davon getrennt.",
	["A sound when someone else writes in guild, party, raid or another channel. None by default."] = "Ein Sound, wenn jemand anderes in Gilde, Gruppe, Schlachtzug oder einem anderen Kanal schreibt. Standardmäßig keiner.",
	["A sound with the goal note. None for silence."] = "Ein Sound mit dem Zielhinweis. Keiner für Stille.",
	["A sound with the slot-free line."] = "Ein Sound mit der Zeile „Platz frei“.",
	["A sound with the warning. None for silence."] = "Ein Sound mit der Warnung. Keiner für Stille.",
	["A spark crosses the mana bar during the 5 seconds after you cast a spell that costs mana (spirit regeneration is paused meanwhile)."] = "Ein Funke läuft während der 5 Sekunden nach einem Zauber, der Mana kostet, über die Manaleiste (die Willenskraftregeneration pausiert so lange).",
	["A spell name or ID (shift-click a spell link works too). Cooldown bars also take an item as item:ID."] = "Ein Zaubername oder eine ID (Umschaltklick auf einen Zauberlink geht auch). Abklingzeitleisten nehmen auch einen Gegenstand als item:ID.",
	["A spell you cast lately, or one you pinned. Cast the spell once to see it here, or type its ID below."] = "Ein Zauber, den Ihr kürzlich gewirkt habt, oder einer, den Ihr angeheftet habt. Wirkt den Zauber einmal, um ihn hier zu sehen, oder gebt unten seine ID ein.",
	["A spell you learn goes to its key on bars 1 to 3; a talent spell relearned after a talent reset returns to its old button. Ask me asks first; Automatic places it out of combat. Empty buttons only."] = "Ein Zauber, den Ihr lernt, kommt auf seine Taste auf den Leisten 1 bis 3; ein Talentzauber, der nach einem Zurücksetzen der Talente neu erlernt wird, kehrt auf seinen alten Platz zurück. Mit Mich fragen kommt zuerst eine Rückfrage; Automatisch platziert ihn außerhalb des Kampfes. Nur leere Plätze.",
	["A standing bar that fills upwards; width is its length and height its thickness."] = "Eine stehende Leiste, die sich nach oben füllt; die Breite ist ihre Länge und die Höhe ihre Dicke.",
	["A step whose goals are all done moves on to the next one. Off: Next moves on."] = "Ein Schritt, dessen Ziele alle erledigt sind, geht zum nächsten über. Aus: Weiter geht zum nächsten.",
	["A sticky line when your combo points are full."] = "Eine haftende Zeile, wenn Eure Kombopunkte voll sind.",
	["A string of the draft (or the selected profile) to share."] = "Ein String des Entwurfs (oder des ausgewählten Profils) zum Teilen.",
	["A string with every node on every map."] = "Ein String mit jedem Vorkommen auf jeder Karte.",
	["A string with the nodes of the map you are on, to copy and give to a friend."] = "Ein String mit den Vorkommen der Karte, auf der Ihr seid, zum Kopieren und Weitergeben an einen Freund.",
	["A summon is pending, accepted or declined."] = "Eine Beschwörung steht aus, wurde angenommen oder abgelehnt.",
	["A sword"] = "Ein Schwert",
	["A tab that flashes (a whisper in another tab) brings the strip back, so you never miss it."] = "Ein aufblinkender Reiter (eine Flüsternachricht in einem anderen Reiter) holt die Leiste zurück, damit Ihr sie nie verpasst.",
	["A tab that gets a whisper while you look at another tab flashes (the game's alert, in the EldoUI look). Off: it stays still. Skin switch."] = "Ein Reiter, der eine Flüsternachricht erhält, während Ihr einen anderen Reiter anseht, blinkt (die Warnung des Spiels, in der EldoUI-Optik). Aus: Er bleibt ruhig. Skin-Schalter.",
	["A thin bar that runs down during the global cooldown after each spell, from the game's own cooldown."] = "Eine dünne Leiste, die während der globalen Abklingzeit nach jedem Zauber abläuft, aus der eigenen Abklingzeit des Spiels.",
	["A thin cross at the center of the screen."] = "Ein dünnes Kreuz in der Bildschirmmitte.",
	["A thin cross at the center of the screen. The range tint shows the game's own in-range answer for a spell as a color."] = "Ein dünnes Kreuz in der Bildschirmmitte. Die Reichweitentönung zeigt die eigene Reichweitenantwort des Spiels für einen Zauber als Farbe.",
	["A thin dark edge around each bar, so it shows on bright ground."] = "Ein dünner dunkler Rand um jede Leiste, damit sie auf hellem Untergrund sichtbar ist.",
	["A thin gap between the cells of a board."] = "Ein schmaler Abstand zwischen den Feldern eines Spielbretts.",
	["A thin mana bar while you are in bear or cat form; the power bar shows the form's rage or energy."] = "Eine dünne Manaleiste, solange Ihr in Bären- oder Katzengestalt seid; die Ressourcenleiste zeigt die Wut oder Energie der Gestalt.",
	["A thin mark at every tick step, so you can read the distance."] = "Eine dünne Markierung bei jedem Teilstrich, damit Ihr die Entfernung ablesen könnt.",
	["A third color from a higher stack count up."] = "Eine dritte Farbe ab einer höheren Stapelanzahl.",
	["A tick each second for the soonest event and a final sound at zero. Off by default, because DBM and BigWigs can count down too."] = "Ein Ticken jede Sekunde für das nächste Ereignis und ein Schlusston bei null. Standardmäßig aus, weil DBM und BigWigs auch herunterzählen können.",
	["A timeline bar that shows the timers DBM or BigWigs publish, plus the pull countdown, as icons moving toward now."] = "Eine Zeitleiste, die die Timer, die DBM oder BigWigs veröffentlichen, sowie den Pull-Countdown als Symbole zeigt, die sich auf jetzt zubewegen.",
	["A tracking bar whose spell the game lights up (a proc or a reactive spell). Only the game's own spell alert starts it."] = "Eine Verfolgungsleiste, deren Zauber das Spiel hervorhebt (ein Proc oder ein reaktiver Zauber). Nur die eigene Zauberwarnung des Spiels startet sie.",
	["A tree"] = "Ein Baum",
	["A warning when you become flagged for PvP yourself."] = "Eine Warnung, wenn bei Euch selbst PvP aktiviert wird.",
	["A warning when your target is flagged for PvP and attacking it (a player or a guard) or healing and buffing it (a player) would flag you too."] = "Eine Warnung, wenn Euer Ziel PvP aktiviert hat und ein Angriff darauf (Spieler oder Wache) oder Heilen und Stärken (Spieler) PvP auch bei Euch aktivieren würde.",
	["A wide panel with the model and a darker screen behind it."] = "Ein breites Panel mit dem Modell und einem abgedunkelten Bildschirm dahinter.",
	["A wide, flat bar with short single-line rows."] = "Eine breite, flache Leiste mit kurzen, einzeiligen Einträgen.",
	["A wishlist item drops"] = "Ein Gegenstand der Wunschliste fällt",
	["A word shown on the bar while the spell is ready (for example Ready). Empty shows nothing."] = "Ein Wort, das auf der Leiste steht, solange der Zauber bereit ist (zum Beispiel Bereit). Leer zeigt nichts.",
	["A zone or a city and the map of its continent: click where it lies."] = "Ein Gebiet oder eine Stadt und die Karte des Kontinents: Klickt, wo es liegt.",
	["AFK Screen"] = "AFK-Bildschirm",
