	["AP"] = "AK",
	["API: %s"] = "API: %s",
	["Abandon %s"] = "%s abbrechen",
	["Above or below the bar; pick below for a bar along the top edge."] = "Über oder unter der Leiste; wählt unten für eine Leiste am oberen Rand.",
	["Above the bar"] = "Über der Leiste",
	["Above the chat"] = "Über dem Chat",
	["Above the damage meter"] = "Über dem Schadensmesser",
	["Above the damage meter needs the damage meter's Move switch; otherwise the timer uses its own mover (EldoUI_CombatTimer)."] = "„Über dem Schadensmesser“ braucht den Schalter „Verschieben“ des Schadensmessers; sonst nutzt der Timer sein eigenes Verschiebefeld (EldoUI_CombatTimer).",
	["Above the debuffs"] = "Über den Schwächungszaubern",
	["Above the icon"] = "Über dem Symbol",
	["Absorb"] = "Absorbiert",
	["Accent"] = "Akzent",
	["Accent background"] = "Akzenthintergrund",
	["Accent bar"] = "Akzentleiste",
	["Accent border on the member you have targeted."] = "Akzentrand am Mitglied, das Ihr anvisiert habt.",
	["Accent borders and headers with an accent gradient behind the model."] = "Akzentränder und -überschriften mit einem Akzentverlauf hinter dem Modell.",
	["Accent color in combat"] = "Akzentfarbe im Kampf",
	["Accent shades"] = "Akzentschattierungen",
	["Accent text only"] = "Nur Akzenttext",
	["Accent underline"] = "Akzentunterstrich",
	["Accent-tinted column headers"] = "Spaltenköpfe in Akzenttönung",
	["Accept %s"] = "%s annehmen",
	["Account"] = "Account",
