	["Account bank page %d"] = "Accountbank, Seite %d",
	["Account macro"] = "Allgemeines Makro",
	["Account: %s"] = "Account: %s",
	["Achievement earned"] = "Erfolg errungen",
	["Action Bar %d"] = "Aktionsleiste %d",
	["Action Bars"] = "Aktionsleisten",
	["Action bar bag buttons"] = "Taschenschaltflächen der Aktionsleiste",
	["Action buttons that still hold a lower rank of a spell you know at a higher rank (Action Bars, Spell ranks)."] = "Aktionstasten, die noch einen niedrigeren Rang eines Zaubers enthalten, den Ihr in höherem Rang kennt (Aktionsleisten, Zauberränge).",
	["Action: %s"] = "Aktion: %s",
	["Actions"] = "Aktionen",
	["Active"] = "Aktiv",
	["Active DBM profile: %s"] = "Aktives DBM-Profil: %s",
	["Active Edit Mode layout: %s"] = "Aktives Layout im Bearbeitungsmodus: %s",
	["Active Edit Mode layout: %s (positions per layout are off)"] = "Aktives Layout im Bearbeitungsmodus: %s (Positionen pro Layout sind aus)",
	["Active look"] = "Optik wenn aktiv",
	["Active tab"] = "Aktiver Reiter",
	["Acts for you"] = "Handelt für Euch",
	["Acts for you when turned on: confirms Bind on Pickup items when you loot alone. Group loot and other confirmations still ask. Off by default."] = "Handelt für Euch, wenn eingeschaltet: bestätigt Gegenstände, die beim Aufheben gebunden werden, wenn Ihr allein plündert. Gruppenbeute und andere Bestätigungen fragen weiterhin. Standardmäßig aus.",
	["Acts for you when turned on: sends a group invite when a player's regular whisper exactly matches your keyword. Out of combat only. Off by default."] = "Handelt für Euch, wenn eingeschaltet: Sendet eine Gruppeneinladung, wenn das normale Flüstern eines Spielers genau Eurem Stichwort entspricht. Nur außerhalb des Kampfes. Standardmäßig aus.",
	["Acts for you when turned on: when the game auto loots, takes every item at once instead of one by one. Works with either window. Off by default: turn it on here or in the setup."] = "Handelt für Euch, wenn eingeschaltet: Wenn das Spiel automatisch plündert, werden alle Gegenstände auf einmal statt einzeln genommen. Funktioniert mit beiden Fenstern. Standardmäßig aus: Schaltet es hier oder in der Einrichtung ein.",
	["Acts for you: declines duel requests from members of the guilds you muted, out of combat, and says who in chat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Duellanfragen von Mitgliedern der stummgeschalteten Gilden ab und sagt im Chat, von wem.",
	["Acts for you: declines group invites from members of the guilds you muted, out of combat, and says who in chat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Gruppeneinladungen von Mitgliedern der stummgeschalteten Gilden ab und sagt im Chat, von wem.",
	["Acts for you: sends a group invite when a regular whisper matches your keyword exactly, out of combat. Set the keyword in Chat settings."] = "Handelt für Euch: sendet außerhalb des Kampfes eine Gruppeneinladung, wenn ein normales Flüstern genau Eurem Stichwort entspricht. Das Stichwort legt Ihr in den Chateinstellungen fest.",
	["Acts for you: when the game auto loots, every item is taken at once instead of one by one."] = "Handelt für Euch: Wenn das Spiel automatisch plündert, werden alle Gegenstände auf einmal statt einzeln genommen.",
	["Add a dashboard"] = "Dashboard hinzufügen",
	["Add a panel"] = "Panel hinzufügen",
	["Add a rank"] = "Rang hinzufügen",
	["Add a stats panel"] = "Werte-Panel hinzufügen",
	["Add an item"] = "Gegenstand hinzufügen",
	["Add area"] = "Bereich hinzufügen",
	["Add bar"] = "Leiste hinzufügen",
	["Add my main cooldown row"] = "Meine Hauptabklingzeitreihe hinzufügen",
	["Add or remove columns. The styles on the Alts page set a good mix."] = "Spalten hinzufügen oder entfernen. Die Stile auf der Seite Twinks ergeben eine gute Mischung.",
	["Add or remove counters"] = "Zähler hinzufügen oder entfernen",
	["Add spells from"] = "Zauber hinzufügen aus",
	["Add spells or items in the Icons row above, or drag icons here in move mode."] = "Fügt in der Zeile Symbole oben Zauber oder Gegenstände hinzu oder zieht im Verschiebemodus Symbole hierher.",
	["Add to list"] = "Zur Liste hinzufügen",
	["Add to the selected list"] = "Zur ausgewählten Liste hinzufügen",
	["Add up repeats"] = "Wiederholungen addieren",
	["Added \"%s\" to %s."] = "\"%s\" zu %s hinzugefügt.",
	["Added \"%s\"."] = "\"%s\" hinzugefügt.",
	["Added %d spells from your main cooldown row."] = { one = "%d Zauber aus Eurer Hauptabklingzeitreihe hinzugefügt.", other = "%d Zauber aus Eurer Hauptabklingzeitreihe hinzugefügt." },
	["Added in the draft"] = "Im Entwurf hinzugefügt",
	["Added."] = "Hinzugefügt.",
	["Addon Lua memory"] = "Lua-Speicher der Addons",
	["Addon memory"] = "Addon-Speicher",
	["Addon messages are paused here. Try again when the fight or match is over."] = "Addon-Nachrichten sind hier pausiert. Versucht es erneut, wenn der Kampf oder das Match vorbei ist.",
	["Adds"] = "Adds",
	["Adds \"Announce the last reset\" to the Instances datatext menu, the reset line and the Raid Tools Reset button. Each click sends one line to group chat."] = "Fügt „Letzten Reset ankündigen“ zum Menü des Datentexts Instanzen, zur Reset-Zeile und zur Reset-Schaltfläche der Schlachtzugswerkzeuge hinzu. Jeder Klick sendet eine Zeile in den Gruppenchat.",
	["Adds \"Appearance: collected / not collected\" to item tooltips, also at the auction house."] = "Fügt Gegenstandstooltips „Vorlage: gesammelt / nicht gesammelt“ hinzu, auch im Auktionshaus.",
	["Adds \"Post to group\" and \"Post to guild\" to the log's right-click menu and lets /eui instances stats party send the newest run. Each post is one click."] = "Fügt dem Rechtsklickmenü des Protokolls „An Gruppe posten“ und „An Gilde posten“ hinzu und lässt /eui instances stats party den neuesten Durchlauf senden. Jeder Post ist ein Klick.",
	["Adds \"×3\" to joined lines. When the game keeps the numbers hidden, the newest number shows with the count."] = "Fügt zusammengefassten Zeilen „×3“ hinzu. Wenn das Spiel die Zahlen verborgen hält, erscheint die neueste Zahl mit der Anzahl.",
	["Adds Send my alts and Ask the guild buttons to the Guild tab, to swap your characters' names, classes and levels with guild members who use EldoUI. Nothing is sent without your click."] = "Fügt dem Reiter Gilde die Schaltflächen „Meine Twinks senden“ und „Gilde fragen“ hinzu, um Namen, Klassen und Stufen Eurer Charaktere mit Gildenmitgliedern auszutauschen, die EldoUI nutzen. Ohne Euren Klick wird nichts gesendet.",
	["Adds Send my recipes and Ask the guild buttons to the Crafters tab, to swap known recipes with guild members who use EldoUI. Nothing is sent without your click. Off by default."] = "Fügt dem Reiter Handwerker die Schaltflächen „Meine Rezepte senden“ und „Gilde fragen“ hinzu, um bekannte Rezepte mit Gildenmitgliedern auszutauschen, die EldoUI nutzen. Ohne Euren Klick wird nichts gesendet. Standardmäßig aus.",
	["Adds Shopping List, Quick Sell and Cancel Undercut tabs to the auction house. Every post, purchase, cancel and search is one click of yours."] = "Fügt dem Auktionshaus die Reiter Einkaufsliste, Schnellverkauf und Unterbieten abbrechen hinzu. Jedes Einstellen, jeder Kauf, jedes Abbrechen und jede Suche ist ein Klick von Euch.",
	["Adds a note when a vendor pays more than the usual auction price after the auction house takes its share."] = "Fügt eine Notiz hinzu, wenn ein Händler mehr zahlt als der übliche Auktionspreis abzüglich des Anteils des Auktionshauses.",
	["Adds a reminder in Scholomance and Stratholme when you carry an Argent Dawn trinket, have none equipped, and are below Exalted."] = "Fügt in Scholomance und Stratholme eine Erinnerung hinzu, wenn Ihr ein Schmuckstück der Argentumdämmerung dabeihabt, keines angelegt habt und noch nicht Ehrfürchtig seid.",
	["Adds a scroll area of your own (up to four), with its own mover. Send events to it on the Events tab."] = "Fügt einen eigenen Scrollbereich hinzu (bis zu vier), mit eigenem Verschiebefeld. Weist ihm auf dem Reiter Ereignisse Ereignisse zu.",
	["Adds an \"EldoUI\" theme (EldoUI colors, accent and font) to RestedXP's theme list. Pick it in RestedXP's settings. Takes effect after a reload."] = "Fügt der Themenliste von RestedXP ein Thema „EldoUI“ hinzu (EldoUI-Farben, Akzent und Schrift). Wählt es in den Einstellungen von RestedXP. Wirkt nach einem Neuladen.",
	["Adds an empty group with its own mover (Cooldown Group N in move mode)."] = "Fügt eine leere Gruppe mit eigenem Verschiebefeld hinzu (Abklingzeitgruppe N im Verschiebemodus).",
	["Adds every spell of your main cooldown row (Cooldown Manager > Own rows) to the list."] = "Fügt der Liste jeden Zauber Eurer Hauptabklingzeitreihe hinzu (Abklingzeitenmanager > Eigene Reihen).",
	["Adds how many of the item you now carry."] = "Fügt hinzu, wie viele dieses Gegenstands Ihr jetzt dabeihabt.",
	["Adds the count in the guild banks you have opened (cached per guild)."] = "Fügt die Anzahl in den Gildenbanken hinzu, die Ihr geöffnet habt (pro Gilde zwischengespeichert).",
	["Adds the search term to the selected shopping list."] = "Fügt den Suchbegriff der ausgewählten Einkaufsliste hinzu.",
	["Adds what all copies on your characters sell for to the tooltip's value line."] = "Fügt der Wertzeile des Tooltips hinzu, was alle Exemplare auf Euren Charakteren beim Verkauf einbringen.",
	["Adds your other characters' amounts to currency tooltips."] = "Fügt Währungstooltips die Mengen Eurer anderen Charaktere hinzu.",
	["Adept"] = "Fortgeschritten",
	["Advanced: macro conditions and page numbers, for example \"[mod:shift] 2; [form:1] 7\". Checked before the modifier paging."] = "Erweitert: Makrobedingungen und Seitenzahlen, zum Beispiel \"[mod:shift] 2; [form:1] 7\". Wird vor dem Seitenwechsel per Modifikator geprüft.",
	["Advanced: macro conditions ending in show or hide, for example \"[mod:shift] show; hide\". When filled they replace the Show rule. The bar always hides in pet battles."] = "Erweitert: Makrobedingungen, die auf show oder hide enden, zum Beispiel \"[mod:shift] show; hide\". Wenn ausgefüllt, ersetzen sie die Anzeigeregel. In Haustierkämpfen ist die Leiste immer ausgeblendet.",
	["Advanced: macro conditions ending in show or hide; when filled they replace the Show rule. The bar only ever shows when you have stances or forms."] = "Erweitert: Makrobedingungen, die auf show oder hide enden; wenn ausgefüllt, ersetzen sie die Anzeigeregel. Die Leiste erscheint ohnehin nur, wenn Ihr Haltungen oder Gestalten habt.",
	["Advanced: macro conditions ending in show or hide; when filled they replace the Show rule. The bar only ever shows while you have a pet with a bar."] = "Erweitert: Makrobedingungen, die auf show oder hide enden; wenn ausgefüllt, ersetzen sie die Anzeigeregel. Die Leiste erscheint ohnehin nur, solange Ihr einen Begleiter mit Leiste habt.",
	["Adventure"] = "Abenteuer",
	["After a set time"] = "Nach einer festen Zeit",
	["After firing, the trigger waits this long before it can fire again."] = "Nach dem Auslösen wartet der Auslöser so lange, bevor er erneut auslösen kann.",
	["After which queen of the ancient night elves is Azshara named?"] = "Nach welcher Königin der alten Nachtelfen ist Azshara benannt?",
	["After you applied the layout's corner: a layout on the other side of the screen moves Questie's grow corner along. A corner you pick in Questie yourself stays."] = "Nachdem Ihr die Ecke des Layouts übernommen habt: Ein Layout auf der anderen Bildschirmseite verschiebt die Wachstumsecke von Questie mit. Eine Ecke, die Ihr selbst in Questie wählt, bleibt.",
	["After you die, a card with a Tell the guild button. One click writes one line about your death in guild chat; nothing is sent without it."] = "Nach Eurem Tod eine Karte mit der Schaltfläche „Der Gilde sagen“. Ein Klick schreibt eine Zeile über Euren Tod in den Gildenchat; ohne ihn wird nichts gesendet.",
	["After you give an item, posts the item and the player's name to your group. Off by default."] = "Nachdem Ihr einen Gegenstand vergeben habt, werden der Gegenstand und der Name des Spielers in Eurer Gruppe gepostet. Standardmäßig aus.",
	["After you learn a new rank, the old one stays on your bars. EldoUI can offer to move those buttons to the new rank, or move them for you."] = "Nachdem Ihr einen neuen Rang gelernt habt, bleibt der alte auf Euren Leisten. EldoUI kann anbieten, diese Aktionstasten auf den neuen Rang zu setzen, oder es für Euch erledigen.",
	["After you learn a new spell rank, and once at login when lower ranks are on your bars, ask whether to show the changes. Nothing moves until you press Apply in that preview."] = "Nachdem Ihr einen neuen Zauberrang gelernt habt, und einmal beim Einloggen, wenn niedrigere Ränge auf Euren Leisten liegen, wird gefragt, ob die Änderungen angezeigt werden sollen. Nichts wird verschoben, bis Ihr in dieser Vorschau auf Übernehmen drückt.",
	["After you leave"] = "Nach dem Verlassen",
	["After you roll, the bar shows your choice and stays until the game's loot history names the winner, or everyone passed. Without a result it leaves when the roll's time is up."] = "Nach Eurem Wurf zeigt die Leiste Eure Wahl und bleibt, bis der Beuteverlauf des Spiels den Gewinner nennt oder alle gepasst haben. Ohne Ergebnis verschwindet sie, wenn die Wurfzeit abgelaufen ist.",
	["After you send a line in %s, the edit box stays there for the next line. Off: it goes back to the last sticky chat type."] = "Nachdem Ihr eine Zeile in %s gesendet habt, bleibt das Eingabefeld dort für die nächste Zeile. Aus: Es kehrt zur letzten beibehaltenen Chatart zurück.",
	["Again!"] = "Noch einmal!",
	["Against your build: %s"] = "Abweichend von Eurem Build: %s",
	["Agenda"] = "Agenda",
	["Agenda reminder details"] = "Details der Agenda-Erinnerungen",
	["Agenda reminders"] = "Agenda-Erinnerungen",
	["Agi"] = "Bew",
	["Agility"] = "Beweglichkeit",
	["Aid"] = "EH",
	["Aim with the mouse or Left and Right. Click, Space or Up: shoot. P: pause."] = "Zielt mit der Maus oder Links und Rechts. Klick, Leertaste oder Hoch: schießen. P: Pause.",
	["Air Hockey"] = "Airhockey",
	["Airy"] = "Luftig",
	["Alarm when something hits you while you are marked AFK."] = "Alarm, wenn Euch etwas trifft, während Ihr als AFK markiert seid.",
	["Alert for"] = "Warnen bei",
	["Alert keywords"] = "Stichwörter für Hinweise",
	["Alert on your name"] = "Hinweis bei Eurem Namen",
	["Alert sounds"] = "Alarmtöne",
	["Alerts and Banners settings"] = "Einstellungen für Hinweise und Banner",
	["Alerts and filters"] = "Hinweise und Filter",
	["Alerts tab"] = "Reiter Hinweise",
	["Alerts tab off"] = "Reiter Hinweise aus",
	["Alerts tab ready"] = "Reiter Hinweise bereit",
	["Alerts tab status"] = "Status des Reiters Hinweise",
	["All addons"] = "Alle Addons",
	["All bags and the bank in EldoUI windows with categories and a bag bar, item counts across your characters, search with filters, offline viewing and a Blizzard skin mode."] = "Alle Taschen und die Bank in EldoUI-Fenstern mit Kategorien und einer Taschenleiste, Gegenstandszahlen über Eure Charaktere hinweg, Suche mit Filtern, Offline-Ansicht und ein Blizzard-Skin-Modus.",
	["All buttons of the bar in one column."] = "Alle Aktionstasten der Leiste in einer Spalte.",
	["All buttons of the bar in one row."] = "Alle Aktionstasten der Leiste in einer Reihe.",
	["All characters"] = "Alle Charaktere",
	["All chat except your own lines"] = "Gesamter Chat außer Euren eigenen Zeilen",
	["All game colors"] = "Alle Spielfarben",
	["All games"] = "Alle Spiele",
	["All guides"] = "Alle Guides",
	["All home"] = "Alle ablegen",
	["All kinds, icons on the world map and minimap."] = "Alle Arten, Symbole auf Weltkarte und Minikarte.",
	["All off"] = "Alle aus",
	["All offers"] = "Alle Angebote",
	["All on"] = "Alle an",
	["All particles"] = "Alle Partikel",
	["All professions"] = "Alle Berufe",
	["All realms"] = "Alle Realms",
	["All tabs"] = "Alle Reiter",
	["All trees"] = "Alle Bäume",
	["All triggers and settings of this module."] = "Alle Auslöser und Einstellungen dieses Moduls.",
	["All white"] = "Alles weiß",
	["All zones"] = "Alle Zonen",
	["Allow posting stats"] = "Posten von Statistiken erlauben",
	["Allow sending nodes"] = "Senden von Vorkommen erlauben",
	["Along the way"] = "Unterwegs",
	["Also catch disguised spellings"] = "Auch verschleierte Schreibweisen erkennen",
	["Also darken the icon while the target is out of range."] = "Das Symbol auch abdunkeln, solange das Ziel außer Reichweite ist.",
	["Also draws every pack, patrol and your route on that map. Off keeps the map readable; the Dungeons window always shows them for planning."] = "Zeichnet auf dieser Karte auch jede Gegnergruppe, jede Patrouille und Eure Route ein. Aus hält die Karte lesbar; das Fenster Dungeons zeigt sie zur Planung immer.",
	["Also for warriors and rogues"] = "Auch für Krieger und Schurken",
	["Also forget its EldoUI settings"] = "Auch seine EldoUI-Einstellungen vergessen",
	["Also forget their EldoUI settings"] = "Auch ihre EldoUI-Einstellungen vergessen",
	["Also in a party"] = "Auch in einer Gruppe",
	["Also in instances"] = "Auch in Instanzen",
	["Also light up and list macros that show or name a lower rank. A macro changes only when you click its Update button in the macro editor (/eui macros)."] = "Auch Makros hervorheben und auflisten, die einen niedrigeren Rang zeigen oder nennen. Ein Makro ändert sich nur, wenn Ihr im Makroeditor (/eui macros) auf seine Schaltfläche „Aktualisieren“ klickt.",
	["Also light up buttons of Bartender4, ElvUI and Dominos. Blizzard's own bars follow Blizzard UI > Action button look: Improve."] = "Auch Aktionstasten von Bartender4, ElvUI und Dominos hervorheben. Blizzards eigene Leisten folgen Blizzard-UI > Optik der Aktionstasten: Verbessern.",
	["Also list the clicks that open the frame's menu."] = "Auch die Klicks auflisten, die das Menü des Rahmens öffnen.",
	["Also list the raid's main assists."] = "Auch die Hauptassistenten des Schlachtzugs auflisten.",
	["Also outside dungeons"] = "Auch außerhalb von Dungeons",
	["Also play the sound each time a charge of a spell with charges comes back, not only when the first one does."] = "Den Sound auch jedes Mal abspielen, wenn eine Aufladung eines Zaubers mit Aufladungen zurückkommt, nicht nur bei der ersten.",
	["Also show defensives others cast on the member."] = "Auch Verteidigungszauber anzeigen, die andere auf das Mitglied wirken.",
	["Also show mana, rage and energy gains, in the mana color."] = "Auch Mana-, Wut- und Energiegewinne anzeigen, in der Manafarbe.",
	["Also show the cues on buttons of other bar addons. Blizzard's own bars follow Blizzard UI > Action button look: Improve."] = "Die Hinweise auch auf Aktionstasten anderer Leisten-Addons anzeigen. Blizzards eigene Leisten folgen Blizzard-UI > Optik der Aktionstasten: Verbessern.",
	["Also show your combo points under your target's nameplate."] = "Eure Kombopunkte auch unter der Namensplakette Eures Ziels anzeigen.",
	["Also show your gold as a counter."] = "Euer Gold auch als Zähler anzeigen.",
	["Also shows plate numbers in a party or raid, where they include your group's hits."] = "Zeigt Plakettenzahlen auch in einer Gruppe oder einem Schlachtzug, wo sie die Treffer Eurer Gruppe einschließen.",
	["Also with loot toasts"] = "Auch mit Beutehinweisen",
	["Alt list of %s"] = "Twinkliste von %s",
	["Alt lists guild members sent you, or that you imported."] = "Twinklisten, die Gildenmitglieder Euch gesendet haben oder die Ihr importiert habt.",
	["Alt shows"] = "Alt zeigt",
	["Alt+F"] = "Alt+F",
	["Alt+Space"] = "Alt+Leertaste",
	["Alt, every action you know, disenchant up to rare."] = "Alt, jede Aktion, die Ihr kennt, Entzaubern bis Rar.",
	["Alt-click a name to invite"] = "Alt-Klick auf einen Namen lädt ein",
	["Alt-click a player's name in chat to send one group invite. Not in combat. Other clicks on names work as before. Off by default."] = "Alt-Klick auf den Namen eines Spielers im Chat sendet eine Gruppeneinladung. Nicht im Kampf. Andere Klicks auf Namen funktionieren wie bisher. Standardmäßig aus.",
	["Alt-click a slot: every slot with the same item flashes in the bag and bank windows. Nothing else happens with the item."] = "Alt-Klick auf einen Platz: Jeder Platz mit demselben Gegenstand blinkt in den Taschen- und Bankfenstern auf. Sonst passiert nichts mit dem Gegenstand.",
	["Alt-click shows the same item"] = "Alt-Klick zeigt denselben Gegenstand",
