	["Armor and weapons up to the quality cap below. Needs Enchanting."] = "Rüstung und Waffen bis zur Qualitätsgrenze unten. Benötigt Verzauberkunst.",
	["Arrange cooldown icons in your own groups. Off keeps the fixed rows."] = "Ordnet Abklingzeitsymbole in Euren eigenen Gruppen an. Aus behält die festen Reihen.",
	["Arrange the items with the settings below. Off keeps Blizzard's layout from Edit Mode."] = "Ordnet die Elemente mit den Einstellungen unten an. Aus behält Blizzards Anordnung aus dem Bearbeitungsmodus.",
	["Arrow keys move the cursor"] = "Pfeiltasten bewegen den Cursor",
	["Arrow keys or WASD, or click a side of the board: slide. P: pause."] = "Pfeiltasten oder WASD oder Klick auf eine Seite des Bretts: schieben. P: Pause.",
	["Arrow keys or WASD: hop. P: pause."] = "Pfeiltasten oder WASD: hüpfen. P: Pause.",
	["Arrow keys or WASD: turn. P: pause."] = "Pfeiltasten oder WASD: abbiegen. P: Pause.",
	["Arrow keys or WASD: walk. P: pause."] = "Pfeiltasten oder WASD: gehen. P: Pause.",
	["Arrow keys, WASD or a click beside you: walk and push. U: back. R: again. P: pause."] = "Pfeiltasten, WASD oder ein Klick neben Euch: gehen und schieben. U: zurück. R: neu. P: Pause.",
	["Arrow keys, WASD or a click: move. P: pause."] = "Pfeiltasten, WASD oder ein Klick: bewegen. P: Pause.",
	["Arrows and bullets."] = "Pfeile und Kugeln.",
	["As group leader, each reset sends the instance names to group members who run EldoUI, as an addon message (never in a battleground)."] = "Als Gruppenanführer sendet jeder Reset die Instanznamen als Addon-Nachricht an Gruppenmitglieder, die EldoUI nutzen (nie auf einem Schlachtfeld).",
	["As issue"] = "Als Issue",
	["As many columns as fit: level, XP, rested, gold, played, item level, durability, lockouts, bags, mail, professions and last seen."] = "So viele Spalten, wie passen: Stufe, EP, erholt, Gold, Spielzeit, Gegenstandsstufe, Haltbarkeit, Sperren, Taschen, Post, Berufe und zuletzt gesehen.",
	["As of each character's last auction house visit."] = "Stand des letzten Auktionshausbesuchs jedes Charakters.",
	["As set on the Glows page"] = "Wie auf der Seite „Leuchteffekte“ eingestellt",
	["Ascending"] = "Aufsteigend",
	["Ask"] = "Fragen",
	["Ask and share camps"] = "Lager erfragen und teilen",
	["Ask and share camps is unchecked on the Camp Helper page (%s)."] = "„Lager erfragen und teilen“ ist auf der Seite Lagerhelfer nicht angehakt (%s).",
	["Ask and share with"] = "Erfragen und teilen mit",
	["Ask for a camp"] = "Nach einem Lager fragen",
	["Ask for each quest"] = "Bei jeder Quest fragen",
	["Ask for played time at login"] = "Beim Einloggen nach der Spielzeit fragen",
	["Ask me"] = "Mich fragen",
	["Ask me: while you know a fire, a toast lets you send it with one click. Never: requests are ignored."] = "Mich fragen: Solange Ihr ein Feuer kennt, könnt Ihr es über einen Hinweis mit einem Klick senden. Nie: Anfragen werden ignoriert.",
	["Ask your guild or group for a camp and share yours, with members who use EldoUI. Nothing is sent until you click Ask or Share, and nothing is answered for you."] = "Fragt Eure Gilde oder Gruppe nach einem Lager und teilt Eures mit Mitgliedern, die EldoUI nutzen. Nichts wird gesendet, bis Ihr auf Fragen oder Teilen klickt, und nichts wird für Euch beantwortet.",
	["Asked your group for a camp. Members who use EldoUI choose whether to answer."] = "Eure Gruppe nach einem Lager gefragt. Mitglieder, die EldoUI nutzen, entscheiden, ob sie antworten.",
	["Asked your guild for a camp. Members who use EldoUI choose whether to answer."] = "Eure Gilde nach einem Lager gefragt. Mitglieder, die EldoUI nutzen, entscheiden, ob sie antworten.",
	["Asked your guild for their alt lists. Answers show in the Guild tab."] = "Eure Gilde nach ihren Twinklisten gefragt. Antworten erscheinen im Reiter Gilde.",
	["Asked your guild for their recipe lists. Answers show in the Crafters tab."] = "Eure Gilde nach ihren Rezeptlisten gefragt. Antworten erscheinen im Reiter Handwerker.",
	["Asks BigWigs, in its own popup, to switch to an \"EldoUI - <layout>\" profile with its bars, messages and countdown on EldoUI's movers. Declining changes nothing."] = "Bittet BigWigs in seinem eigenen Popup, zu einem Profil \"EldoUI - <layout>\" zu wechseln, mit seinen Leisten, Nachrichten und dem Countdown auf den Verschiebefeldern von EldoUI. Ablehnen ändert nichts.",
	["Asks for played time right after a level-up, so the level log has the exact value instead of an estimate from the login read."] = "Fragt direkt nach einem Stufenaufstieg nach der Spielzeit, damit das Stufenprotokoll den genauen Wert hat statt einer Schätzung vom Einloggen.",
	["Asks guild members who use EldoUI and share their alts to send you their list. Their answer needs their click too."] = "Bittet Gildenmitglieder, die EldoUI nutzen und ihre Twinks teilen, Euch ihre Liste zu senden. Auch ihre Antwort braucht ihren Klick.",
	["Asks guild members who use EldoUI and share their recipes to send you their list. Their answer needs their click too."] = "Bittet Gildenmitglieder, die EldoUI nutzen und ihre Rezepte teilen, Euch ihre Liste zu senden. Auch ihre Antwort braucht ihren Klick.",
	["Asks once, then removes the character picked above."] = "Fragt einmal nach und entfernt dann den oben gewählten Charakter.",
	["Asks the auction house once for every listing and saves the lowest price of each item. Blizzard allows one full scan every 15 minutes."] = "Fragt das Auktionshaus einmal nach jedem Angebot ab und speichert den niedrigsten Preis jedes Gegenstands. Blizzard erlaubt alle 15 Minuten einen vollständigen Scan.",
	["Asks the server for your played time a few seconds after login, so the window can show and total it."] = "Fragt den Server einige Sekunden nach dem Einloggen nach Eurer Spielzeit, damit das Fenster sie anzeigen und summieren kann.",
	["Asks your guild or group for a camp now. Members who use EldoUI choose whether to answer."] = "Fragt Eure Gilde oder Gruppe jetzt nach einem Lager. Mitglieder, die EldoUI nutzen, entscheiden, ob sie antworten.",
	["Asks your guild or group for a camp. Members who use EldoUI choose whether to answer."] = "Fragt Eure Gilde oder Gruppe nach einem Lager. Mitglieder, die EldoUI nutzen, entscheiden, ob sie antworten.",
