	["Blizzard art"] = "Blizzard-Grafik",
	["Blizzard art keeps Blizzard's bar textures."] = "Blizzard-Grafik behält Blizzards Leistentexturen.",
	["Blizzard art keeps Blizzard's fill textures; the others use the texture below."] = "Blizzard-Grafik behält Blizzards Fülltexturen; die anderen nutzen die Textur unten.",
	["Blizzard bank"] = "Blizzard-Bank",
	["Blizzard class background"] = "Blizzard-Klassenhintergrund",
	["Blizzard combat text"] = "Blizzard-Kampftext",
	["Blizzard decides what the meter counts. Its own settings (Edit Mode and the window's cog menu) still apply."] = "Blizzard entscheidet, was der Messer zählt. Seine eigenen Einstellungen (Bearbeitungsmodus und das Zahnradmenü des Fensters) gelten weiterhin.",
	["Blizzard draws these into an anchor on the frame; EldoUI never sees them."] = "Blizzard zeichnet diese in einen Anker am Rahmen; EldoUI sieht sie nie.",
	["Blizzard frames that EldoUI hides or replaces can't be grabbed in Edit Mode, nor the empty Blizzard bar left behind when EldoUI carries the micro menu or bag buttons. Drag EldoUI's own box instead."] = "Blizzard-Rahmen, die EldoUI ausblendet oder ersetzt, lassen sich im Bearbeitungsmodus nicht greifen, ebenso wenig die leere Blizzard-Leiste, die zurückbleibt, wenn EldoUI das Mikromenü oder die Taschenschaltflächen übernimmt. Zieht stattdessen das Feld von EldoUI.",
	["Blizzard frames whose position EldoUI sets get a label, so you know an Edit Mode drag won't stick."] = "Blizzard-Rahmen, deren Position EldoUI festlegt, erhalten eine Beschriftung, damit Ihr wisst, dass ein Ziehen im Bearbeitungsmodus nicht hält.",
	["Blizzard frames whose position EldoUI sets get a label: dragging them in Edit Mode won't stick."] = "Blizzard-Rahmen, deren Position EldoUI festlegt, erhalten eine Beschriftung: Sie im Bearbeitungsmodus zu ziehen, hält nicht.",
	["Blizzard frames, skinned"] = "Blizzard-Rahmen, mit Skin",
	["Blizzard frames, untouched"] = "Blizzard-Rahmen, unverändert",
	["Blizzard gold"] = "Blizzard-Gold",
	["Blizzard import string for the first Legacy tree: %s"] = "Blizzard-Importstring für den ersten Vermächtnisbaum: %s",
	["Blizzard party and raid switches"] = "Blizzard-Schalter für Gruppe und Schlachtzug",
	["Blizzard roll frame scale"] = "Skalierung des Blizzard-Wurffensters",
	["Blizzard setting"] = "Blizzard-Einstellung",
	["Blizzard window scale"] = "Skalierung des Blizzard-Fensters",
	["Blizzard's Buy tab"] = "Blizzards Reiter Kaufen",
	["Blizzard's Cooldown Manager isn't available on this character."] = "Blizzards Abklingzeitenmanager ist auf diesem Charakter nicht verfügbar.",
	["Blizzard's Cooldown Manager isn't loaded."] = "Blizzards Abklingzeitenmanager ist nicht geladen.",
	["Blizzard's Cooldown Manager settings open after combat."] = "Die Einstellungen von Blizzards Abklingzeitenmanager öffnen sich nach dem Kampf.",
	["Blizzard's Cooldown Manager shows no spells here, so EldoUI's own cooldown rows take its place. They stay empty until you pick your spells for the Main and Utility rows in /eui cooldownmanager."] = "Blizzards Abklingzeitenmanager zeigt hier keine Zauber, daher nehmen EldoUIs eigene Abklingzeitreihen seinen Platz ein. Sie bleiben leer, bis Ihr in /eui cooldownmanager Eure Zauber für die Reihen Haupt und Nützlich wählt.",
	["Blizzard's Edit Mode for Blizzard's frames only; EldoUI's frames move with /eui move."] = "Blizzards Bearbeitungsmodus nur für Blizzards Rahmen; die Rahmen von EldoUI verschiebt Ihr mit /eui move.",
	["Blizzard's Legacy window"] = "Blizzards Vermächtnisfenster",
	["Blizzard's action bars come fully back after a reload."] = "Blizzards Aktionsleisten sind nach einem Neuladen vollständig zurück.",
	["Blizzard's auction window. Its size, dragging and resets are on the Move windows page; where it opens is its mover in move mode."] = "Blizzards Auktionsfenster. Größe, Ziehen und Zurücksetzen stehen auf der Seite Fenster verschieben; wo es sich öffnet, legt sein Verschiebefeld im Verschiebemodus fest.",
	["Blizzard's bag windows"] = "Blizzards Taschenfenster",
	["Blizzard's bar"] = "Blizzards Leiste",
	["Blizzard's bar stays next to EldoUI's."] = "Blizzards Leiste bleibt neben der von EldoUI.",
	["Blizzard's bars under your character (Edit Mode: Personal Resource Display). Skin restyles it instead."] = "Blizzards Leisten unter Eurem Charakter (Bearbeitungsmodus: Persönliche Ressourcenanzeige). Skin gestaltet sie stattdessen um.",
	["Blizzard's breath, fatigue and feign death bars stay hidden."] = "Blizzards Leisten für Atem, Erschöpfung und Totstellen bleiben ausgeblendet.",
	["Blizzard's bright tip at the end of each buff bar."] = "Blizzards helle Spitze am Ende jeder Stärkungsleiste.",
	["Blizzard's cast bars too"] = "Auch Blizzards Zauberleisten",
	["Blizzard's class background with quality borders only."] = "Blizzards Klassenhintergrund nur mit Qualitätsrändern.",
	["Blizzard's compact raid frame proportions, two groups per column, power bars only on healers."] = "Die Proportionen von Blizzards kompakten Schlachtzugsrahmen, zwei Gruppen pro Spalte, Ressourcenleisten nur bei Heilern.",
	["Blizzard's countdown numbers on the icon."] = "Blizzards Countdown-Zahlen auf dem Symbol.",
	["Blizzard's damage meter isn't available on this character."] = "Blizzards Schadensmesser ist auf diesem Charakter nicht verfügbar.",
	["Blizzard's damage numbers are on too, so each hit shows twice. Turn on \"Let EldoUI change this\" on the Blizzard combat text tab."] = "Blizzards Schadenszahlen sind ebenfalls an, daher erscheint jeder Treffer doppelt. Schaltet auf dem Reiter Blizzard-Kampftext „EldoUI dies ändern lassen“ ein.",
	["Blizzard's floating combat text is hidden (Blizzard combat text tab)."] = "Blizzards schwebender Kampftext ist ausgeblendet (Reiter Blizzard-Kampftext).",
	["Blizzard's frames"] = "Blizzards Rahmen",
	["Blizzard's loot history gets the EldoUI look with the Skin switch, and remembers where you drag it with the Move switch."] = "Blizzards Beuteverlauf erhält mit dem Skin-Schalter die EldoUI-Optik und merkt sich mit dem Schalter „Verschieben“, wohin Ihr ihn zieht.",
	["Blizzard's main-hand swing bar stays hidden."] = "Blizzards Schlagleiste für die Waffenhand bleibt ausgeblendet.",
	["Blizzard's numbers over enemies"] = "Blizzards Zahlen über Gegnern",
	["Blizzard's off-hand swing bar stays hidden."] = "Blizzards Schlagleiste für die Schildhand bleibt ausgeblendet.",
	["Blizzard's option %s. \"Blizzard setting\" follows the game's options, but hides it while hit numbers on plates are on, so a hit shows once."] = "Blizzards Option %s. „Blizzard-Einstellung“ folgt den Spieloptionen, blendet sie aber aus, solange Trefferzahlen auf Plaketten an sind, damit ein Treffer nur einmal erscheint.",
	["Blizzard's option %s. \"Blizzard setting\" leaves it as you set it in the game's options."] = "Blizzards Option %s. „Blizzard-Einstellung“ lässt sie so, wie Ihr sie in den Spieloptionen eingestellt habt.",
	["Blizzard's own"] = "Blizzards eigene",
	["Blizzard's own combat text options. \"Blizzard setting\" keeps your value from Blizzard's options; Blizzard default puts your values back."] = "Blizzards eigene Kampftextoptionen. „Blizzard-Einstellung“ behält Euren Wert aus Blizzards Optionen; Blizzard-Standard setzt Eure Werte zurück.",
	["Blizzard's own countdown with the big numbers (battleground gates, pull countdown). Skin, move or hide it under Blizzard UI > Combat HUD > Start countdown."] = "Blizzards eigener Countdown mit den großen Zahlen (Schlachtfeldtore, Pull-Countdown). Unter Blizzard-UI > Kampf-HUD > Start-Countdown mit Skin versehen, verschieben oder ausblenden.",
	["Blizzard's own damage and healing numbers over targets: your own hits, from the game."] = "Blizzards eigene Schadens- und Heilungszahlen über Zielen: Eure eigenen Treffer, vom Spiel.",
	["Blizzard's own loot and roll frames in the EldoUI look."] = "Blizzards eigene Beute- und Wurffenster in der EldoUI-Optik.",
	["Blizzard's own option for coloring names by class in every channel."] = "Blizzards eigene Option, Namen in jedem Kanal nach Klasse einzufärben.",
	["Blizzard's own swing timer shows when Interface > Combat > Swing Timer is on. Its Edit Mode visibility still applies."] = "Blizzards eigener Schlagtimer erscheint, wenn Interface > Kampf > Schlagtimer an ist. Seine Sichtbarkeit im Bearbeitungsmodus gilt weiterhin.",
	["Blizzard's own timestamp setting (Social options)."] = "Blizzards eigene Zeitstempel-Einstellung (Optionen Soziales).",
	["Blizzard's party and raid frames too"] = "Auch Blizzards Gruppen- und Schlachtzugsrahmen",
	["Blizzard's quest timer stays hidden."] = "Blizzards Questtimer bleibt ausgeblendet.",
	["Blizzard's raid manager on the left edge. Hidden keeps markers and ready check in EldoUI's Raid Tools. Needs the raid frames switch on the Blizzard UI page; Skinned also needs its Skin switch."] = "Blizzards Schlachtzugsverwaltung am linken Rand. Ausgeblendet behält Markierungen und Bereitschaftscheck in den Schlachtzugswerkzeugen von EldoUI. Braucht den Schalter für Schlachtzugsrahmen auf der Seite Blizzard-UI; „Mit Skin“ braucht zusätzlich dessen Skin-Schalter.",
	["Blizzard's ranged swing bar stays hidden."] = "Blizzards Schlagleiste für Distanz bleibt ausgeblendet.",
	["Blizzard's roll frames are hidden and EldoUI's roll bars are off, so loot rolls are not shown. Type %s for EldoUI's bars."] = "Blizzards Wurffenster sind ausgeblendet und EldoUIs Wurfleisten sind aus, daher werden Beutewürfe nicht angezeigt. Gebt %s für EldoUIs Leisten ein.",
	["Blizzard's roll frames, Blizzard's in the EldoUI look, or EldoUI's roll bars. Going back from EldoUI's bars takes effect after a reload."] = "Blizzards Wurffenster, Blizzards in der EldoUI-Optik oder EldoUIs Wurfleisten. Der Wechsel zurück von EldoUIs Leisten wirkt nach einem Neuladen.",
	["Blizzard's setting"] = "Blizzards Einstellung",
	["Blizzard's setting follows the game's own class color option. Class colors colors every player by class even when that option is off."] = "Blizzards Einstellung folgt der eigenen Klassenfarbenoption des Spiels. Klassenfarben färbt jeden Spieler nach Klasse, auch wenn diese Option aus ist.",
	["Blizzard's settings"] = "Blizzards Einstellungen",
	["Blizzard's start countdown"] = "Blizzards Start-Countdown",
	["Blizzard's totem timers (the totem bar for placing totems is under Action Bars)."] = "Blizzards Totemtimer (die Totemleiste zum Setzen von Totems steht unter Aktionsleisten).",
	["Blizzard's vehicle bar"] = "Blizzards Fahrzeugleiste",
	["Blizzard's window, Blizzard's window in the EldoUI look, or EldoUI's own quality-colored window."] = "Blizzards Fenster, Blizzards Fenster in der EldoUI-Optik oder EldoUIs eigenes, nach Qualität gefärbtes Fenster.",
	["Blizzard's windows (skin and move)"] = "Blizzards Fenster (Skin und Verschieben)",
