	["Click Casting"] = "Klickzauber",
	["Click Refresh to load your auctions."] = "Klickt auf Aktualisieren, um Eure Auktionen zu laden.",
	["Click a brazier, or arrow keys and Space. P: pause."] = "Klickt auf eine Kohlenpfanne oder nutzt die Pfeiltasten und die Leertaste. P: Pause.",
	["Click a burrow, or the number keys as on a number pad. P: pause."] = "Klickt auf einen Bau oder nutzt die Zifferntasten wie auf einem Ziffernblock. P: Pause.",
	["Click a card to turn it. Arrow keys and Space work too."] = "Klickt auf eine Karte, um sie umzudrehen. Pfeiltasten und Leertaste funktionieren auch.",
	["Click a card, then where it goes. Right-click or double-click: send home. Space: draw. U: undo. A: all home."] = "Klickt auf eine Karte, dann auf ihr Ziel. Rechts- oder Doppelklick: auf die Ablage. Leertaste: ziehen. U: rückgängig. A: alle auf die Ablage.",
	["Click a cart, then where it goes. Arrow keys slide it, Space picks the next. U: undo. R: start over."] = "Klickt auf einen Karren, dann auf sein Ziel. Pfeiltasten schieben ihn, die Leertaste wählt den nächsten. U: rückgängig. R: neu beginnen.",
	["Click a color to change it. Game puts the game's own color back. Numbered channels keep their color when their number changes."] = "Klickt auf eine Farbe, um sie zu ändern. Spiel stellt die Farbe des Spiels wieder her. Nummerierte Kanäle behalten ihre Farbe, wenn sich ihre Nummer ändert.",
	["Click a column, or Left, Right and Space (or 1 to 7). P: pause."] = "Klickt auf eine Spalte oder nutzt Links, Rechts und die Leertaste (oder 1 bis 7). P: Pause.",
	["Click a line to try it in the search box."] = "Klickt auf eine Zeile, um sie im Suchfeld auszuprobieren.",
	["Click a name or press 1 to 4. P: pause."] = "Klickt auf einen Namen oder drückt 1 bis 4. P: Pause.",
	["Click a note, arrow or line to delete it."] = "Klickt auf eine Notiz, einen Pfeil oder eine Linie, um sie zu löschen.",
	["Click a pack: it becomes the next pull, or comes out of the route when it is in it. Shift-click: it joins the pull picked in the list."] = "Klickt auf eine Gegnergruppe: Sie wird zum nächsten Pull oder fliegt aus der Route, wenn sie schon darin ist. Umschaltklick: Sie kommt zu dem Pull, der in der Liste gewählt ist.",
	["Click a piece in line with the gap, or the arrow keys. P: pause."] = "Klickt auf ein Teil in einer Linie mit der Lücke oder nutzt die Pfeiltasten. P: Pause.",
	["Click a piece, then where it goes. P: pause."] = "Klickt auf einen Stein, dann auf sein Ziel. P: Pause.",
	["Click a piece, then where it goes. U: take back. P: pause."] = "Klickt auf eine Figur, dann auf ihr Ziel. U: Zug zurücknehmen. P: Pause.",
	["Click a point to place; click a piece, then where it goes. P: pause."] = "Klickt auf einen Punkt, um zu setzen; klickt auf einen Stein, dann auf sein Ziel. P: Pause.",
	["Click a profession to see its recipes."] = "Klickt auf einen Beruf, um seine Rezepte zu sehen.",
	["Click a route to keep it or dismiss it. Nothing is added to your routes until you keep one."] = "Klickt auf eine Route, um sie zu behalten oder zu verwerfen. Zu Euren Routen kommt nichts hinzu, bis Ihr eine behaltet.",
	["Click a route to open it on the map. Right-click for rename, export and delete."] = "Klickt auf eine Route, um sie auf der Karte zu öffnen. Rechtsklick zum Umbenennen, Exportieren und Löschen.",
	["Click a rune, then move the pointer to draw. Arrow keys and Space work too. P: pause."] = "Klickt auf eine Rune und bewegt dann den Zeiger, um zu zeichnen. Pfeiltasten und Leertaste funktionieren auch. P: Pause.",
	["Click a rune, then the empty hole it jumps to. Arrow keys and Space work too. U: undo. P: pause."] = "Klickt auf eine Rune, dann auf das leere Loch, in das sie springt. Pfeiltasten und Leertaste funktionieren auch. U: rückgängig. P: Pause.",
	["Click a square of enemy waters. R: new fleet before the first shot. P: pause."] = "Klickt auf ein Feld in den feindlichen Gewässern. R: neue Flotte vor dem ersten Schuss. P: Pause.",
	["Click a square to pick a blessing."] = "Klickt auf ein Feld, um einen Segen zu wählen.",
	["Click a square with a dot. P: pause."] = "Klickt auf ein Feld mit einem Punkt. P: Pause.",
	["Click a stone, then a number key or the runes below. Backspace clears. P: pause."] = "Klickt auf einen Stein, dann auf eine Zifferntaste oder die Runen unten. Rücktaste löscht. P: Pause.",
	["Click a word's first letter."] = "Klickt auf den ersten Buchstaben eines Wortes.",
	["Click again"] = "Erneut klicken",
	["Click an answer or press 1 to 4. P: pause."] = "Klickt auf eine Antwort oder drückt 1 bis 4. P: Pause.",
	["Click an empty square. P: pause."] = "Klickt auf ein leeres Feld. P: Pause.",
	["Click between two posts to set a fence."] = "Klickt zwischen zwei Pfosten, um einen Zaun zu setzen.",
	["Click between two posts. P: pause."] = "Klickt zwischen zwei Pfosten. P: Pause.",
	["Click dice to keep them, roll again, or pick a box."] = "Klickt auf Würfel, um sie zu behalten, würfelt erneut oder wählt ein Feld.",
	["Click here with a mouse button, or hover and press a key"] = "Hier mit einer Maustaste klicken oder mit der Maus darauf zeigen und eine Taste drücken",
	["Click one of your pits, or 1 to 6. P: pause."] = "Klickt auf eine Eurer Mulden oder drückt 1 bis 6. P: Pause.",
	["Click or press %d"] = "Klicken oder %d drücken",
	["Click or press Esc to close. Moving clears Away."] = "Klicken oder Esc drücken zum Schließen. Bewegung beendet Abwesend.",
	["Click the first and the last letter of a word. Arrow keys and Space work too. P: pause."] = "Klickt auf den ersten und den letzten Buchstaben eines Wortes. Pfeiltasten und Leertaste funktionieren auch. P: Pause.",
	["Click the map to write a note there. Click a note to change its text; an empty text deletes it."] = "Klickt auf die Karte, um dort eine Notiz zu schreiben. Klickt auf eine Notiz, um ihren Text zu ändern; ein leerer Text löscht sie.",
	["Click the map where the place lies. P: pause."] = "Klickt auf die Stelle der Karte, an der der Ort liegt. P: Pause.",
	["Click the runes, or their number keys. P: pause."] = "Klickt auf die Runen oder drückt ihre Zifferntasten. P: Pause.",
	["Click to check this off when it is done. Click again to uncheck it."] = "Klicken, um dies abzuhaken, wenn es erledigt ist. Erneut klicken, um den Haken zu entfernen.",
	["Click to copy"] = "Klicken zum Kopieren",
