	["Draw"] = "Zeichnen",
	["Draw a background behind the panel. Off leaves only the text, which can be hard to read on a bright minimap."] = "Zeichnet einen Hintergrund hinter das Panel. Aus lässt nur den Text, der auf einer hellen Minikarte schwer lesbar sein kann.",
