	["Edit Mode"] = "Bearbeitungsmodus",
	["Edit Mode and EldoUI agree: no frame is placed by both."] = "Bearbeitungsmodus und EldoUI sind sich einig: Kein Rahmen wird von beiden platziert.",
	["Edit Mode brings EldoUI's move tools along, so Blizzard's and EldoUI's frames are placed in one go. /eui move has the same tools."] = "Der Bearbeitungsmodus bringt die Verschiebewerkzeuge von EldoUI mit, sodass Blizzards und EldoUIs Rahmen in einem Zug platziert werden. /eui move hat dieselben Werkzeuge.",
	["Edit Mode layout %s: EldoUI frames moved to their spots for it."] = "Layout %s im Bearbeitungsmodus: EldoUI-Rahmen an ihre Plätze dafür verschoben.",
	["Edit bindings"] = "Belegungen bearbeiten",
	["Edit box height"] = "Höhe des Eingabefelds",
