	["EldoUI bar"] = "EldoUI-Leiste",
	["EldoUI bar style"] = "EldoUI-Leistenstil",
	["EldoUI bar: the pet bar buttons in an EldoUI frame you can move, resize and fade (needs the Replace switch). Blizzard's bar: left as it is. Hidden: needs the Hide switch."] = "EldoUI-Leiste: die Tasten der Begleiterleiste in einem EldoUI-Rahmen, den Ihr verschieben, skalieren und ausblenden könnt (braucht den Schalter Ersetzen). Blizzards Leiste: bleibt, wie sie ist. Ausgeblendet: braucht den Schalter Ausblenden.",
	["EldoUI bar: the stance bar buttons in an EldoUI frame you can move, resize and fade (needs the Replace switch). Blizzard's bar: left as it is. Hidden: needs the Hide switch."] = "EldoUI-Leiste: die Tasten der Haltungsleiste in einem EldoUI-Rahmen, den Ihr verschieben, skalieren und ausblenden könnt (braucht den Schalter Ersetzen). Blizzards Leiste: bleibt, wie sie ist. Ausgeblendet: braucht den Schalter Ausblenden.",
	["EldoUI buffs"] = "EldoUI-Stärkungszauber",
	["EldoUI changes Blizzard's party and raid frames only as allowed on the Blizzard UI page. Off there keeps them as Blizzard made them."] = "EldoUI ändert Blizzards Gruppen- und Schlachtzugsrahmen nur so weit, wie auf der Seite Blizzard-UI erlaubt. Aus belässt sie dort so, wie Blizzard sie gemacht hat.",
	["EldoUI changes it"] = "EldoUI ändert es",
	["EldoUI combo points"] = "EldoUI-Kombopunkte",
	["EldoUI command"] = "EldoUI-Befehl",
	["EldoUI cooldown text"] = "EldoUI-Abklingzeittext",
	["EldoUI could not move a spell rank on your action bars and stops upgrading them automatically until you log in again."] = "EldoUI konnte einen Zauberrang auf Euren Aktionsleisten nicht verschieben und verbessert sie nicht mehr automatisch, bis Ihr Euch erneut einloggt.",
	["EldoUI debuffs"] = "EldoUI-Schwächungszauber",
	["EldoUI font, bar texture, 1 px border, backdrop and accent on DBM's timer bars, and the EldoUI font on warnings and the info frame. Off: DBM's own look comes back."] = "EldoUI-Schriftart, Leistentextur, 1-px-Rand, Hintergrund und Akzent auf den Timerleisten von DBM sowie die EldoUI-Schriftart auf Warnungen und dem Infofenster. Aus: Die eigene Optik von DBM kehrt zurück.",
	["EldoUI format"] = "EldoUI-Format",
	["EldoUI format: seconds, minutes and hours with colors and tenths at the end. Game setting: follows Options > Action Bars > Show cooldown numbers. Off: no numbers."] = "EldoUI-Format: Sekunden, Minuten und Stunden mit Farben und Zehnteln am Ende. Spieleinstellung: folgt Optionen > Aktionsleisten > Abklingzeitzahlen anzeigen. Aus: keine Zahlen.",
	["EldoUI frame"] = "EldoUI-Rahmen",
	["EldoUI frames"] = "EldoUI-Rahmen",
	["EldoUI handles this viewer"] = "EldoUI steuert diese Anzeige",
	["EldoUI has no map for this place yet. The pulls of its route are listed on the right."] = "EldoUI hat für diesen Ort noch keine Karte. Die Pulls seiner Route stehen rechts.",
	["EldoUI has no record of Guidelime's earlier spot, so the window stays where it is. Guidelime's own Reset position button moves it."] = "EldoUI hat keine Aufzeichnung von Guidelimes früherem Platz, daher bleibt das Fenster, wo es ist. Guidelimes eigene Schaltfläche Reset position verschiebt es.",
	["EldoUI has nothing to undo here."] = "EldoUI hat hier nichts rückgängig zu machen.",
	["EldoUI hides or replaces:"] = "EldoUI blendet aus oder ersetzt:",
	["EldoUI holds none of your camera settings."] = "EldoUI hält keine Eurer Kameraeinstellungen.",
	["EldoUI layout"] = "EldoUI-Layout",
	["EldoUI leaves Details, RestedXP, BigWigs and Questie exactly as they are."] = "EldoUI lässt Details, RestedXP, BigWigs und Questie genau so, wie sie sind.",
	["EldoUI line"] = "EldoUI-Linie",
	["EldoUI look"] = "EldoUI-Optik",
	["EldoUI look for the character window"] = "EldoUI-Optik für das Charakterfenster",
	["EldoUI look on DBM's bars and texts; DBM keeps its own positions."] = "EldoUI-Optik auf den Leisten und Texten von DBM; DBM behält seine eigenen Positionen.",
	["EldoUI look: flat bars, theme font and texture, a see-through box behind each window."] = "EldoUI-Optik: flache Leisten, Themenschrift und -textur, ein durchscheinendes Feld hinter jedem Fenster.",
	["EldoUI look: font, bar texture, 1 px border, backdrop and accent"] = "EldoUI-Optik: Schriftart, Leistentextur, 1-px-Rand, Hintergrund und Akzent",
	["EldoUI module"] = "EldoUI-Modul",
	["EldoUI mover"] = "EldoUI-Verschiebefeld",
	["EldoUI movers, attach points and the icon grid below. Off keeps Blizzard's Edit Mode position and layout."] = "EldoUI-Verschiebefelder, Ankerpunkte und das Symbolraster unten. Aus behält Position und Layout aus Blizzards Bearbeitungsmodus.",
	["EldoUI never changes DBM's sounds, voices, comms, raid icons, pull timer or boss settings. Timer area sizes are on the Integrations page."] = "EldoUI ändert nie die Töne, Stimmen, Kommunikation, Schlachtzugssymbole, den Pull-Timer oder die Bosseinstellungen von DBM. Die Größen der Timerbereiche stehen auf der Seite Integrationen.",
	["EldoUI never releases your spirit for you: the buttons only work when you click them. The death popup is skinned with the dialogs."] = "EldoUI lässt Euren Geist nie für Euch frei: Die Schaltflächen wirken nur, wenn Ihr sie anklickt. Das Todesfenster erhält mit den Dialogen einen Skin.",
	["EldoUI options"] = "EldoUI-Optionen",
	["EldoUI panel for the death recap, flat ghost button."] = "EldoUI-Panel für den Todesrückblick, flache Geist-Schaltfläche.",
	["EldoUI panel next to Edit Mode"] = "EldoUI-Panel neben dem Bearbeitungsmodus",
	["EldoUI places this"] = "EldoUI platziert dies",
	["EldoUI places:"] = "EldoUI platziert:",
	["EldoUI sets nothing in its DBM profile; switch back to your own profile on this page."] = "EldoUI setzt nichts in seinem DBM-Profil; wechselt auf dieser Seite zurück zu Eurem eigenen Profil.",
	["EldoUI settings page"] = "EldoUI-Einstellungsseite",
	["EldoUI settings re-applied to the DBM profile %s (%d settings)."] = "EldoUI-Einstellungen erneut auf das DBM-Profil %s angewendet (%d Einstellungen).",
	["EldoUI shows \"Name the Title\" and the level, specialization and class in class color."] = "EldoUI zeigt „Name mit Titel“ sowie Stufe, Spezialisierung und Klasse in Klassenfarbe.",
	["EldoUI shows your combat text now. Hide Blizzard's own text around your character? Your damage numbers over enemies stay."] = "EldoUI zeigt jetzt Euren Kampftext. Blizzards eigenen Text um Euren Charakter ausblenden? Eure Schadenszahlen über Feinden bleiben.",
	["EldoUI skin"] = "EldoUI-Skin",
	["EldoUI skin dresses the game's guild bank window (Bank switch with Skin on). EldoUI window shows the guild bank in EldoUI's own window, on the Guild bank mover."] = "EldoUI-Skin kleidet das Gildenbankfenster des Spiels ein (Schalter Bank mit Skin an). EldoUI-Fenster zeigt die Gildenbank in einem eigenen Fenster von EldoUI, am Verschiebefeld Gildenbank.",
	["EldoUI skins and places Blizzard's death recap window. Off leaves it to Blizzard."] = "EldoUI versieht Blizzards Todesrückblick-Fenster mit Skin und platziert es. Aus überlässt es Blizzard.",
	["EldoUI skins and places the breath, fatigue and feign death bars. Off leaves them to Blizzard."] = "EldoUI versieht die Atem-, Erschöpfungs- und Totstellen-Leisten mit Skin und platziert sie. Aus überlässt sie Blizzard.",
	["EldoUI skins and places the ghost button. Off leaves it to Blizzard."] = "EldoUI versieht die Geist-Schaltfläche mit Skin und platziert sie. Aus überlässt sie Blizzard.",
	["EldoUI skins the quest timer and moves it out of the objective tracker onto its own mover. Off leaves it to Blizzard."] = "EldoUI versieht den Questtimer mit Skin und verschiebt ihn aus der Zielverfolgung auf ein eigenes Verschiebefeld. Aus überlässt ihn Blizzard.",
	["EldoUI theme"] = "EldoUI-Thema",
	["EldoUI theme: pick it in RestedXP's theme list."] = "EldoUI-Thema: Wählt es in der Themenliste von RestedXP.",
	["EldoUI timestamps"] = "EldoUI-Zeitstempel",
	["EldoUI unit frames too"] = "Auch EldoUI-Einheitenrahmen",
	["EldoUI window"] = "EldoUI-Fenster",
	["EldoUI windows and a compact loot feed of everything you gain, repeats added up."] = "EldoUI-Fenster und ein kompakter Beute-Feed von allem, was Ihr erhaltet, Wiederholungen zusammengezählt.",
	["EldoUI windows without toasts."] = "EldoUI-Fenster ohne Hinweise.",
	["EldoUI's DBM setup needs an update for DBM %s (%d settings skipped)."] = "EldoUIs DBM-Einrichtung braucht ein Update für DBM %s (%d Einstellungen übersprungen).",
	["EldoUI's Edit Mode settings: snapping, nudge step, conflicts and style presets."] = "EldoUIs Einstellungen für den Bearbeitungsmodus: Einrasten, Schrittweite, Konflikte und Stilvorlagen.",
	["EldoUI's Nameplates module is off: the numbers hang on Blizzard's plates."] = "EldoUIs Modul Namensplaketten ist aus: Die Zahlen hängen an Blizzards Plaketten.",
	["EldoUI's auction tabs"] = "EldoUIs Auktionsreiter",
	["EldoUI's frames can be dragged inside Blizzard's Edit Mode."] = "EldoUIs Rahmen lassen sich in Blizzards Bearbeitungsmodus ziehen.",
	["EldoUI's frames get a box you can drag, like Blizzard's."] = "EldoUIs Rahmen erhalten ein Feld zum Ziehen, wie die von Blizzard.",
	["EldoUI's frames inside Blizzard's Edit Mode, positions per Edit Mode layout, and warnings when both place the same frame."] = "EldoUIs Rahmen in Blizzards Bearbeitungsmodus, Positionen pro Layout des Bearbeitungsmodus und Warnungen, wenn beide denselben Rahmen platzieren.",
	["EldoUI's frames move here too: drag a box, or click it for exact X and Y."] = "EldoUIs Rahmen lassen sich auch hier verschieben: Zieht ein Feld oder klickt darauf für exaktes X und Y.",
	["EldoUI's frames move here too: drag them like Blizzard's, with EldoUI's move panel beside Edit Mode's window."] = "EldoUIs Rahmen lassen sich auch hier verschieben: Zieht sie wie die von Blizzard, mit EldoUIs Verschiebepanel neben dem Fenster des Bearbeitungsmodus.",
	["EldoUI's frames, panel and labels inside Blizzard's Edit Mode; snaps to grid and frames."] = "EldoUIs Rahmen, Panel und Beschriftungen in Blizzards Bearbeitungsmodus; rastet an Raster und Rahmen ein.",
	["EldoUI's group frames, and Blizzard's when their Improve switch is on."] = "EldoUIs Gruppenrahmen und die von Blizzard, wenn ihr Schalter Verbessern an ist.",
	["EldoUI's loot window at the mouse, roll bars, toasts from Uncommon."] = "EldoUIs Beutefenster an der Maus, Würfelleisten, Hinweise ab Selten.",
	["EldoUI's movable leave-vehicle button. Shown while you can leave a vehicle or a flight path early. Automatic: only when Blizzard's button is hidden with its bar."] = "EldoUIs verschiebbare Schaltfläche zum Verlassen des Fahrzeugs. Erscheint, solange Ihr ein Fahrzeug oder eine Flugroute vorzeitig verlassen könnt. Automatisch: nur wenn Blizzards Schaltfläche mit ihrer Leiste ausgeblendet ist.",
	["EldoUI's move mode opens with Edit Mode: its panel beside Edit Mode's window, with search, exact X and Y, lock, attach, match size and test frames. Off: compact boxes with a small X and Y dialog."] = "EldoUIs Verschiebemodus öffnet sich mit dem Bearbeitungsmodus: sein Panel neben dem Fenster des Bearbeitungsmodus, mit Suche, exaktem X und Y, Sperren, Anheften, Größe angleichen und Testrahmen. Aus: kompakte Felder mit einem kleinen X-und-Y-Dialog.",
	["EldoUI's move mode opens with Edit Mode: its panel beside this window, with search, exact X and Y, lock, attach, match size and test frames. Off: compact boxes with a small X and Y dialog."] = "EldoUIs Verschiebemodus öffnet sich mit dem Bearbeitungsmodus: sein Panel neben diesem Fenster, mit Suche, exaktem X und Y, Sperren, Anheften, Größe angleichen und Testrahmen. Aus: kompakte Felder mit einem kleinen X-und-Y-Dialog.",
	["EldoUI's own"] = "EldoUIs eigenes",
	["EldoUI's own cast bars get effects. For a unit whose EldoUI cast bar is off, Blizzard's own cast bar gets them instead."] = "EldoUIs eigene Zauberleisten erhalten Effekte. Für eine Einheit, deren EldoUI-Zauberleiste aus ist, erhält stattdessen Blizzards eigene Zauberleiste sie.",
	["EldoUI's own cooldown rows. The game draws each cooldown; EldoUI picks what shows and where. Their glows are on the Glows page."] = "EldoUIs eigene Abklingzeitreihen. Das Spiel zeichnet jede Abklingzeit; EldoUI wählt, was wo erscheint. Ihr Leuchten steht auf der Seite Leuchteffekte.",
	["EldoUI's own display"] = "EldoUIs eigene Anzeige",
	["EldoUI's own leveling guide: community guides step by step in an EldoUI window on the layout's guide spot, with goals that tick from your quest log, bags and level, and one waypoint to the next goal."] = "EldoUIs eigener Levelguide: Community-Guides Schritt für Schritt in einem EldoUI-Fenster am Guide-Platz des Layouts, mit Zielen, die sich anhand Eures Questlogs, Eurer Taschen und Stufe abhaken, und einem Wegpunkt zum nächsten Ziel.",
	["EldoUI's own leveling guide: community guides, step by step, on the layout's guide spot. The guides are in English."] = "EldoUIs eigener Levelguide: Community-Guides Schritt für Schritt am Guide-Platz des Layouts. Die Guides sind auf Englisch.",
	["EldoUI's own ring around the mouse cursor. The GCD and cast sweeps are drawn by the game from its own timers."] = "EldoUIs eigener Ring um den Mauszeiger. GCD- und Zauberverlauf zeichnet das Spiel aus seinen eigenen Timern.",
	["EldoUI's own scrolling combat text in the scroll areas: damage and healing you take, notifications, loot and gains."] = "EldoUIs eigener scrollender Kampftext in den Scrollbereichen: erlittener Schaden und erhaltene Heilung, Benachrichtigungen, Beute und Gewinne.",
	["EldoUI's own swing bars with titles and time, GCD ring on the cursor."] = "EldoUIs eigene Schlagleisten mit Titeln und Zeit, GCD-Ring am Mauszeiger.",
	["EldoUI's scrolling text instead of Blizzard's text around your character, while EldoUI's is on. Your damage numbers over enemies stay."] = "EldoUIs scrollender Text statt Blizzards Text um Euren Charakter, solange der von EldoUI an ist. Eure Schadenszahlen über Feinden bleiben.",
	["EldoUI's settings (each opens the options search on it) and the game settings browser."] = "EldoUIs Einstellungen (jede öffnet die Optionssuche dazu) und der Browser für Spieleinstellungen.",
	["EldoUI's swing bars, drawn from the game's swing event, with the movers and settings of the Swing timer tab. Hide Blizzard's bars there."] = "EldoUIs Schlagleisten, gezeichnet aus dem Schlagereignis des Spiels, mit den Verschiebefeldern und Einstellungen des Reiters Schlagtimer. Blendet Blizzards Leisten dort aus.",
	["EldoUI's thin line"] = "EldoUIs dünne Linie",
	["EldoUI's unit frames."] = "EldoUIs Einheitenrahmen.",
	["EldoUI: %d action slots hold a lower rank of %s. Look at the changes before they happen?"] = { one = "EldoUI: %d Aktionsplatz enthält einen niedrigeren Rang von %s. Die Änderungen ansehen, bevor sie passieren?", other = "EldoUI: %d Aktionsplätze enthalten einen niedrigeren Rang von %s. Die Änderungen ansehen, bevor sie passieren?" },
	["EldoUI: gear sets change only out of combat."] = "EldoUI: Ausrüstungssets wechseln nur außerhalb des Kampfes.",
	["EldoUI: name, title, class color"] = "EldoUI: Name, Titel, Klassenfarbe",
	["EldoUI_Emoji could not load (%s)."] = "EldoUI_Emoji konnte nicht geladen werden (%s).",
	["EldoUI_Emoji does not match this EldoUI version. Update both folders."] = "EldoUI_Emoji passt nicht zu dieser EldoUI-Version. Aktualisiert beide Ordner.",
	["EldoUI_Emoji is switched off in the addon list."] = "EldoUI_Emoji ist in der Addon-Liste ausgeschaltet.",
	["EldoUI_Emoji loads when emoji are on and you are out of combat."] = "EldoUI_Emoji lädt, wenn Emojis an sind und Ihr außerhalb des Kampfes seid.",
	["EldoUI_GuideData is switched off in the game's addon list. Turn it on there and reload."] = "EldoUI_GuideData ist in der Addon-Liste des Spiels ausgeschaltet. Schaltet es dort ein und ladet neu.",
	["Eldostar"] = "Eldostar",
	["Eldostar guide"] = "Eldostar-Guide",
	["Eldostar is switched off on the Modules page, so no guide shows."] = "Eldostar ist auf der Seite Module ausgeschaltet, daher erscheint kein Guide.",
	["Eldostar is your guide."] = "Eldostar ist Euer Guide.",
	["Eldostar is your guide. RestedXP stays on and keeps its own spot: EldoUI does not place it."] = "Eldostar ist Euer Guide. RestedXP bleibt an und behält seinen eigenen Platz: EldoUI platziert es nicht.",
	["Eldostar, EldoUI's own guide window."] = "Eldostar, das eigene Guide-Fenster von EldoUI.",
	["Elemental Storm"] = "Elementarsturm",
	["Ember"] = "Glut",
	["Emberveil Foundry"] = "Glutschleiergießerei",
	["Emoji"] = "Emoji",
	["Emoji and :shortcodes: such as :smile: show as pictures in chat. Needs the Blizzard UI switch Improve. Emoji graphics: Twemoji, CC-BY 4.0."] = "Emojis und :Kurzcodes: wie :smile: erscheinen im Chat als Bilder. Braucht den Schalter Verbessern auf der Seite Blizzard-UI. Emoji-Grafiken: Twemoji, CC-BY 4.0.",
	["Emoji characters and :shortcodes: in chat lines show as pictures, and the edit box gets a smiley button for the picker. Hover an emoji in chat for its name and shortcode."] = "Emoji-Zeichen und :Kurzcodes: in Chatzeilen erscheinen als Bilder, und das Eingabefeld erhält eine Smiley-Schaltfläche für die Auswahl. Zeigt im Chat auf ein Emoji, um Namen und Kurzcode zu sehen.",
	["Emoji don't go into slash commands."] = "Emojis kommen nicht in Slash-Befehle.",
	["Emoji ready: %d emoji, Twemoji %s, %.1f MB in memory."] = "Emoji bereit: %d Emojis, Twemoji %s, %.1f MB im Speicher.",
	["Emoji ready: %d emoji, Twemoji %s."] = "Emoji bereit: %d Emojis, Twemoji %s.",
	["Emoji size"] = "Emoji-Größe",
	["Emoji that come in skin tones use this one."] = "Emojis mit Hauttönen verwenden diesen.",
	["Emoji you pick show up here."] = "Emojis, die Ihr wählt, erscheinen hier.",
	["Emote"] = "Emote",
	["Emotes of your target (\"... becomes enraged!\"). Skipped while the game keeps chat hidden."] = "Emotes Eures Ziels („... gerät in Raserei!“). Wird übersprungen, solange das Spiel den Chat verborgen hält.",
	["Emphasized area height"] = "Höhe des hervorgehobenen Bereichs",
	["Emphasized area width"] = "Breite des hervorgehobenen Bereichs",
	["Empties as time runs out"] = "Leert sich mit ablaufender Zeit",
	["Empties the Recent row of the picker for this character."] = "Leert die Reihe Kürzlich in der Auswahl für diesen Charakter.",
	["Empties the draft. Your Legacy points don't change."] = "Leert den Entwurf. Eure Vermächtnispunkte ändern sich nicht.",
	["Empties the list (asks first)."] = "Leert die Liste (fragt zuerst).",
	["Empties the log."] = "Leert das Protokoll.",
	["Empties the run log for every character, after a confirmation."] = "Leert das Durchlaufprotokoll aller Charaktere nach einer Bestätigung.",
	["Empties the search box each time the bag or bank window closes, so the next open shows every item."] = "Leert das Suchfeld jedes Mal, wenn das Taschen- oder Bankfenster schließt, damit beim nächsten Öffnen alle Gegenstände erscheinen.",
	["Empty slots of herb, enchanting and other special bags get a green border."] = "Leere Plätze von Kräuter-, Verzauberer- und anderen Spezialtaschen erhalten einen grünen Rand.",
	["Empty space between the center and each bar."] = "Leerer Raum zwischen der Mitte und jedem Balken.",
