	["Gathering finds"] = "Sammelfunde",
	["Gathering nodes"] = "Sammelvorkommen",
	["Gathering: %d nodes added, %d matched nodes you have."] = "Sammeln: %d Vorkommen hinzugefügt, %d stimmten mit Euren Vorkommen überein.",
	["Gear"] = "Ausrüstung",
	["Gear below this item level shows no number."] = "Ausrüstung unter dieser Gegenstandsstufe zeigt keine Zahl.",
	["Gear links in chat show their equipment slot and armor or weapon type. Off by default."] = "Ausrüstungslinks im Chat zeigen ihren Ausrüstungsplatz und Rüstungs- oder Waffentyp. Standardmäßig aus.",
	["Gear needs repair"] = "Ausrüstung muss repariert werden",
	["Gear sets"] = "Ausrüstungssets",
	["Gear that Upgrades rates above your equipped gear"] = "Ausrüstung, die laut Verbesserungen besser ist als Eure angelegte Ausrüstung",
	["Gear that binds when equipped or used and is not bound yet says so in the bottom corner."] = "Ausrüstung, die beim Anlegen oder Benutzen gebunden wird und noch nicht gebunden ist, zeigt das in der unteren Ecke.",
	["Gear the character wears."] = "Ausrüstung, die der Charakter trägt.",
	["Gear, recipes and other items this character can't use yet (level, skill, class or armor type) get a red icon, as the game's tooltip shows in red."] = "Ausrüstung, Rezepte und andere Gegenstände, die dieser Charakter noch nicht benutzen kann (Stufe, Fertigkeit, Klasse oder Rüstungsart), erhalten ein rotes Symbol, so wie der Tooltip des Spiels sie rot zeigt.",
	["Gem and enchant marks"] = "Markierungen für Edelsteine und Verzauberungen",
	["General bag slots"] = "Allgemeine Taschenplätze",
	["General channel"] = "Kanal Allgemein",
	["Get routes your group sends"] = "Routen Eurer Gruppe empfangen",
	["Get the flight path at %s"] = "Holt die Flugroute in %s",
	["Give"] = "Geben",
	["Give %s to %s?"] = "%s an %s geben?",
	["Give a channel and a player name, for example Trade and Name-Realm."] = "Gebt einen Kanal und einen Spielernamen an, zum Beispiel Handel und Name-Realm.",
	["Give menu"] = "Vergabemenü",
	["Give one spell or item its own sound, speech or glow. Module default uses the settings on the Pulse tab."] = "Gebt einem Zauber oder Gegenstand einen eigenen Klang, eine eigene Sprachausgabe oder ein eigenes Leuchten. Modulstandard verwendet die Einstellungen im Reiter Pulsieren.",
	["Give spell flyout buttons the EldoUI look. Blizzard's flyout follows the Skin switch of Action button look."] = "Gibt den Ausklapptasten von Zaubern die EldoUI-Optik. Blizzards Ausklappleiste folgt dem Skin-Schalter von Aktionstasten-Optik.",
	["Give this bar its own keybind, count and macro text (the gear). Off: the bar uses the Text tab."] = "Gebt dieser Leiste eigenen Text für Tastenbelegung, Anzahl und Makro (das Zahnrad). Aus: Die Leiste verwendet den Reiter Text.",
	["Give this group its own visibility rule. Off: a group made from a fixed row follows that row, any other group follows the main row."] = "Gebt dieser Gruppe eine eigene Sichtbarkeitsregel. Aus: Eine Gruppe aus einer festen Reihe folgt dieser Reihe, jede andere Gruppe folgt der Hauptreihe.",
	["Give this icon's shadow its own strength and size. Off follows Frame shadows on Global settings > Textures."] = "Gebt dem Schatten dieses Symbols eine eigene Stärke und Größe. Aus folgt Rahmenschatten unter Globale Einstellungen > Texturen.",
	["Give your route another name."] = "Gebt Eurer Route einen anderen Namen.",
	["Gives BigWigs' bars, messages and countdown a spot in the layout. BigWigs asks in its own window before it takes them. Unchecked, EldoUI leaves BigWigs alone."] = "Gibt den Leisten, Nachrichten und dem Countdown von BigWigs einen Platz im Layout. BigWigs fragt in seinem eigenen Fenster, bevor es sie abgibt. Ohne Haken lässt EldoUI BigWigs in Ruhe.",
	["Gives the selected profile another name."] = "Gibt dem gewählten Profil einen anderen Namen.",
	["Glass"] = "Glas",
	["Glimmercap Crossing"] = "Glimmerhutübergang",
	["Global cooldown"] = "Globale Abklingzeit",
	["Global cooldown bar"] = "Leiste der globalen Abklingzeit",
	["Glow around the pulse icon for this entry, or not."] = "Leuchten um das Pulssymbol für diesen Eintrag – oder nicht.",
	["Glow on a party or raid frame while the member has a debuff you (or your group) can dispel. Switch it on under Party and Raid > Indicators."] = "Leuchten auf einem Gruppen- oder Schlachtzugsrahmen, solange das Mitglied einen Schwächungszauber hat, den Ihr (oder Eure Gruppe) bannen könnt. Schaltet es unter Gruppe und Schlachtzug > Indikatoren ein.",
	["Glow on a party or raid frame while the member has an aura the game marks as a boss aura. Switch it on under Party and Raid > Indicators."] = "Leuchten auf einem Gruppen- oder Schlachtzugsrahmen, solange das Mitglied eine Aura hat, die das Spiel als Bossaura markiert. Schaltet es unter Gruppe und Schlachtzug > Indikatoren ein.",
	["Glow on boss auras"] = "Leuchten bei Bossauren",
	["Glow on new items"] = "Leuchten bei neuen Gegenständen",
	["Glow on the big icon of the Encounter Timeline in the last seconds before an event."] = "Leuchten auf dem großen Symbol der Begegnungszeitleiste in den letzten Sekunden vor einem Ereignis.",
	["Glow style"] = "Leuchtstil",
