	["Item level text size"] = "Textgröße der Gegenstandsstufe",
	["Item level, durability, lockouts and gold. Opens on the Lockouts tab."] = "Gegenstandsstufe, Haltbarkeit, Instanzsperren und Gold. Öffnet sich im Reiter Instanzsperren.",
	["Item level; \"lvl:20\" means 20 or more"] = "Gegenstandsstufe; „lvl:20“ bedeutet 20 oder mehr",
	["Item lists"] = "Gegenstandslisten",
	["Item marks"] = "Gegenstandsmarkierungen",
	["Item names or IDs, separated by commas, in the order they should show (for example Major Healing Potion, 5512). Names work for items in your bags."] = "Gegenstandsnamen oder IDs, durch Kommas getrennt, in der Reihenfolge, in der sie erscheinen sollen (zum Beispiel Erheblicher Heiltrank, 5512). Namen funktionieren für Gegenstände in Euren Taschen.",
	["Item names or IDs, separated by commas, that always show."] = "Gegenstandsnamen oder IDs, durch Kommas getrennt, die immer erscheinen.",
	["Item names or IDs, separated by commas, that never show."] = "Gegenstandsnamen oder IDs, durch Kommas getrennt, die nie erscheinen.",
	["Item quality"] = "Gegenstandsqualität",
	["Item quality and class color follow what fired the trigger."] = "Gegenstandsqualität und Klassenfarbe richten sich danach, was den Auslöser ausgelöst hat.",
	["Item ready"] = "Gegenstand bereit",
	["Item row"] = "Gegenstandsreihe",
	["Item rows take the item's quality color on their border."] = "Gegenstandszeilen erhalten die Qualitätsfarbe des Gegenstands an ihrem Rand.",
	["Item score"] = "Gegenstandswertung",
	["Item slots"] = "Ausrüstungsplätze",
	["Item type, subtype or slot"] = "Gegenstandsart, Unterart oder Platz",
	["Item value"] = "Gegenstandswert",
	["Item, %d in your bags"] = "Gegenstand, %d in Euren Taschen",
	["Item, none in your bags"] = "Gegenstand, keiner in Euren Taschen",
	["Items"] = "Gegenstände",
	["Items and their value"] = "Gegenstände und ihr Wert",
	["Items attached to mail in the mailbox, as of the last visit."] = "Gegenstände, die an Post im Briefkasten hängen, Stand des letzten Besuchs.",
	["Items below this quality are left out of the post."] = "Gegenstände unter dieser Qualität werden nicht mitgepostet.",
	["Items below this quality are not shown."] = "Gegenstände unter dieser Qualität werden nicht angezeigt.",
	["Items below this quality keep the plain border."] = "Gegenstände unter dieser Qualität behalten den schlichten Rand.",
	["Items bound to you"] = "An Euch gebundene Gegenstände",
	["Items for quests and items that start one."] = "Gegenstände für Quests und Gegenstände, die eine Quest beginnen.",
	["Items in one of your equipment sets get a small mark in the bottom corner."] = "Gegenstände aus einem Eurer Ausrüstungssets erhalten eine kleine Markierung in der unteren Ecke.",
	["Items in the bags, bank and mailbox. The Bags button opens the Bags module's own windows on this character."] = "Gegenstände in Taschen, Bank und Briefkasten. Die Schaltfläche Taschen öffnet die eigenen Fenster des Moduls Taschen für diesen Charakter.",
	["Items in the bags."] = "Gegenstände in den Taschen.",
	["Items in the bank, as of the last visit."] = "Gegenstände in der Bank, Stand des letzten Besuchs.",
	["Items in the guild bank tabs a character of yours opened."] = "Gegenstände in den Gildenbankfächern, die ein Charakter von Euch geöffnet hat.",
	["Items in your bags that have a use. Your click or Enter on the result uses it."] = "Gegenstände in Euren Taschen, die eine Verwendung haben. Euer Klick oder die Eingabetaste auf dem Ergebnis benutzt sie.",
	["Items looted"] = "Geplünderte Gegenstände",
	["Items looted, and items per hour."] = "Geplünderte Gegenstände und Gegenstände pro Stunde.",
	["Items new in your bags"] = "Neue Gegenstände in Euren Taschen",
	["Items on this list never get an action. Modifier + right-click an item with a glow to add it, or type it here."] = "Gegenstände auf dieser Liste erhalten nie eine Aktion. Zusatztaste + Rechtsklick auf einen leuchtenden Gegenstand fügt ihn hinzu, oder gebt ihn hier ein.",
	["Items per hour"] = "Gegenstände pro Stunde",
	["Items that always or never show."] = "Gegenstände, die immer oder nie erscheinen.",
	["Items that bind when equipped and are not bound yet"] = "Gegenstände, die beim Anlegen gebunden werden und noch nicht gebunden sind",
	["Items that bind when picked up"] = "Gegenstände, die beim Aufheben gebunden werden",
	["Items the character has on the auction house, as of the last visit."] = "Gegenstände, die der Charakter im Auktionshaus hat, Stand des letzten Besuchs.",
	["Items this search finds go into the category. The bag window's Search help lists every word."] = "Gegenstände, die diese Suche findet, kommen in die Kategorie. Die Suchhilfe des Taschenfensters listet jedes Wort.",
	["Items waiting in the mailbox; red when a mail returns or is deleted within 5 days."] = "Gegenstände, die im Briefkasten warten; rot, wenn eine Post innerhalb von 5 Tagen zurückgeht oder gelöscht wird.",
	["Items whose name has the word"] = "Gegenstände, deren Name das Wort enthält",
	["Items you create, such as crafted goods and conjured food."] = "Gegenstände, die Ihr erschafft, etwa hergestellte Waren und herbeigezaubertes Essen.",
	["Items you just got glow until you close your bags."] = "Gerade erhaltene Gegenstände leuchten, bis Ihr Eure Taschen schließt.",
	["Items you just got, until you close your bags."] = "Gerade erhaltene Gegenstände, bis Ihr Eure Taschen schließt.",
	["Items you left out of this category from a section title's menu. Forgetting them lets its search find them again."] = "Gegenstände, die Ihr über das Menü eines Abschnittstitels aus dieser Kategorie herausgenommen habt. Vergesst Ihr sie, findet die Suche der Kategorie sie wieder.",
	["Items you loot, receive or create."] = "Gegenstände, die Ihr plündert, erhaltet oder herstellt.",
	["Items you loot. Only while EldoUI's loot toasts are off, unless you check the option on the Loot and Info tab."] = "Gegenstände, die Ihr plündert. Nur solange die Beutehinweise von EldoUI aus sind, außer Ihr hakt die Option im Reiter Beute und Info an.",
	["Items you make"] = "Gegenstände, die Ihr herstellt",
	["Items, money and currencies show only while EldoUI's loot toasts are off, so nothing shows twice. XP, honor and reputation always can."] = "Gegenstände, Geld und Währungen erscheinen nur, solange die Beutehinweise von EldoUI aus sind, damit nichts doppelt erscheint. EP, Ehre und Ruf können immer erscheinen.",
	["Its own mover"] = "Eigenes Verschiebefeld",
	["Its own mover: drag it in move mode. In the chat window (up to three, the docked second info bar counts as one) or on the minimap (two): it sits inside the edge, moves along and the frame makes room."] = "Eigenes Verschiebefeld: Zieht es im Verschiebemodus. Im Chatfenster (bis zu drei, die angedockte zweite Infoleiste zählt als eine) oder an der Minikarte (zwei): Es sitzt innen am Rand, bewegt sich mit, und der Rahmen macht Platz.",
	["Its own position"] = "Eigene Position",
	["Its own sound for a legendary item. None plays the sound above."] = "Ein eigener Klang für einen legendären Gegenstand. Nichts spielt den Klang oben ab.",
	["Its packs are not in your dungeon data."] = "Seine Gegnergruppen sind nicht in Euren Dungeondaten.",
	["Its saved bags, bank, gold, mail, auctions, professions, quests, lockouts, level log, wishlist and journal leave EldoUI. Its journal is backed up first, and the Saved data page can put it back or remove it. Log in on it again to record it anew."] = "Seine gespeicherten Taschen, Bank, Gold, Post, Auktionen, Berufe, Quests, Instanzsperren, Stufenprotokoll, Wunschliste und Tagebuch verlassen EldoUI. Sein Tagebuch wird vorher gesichert, und die Seite Gespeicherte Daten kann es zurückholen oder entfernen. Loggt Euch erneut mit ihm ein, um es neu zu erfassen.",
	["Its search alone fills it."] = "Nur ihre Suche füllt sie.",
	["Join a group first, or pick Guild under Ask and share with."] = "Tretet zuerst einer Gruppe bei oder wählt Gilde unter Fragen und teilen mit.",
	["Join a guild first, or pick Group under Ask and share with."] = "Tretet zuerst einer Gilde bei oder wählt Gruppe unter Fragen und teilen mit.",
	["Join each pair of runes with a line and fill every cell."] = "Verbindet jedes Runenpaar mit einer Linie und füllt jedes Feld.",
	["Join order (no grouping)"] = "Beitrittsreihenfolge (ohne Gruppierung)",
	["Join similar hits"] = "Ähnliche Treffer zusammenfassen",
	["Join the pull before"] = "Mit dem vorherigen Pull zusammenlegen",
	["Join the pulls of the picked route with a line in each pull's color."] = "Verbindet die Pulls der gewählten Route mit einer Linie in der Farbe jedes Pulls.",
	["Join window"] = "Zeitfenster zum Zusammenfassen",
	["Joined %d of %d"] = "%d von %d verbunden",
	["Joined in %d strokes"] = { one = "Mit %d Strich verbunden", other = "Mit %d Strichen verbunden" },
	["Joins hits of the same kind that land within a moment into one line."] = "Fasst Treffer derselben Art, die kurz nacheinander landen, zu einer Zeile zusammen.",
	["Journal moment"] = "Tagebuchmoment",
	["Journeyman campfire"] = "Gesellen-Lagerfeuer",
	["Jump a rune over its neighbor into an empty hole."] = "Lasst eine Rune über ihre Nachbarin in ein leeres Loch springen.",
