	["None in your bags"] = "Nichts in Euren Taschen",
	["None learned"] = "Keine erlernt",
	["None of these characters had a quest in the log at logout."] = "Keiner dieser Charaktere hatte beim Ausloggen eine Quest im Questlog.",
	["None of these characters had auctions running at their last auction house visit."] = "Keiner dieser Charaktere hatte bei seinem letzten Besuch im Auktionshaus laufende Auktionen.",
	["None of these characters had bids at their last auction house visit."] = "Keiner dieser Charaktere hatte bei seinem letzten Besuch im Auktionshaus Gebote.",
	["None of these characters had mail at their last mailbox visit. Mail you send to your own characters shows up at once."] = "Keiner dieser Charaktere hatte bei seinem letzten Besuch am Briefkasten Post. Post, die Ihr an Eure eigenen Charaktere sendet, erscheint sofort.",
	["None of these characters has saved anything for this grid yet."] = "Keiner dieser Charaktere hat bisher etwas für diese Tabelle gespeichert.",
	["None of your characters has a matching item in the places picked above. Banks, mail and auctions show what each character saw on its last visit."] = "Keiner Eurer Charaktere hat einen passenden Gegenstand an den oben gewählten Orten. Banken, Post und Auktionen zeigen, was jeder Charakter bei seinem letzten Besuch gesehen hat.",
	["None of your characters is saved to an instance right now. Lockouts show here after each character logs in (or opens the raid info)."] = "Keiner Eurer Charaktere ist derzeit in einer Instanz gespeichert. Instanzsperren erscheinen hier, nachdem sich jeder Charakter eingeloggt (oder die Schlachtzugsinfo geöffnet) hat.",
	["None picked"] = "Nichts gewählt",
	["None tracked"] = "Nichts verfolgt",
	["None watched"] = "Nichts beobachtet",
	["Normal target"] = "Normales Ziel",
	["Not a run"] = "Kein Durchlauf",
	["Not available in this client."] = "In diesem Client nicht verfügbar.",
	["Not available in this game client: aura alarms are off. Breath, fatigue and AFK alarms still work."] = "In diesem Spielclient nicht verfügbar: Aurenalarme sind aus. Atem-, Erschöpfungs- und AFK-Alarme funktionieren weiterhin.",
	["Not chosen yet: %s"] = "Noch nicht gewählt: %s",
	["Not enough gold"] = "Nicht genug Gold",
	["Not enough power color"] = "Farbe bei zu wenig Ressource",
	["Not found. Use an item link or ID, a currency link, c<currency ID>, or a currency name."] = "Nicht gefunden. Nutzt einen Gegenstandslink oder eine ID, einen Währungslink, c<currency ID> oder einen Währungsnamen.",
	["Not in a group."] = "Nicht in einer Gruppe.",
	["Not in an instance."] = "Nicht in einer Instanz.",
	["Not in combat."] = "Nicht im Kampf.",
	["Not in the route"] = "Nicht in der Route",
	["Not placed: another guide is selected for the guide spot."] = "Nicht platziert: Für den Guide-Platz ist ein anderer Guide ausgewählt.",
	["Not placed: the guide spot goes to the guide you picked on Eldostar's page."] = "Nicht platziert: Der Guide-Platz geht an den Guide, den Ihr auf der Seite von Eldostar gewählt habt.",
	["Not played yet"] = "Noch nicht gespielt",
	["Not quite. The answer was %s."] = "Nicht ganz. Die Antwort war %s.",
	["Not reset: %s."] = "Nicht zurückgesetzt: %s.",
	["Not set"] = "Nicht festgelegt",
	["Not set up: EldoUI changes nothing in DBM until you click \"Set up DBM for EldoUI\"."] = "Nicht eingerichtet: EldoUI ändert nichts an DBM, bis Ihr auf „DBM für EldoUI einrichten“ klickt.",
	["Not started"] = "Nicht begonnen",
	["Not usable color"] = "Farbe für nicht Nutzbares",
	["Not used by your class"] = "Von Eurer Klasse nicht genutzt",
	["Not: leaves out what the word finds"] = "Nicht: lässt weg, was das Wort findet",
	["Note when a camp buff starts"] = "Hinweis, wenn ein Lagereffekt beginnt",
	["Notes and drawings"] = "Notizen und Zeichnungen",
	["Nothing found on any character."] = "Bei keinem Charakter etwas gefunden.",
	["Nothing found."] = "Nichts gefunden.",
	["Nothing here can go there."] = "Nichts von hier passt dorthin.",
	["Nothing here yet."] = "Hier ist noch nichts.",
	["Nothing in this log yet."] = "Noch nichts in diesem Protokoll.",
	["Nothing is damaged."] = "Nichts ist beschädigt.",
	["Nothing is filtered"] = "Nichts wird gefiltert",
	["Nothing is spent."] = "Nichts ausgegeben.",
	["Nothing matches the filters. Turn on Alts or turn off 24 h to see more."] = "Nichts passt zu den Filtern. Schaltet Twinks ein oder 24 Std. aus, um mehr zu sehen.",
	["Nothing saved"] = "Nichts gespeichert",
	["Nothing this day"] = "An diesem Tag nichts",
	["Nothing to copy: search for something first."] = "Nichts zu kopieren: Sucht zuerst nach etwas.",
	["Nothing to import."] = "Nichts zu importieren.",
	["Nothing to show"] = "Nichts anzuzeigen",
	["Nothing was hidden."] = "Nichts wurde ausgeblendet.",
	["Nothing watched yet."] = "Noch nichts beobachtet.",
	["Nothing yet: EldoUI leaves every Edit Mode frame to Blizzard."] = "Noch nichts: EldoUI überlässt jeden Rahmen des Bearbeitungsmodus Blizzard.",
	["Notice when a route arrives"] = "Hinweis, wenn eine Route eintrifft",
	["Notice without fuss: EldoUI's soft sounds, a clean banner, a flash only when a queue pops or a ready check starts."] = "Bemerken ohne Aufhebens: die sanften Töne von EldoUI, ein schlichtes Banner und ein Aufblitzen nur, wenn eine Warteschlange aufgeht oder ein Bereitschaftscheck beginnt.",
	["Notifications"] = "Benachrichtigungen",
	["Notify when the game's frames are used"] = "Melden, wenn die Rahmen des Spiels genutzt werden",
	["Novice"] = "Anfänger",
	["Now"] = "Jetzt",
	["Now %d of %d ranks, draft %d."] = "Jetzt %d von %d Rängen, Entwurf %d.",
	["Now %s  ·  %s (%s)"] = "Jetzt %s  ·  %s (%s)",
	["Now click the last letter."] = "Klickt jetzt den letzten Buchstaben an.",
	["Nudge sideways"] = "Seitlich verschieben",
	["Nudge step"] = "Schrittweite",
	["Nudge up or down"] = "Nach oben oder unten verschieben",
	["Number keys pick"] = "Zifferntasten wählen",
	["Number of characters"] = "Anzahl der Charaktere",
	["Number of rows (up to %d buffs in total)."] = "Anzahl der Reihen (insgesamt bis zu %d Stärkungszauber).",
	["Number of rows (up to %d debuffs in total)."] = "Anzahl der Reihen (insgesamt bis zu %d Schwächungszauber).",
	["Number on the bar, straight from the game. Percent is not shown for combo points."] = "Zahl auf der Leiste, direkt vom Spiel. Prozent wird für Kombopunkte nicht angezeigt.",
	["Number on the health bar, straight from the game."] = "Zahl auf der Gesundheitsleiste, direkt vom Spiel.",
	["Number on the power bar, straight from the game."] = "Zahl auf der Ressourcenleiste, direkt vom Spiel.",
	["Number size"] = "Zahlengröße",
	["Number: [2]"] = "Nummer: [2]",
	["Numbered channels"] = "Nummerierte Kanäle",
	["Numbers and words over EldoUI's unit frames when the unit is hit, healed, dodges, parries, misses or is immune."] = "Zahlen und Wörter über den Einheitenrahmen von EldoUI, wenn die Einheit getroffen oder geheilt wird, ausweicht, pariert, verfehlt oder immun ist.",
	["Numbers fade and scale with EldoUI's plate (non-target fade, target scale)."] = "Zahlen verblassen und skalieren mit der Plakette von EldoUI (Verblassen von Nicht-Zielen, Skalierung des Ziels).",
	["Numbers from"] = "Zahlen ab",
	["Numbers on the enemy's nameplate when it is hit. Every hit the enemy takes, not only yours."] = "Zahlen auf der Namensplakette des Gegners, wenn er getroffen wird. Jeder Treffer, den der Gegner erleidet, nicht nur Eure.",
	["Numbers on the enemy's nameplate, a slim incoming lane, no target area."] = "Zahlen auf der Namensplakette des Gegners, eine schmale Spalte für Eingehendes, kein Zielbereich.",
	["Numbers on the swipe: EldoUI's cooldown text (Fonts and text page), the game's own (its Action Bars setting), or none."] = "Zahlen auf der Spirale: der Abklingzeittext von EldoUI (Seite Schriften und Text), der des Spiels (seine Einstellung unter Aktionsleisten) oder keiner.",
	["Numbers on your target's plate only, or on every enemy plate."] = "Zahlen nur auf der Plakette Eures Ziels oder auf jeder gegnerischen Plakette.",
	["Numbers over targets too"] = "Zahlen auch über Zielen",
	["Numbers rise off an enemy's nameplate when it is hit, by you or anyone else: the game doesn't say who hit."] = "Zahlen steigen von der Namensplakette eines Gegners auf, wenn er getroffen wird, von Euch oder sonst jemandem: Das Spiel verrät nicht, wer getroffen hat.",
	["OOF"] = "AUTSCH",
	["Off Hand"] = "Schildhand",
	["Off by default. At the bank, mail, trade or a vendor, a button by the search box moves up to 12 searched items per click. Quest, recipe and never-sell items stay."] = "Standardmäßig aus. Bei der Bank, der Post, im Handel oder bei einem Händler verschiebt eine Schaltfläche neben dem Suchfeld pro Klick bis zu 12 gesuchte Gegenstände. Quest-, Rezept- und Nie-verkaufen-Gegenstände bleiben.",
	["Off by default. Nothing is ever sent without your click, and gold is never posted."] = "Standardmäßig aus. Nichts wird je ohne Euren Klick gesendet, und Gold wird nie genannt.",
	["Off by default. On shows the send buttons below; each send is one click, and the other player must accept."] = "Standardmäßig aus. An zeigt die Senden-Schaltflächen unten; jedes Senden ist ein Klick, und der andere Spieler muss annehmen.",
	["Off hand color"] = "Farbe der Schildhand",
	["Off in dungeons, raids and battlegrounds."] = "Aus in Dungeons, Schlachtzügen und auf Schlachtfeldern.",
	["Off leaves Blizzard's buff bars viewer exactly as Blizzard made it."] = "Aus lässt Blizzards Anzeige der Stärkungsleisten genau so, wie Blizzard sie gemacht hat.",
	["Off leaves Blizzard's buff icons viewer exactly as Blizzard made it."] = "Aus lässt Blizzards Anzeige der Stärkungssymbole genau so, wie Blizzard sie gemacht hat.",
	["Off leaves Blizzard's essential viewer exactly as Blizzard made it."] = "Aus lässt Blizzards Anzeige der essenziellen Abklingzeiten genau so, wie Blizzard sie gemacht hat.",
	["Off leaves Blizzard's utility viewer exactly as Blizzard made it."] = "Aus lässt Blizzards Anzeige der nützlichen Abklingzeiten genau so, wie Blizzard sie gemacht hat.",
	["Off leaves whispers out of the saved history, also their copies in the right panel and the Alerts tab, and deletes the whispers saved so far."] = "Aus lässt Flüsternachrichten aus dem gespeicherten Verlauf heraus, auch ihre Kopien im rechten Panel und im Reiter „Hinweise“, und löscht die bisher gespeicherten Flüsternachrichten.",
	["Off lists every character, with 0 where they have none."] = "Aus listet jeden Charakter auf, mit 0, wo er keine hat.",
	["Off lists only your other characters."] = "Aus listet nur Eure anderen Charaktere auf.",
	["Off uses the color below."] = "Aus nutzt die Farbe unten.",
	["Off uses the link color below."] = "Aus nutzt die Linkfarbe unten.",
	["Off uses the spot you set in move mode (/eui move). For Blizzard's window this needs the Move switch and sets the game's \"loot under mouse\" option."] = "Aus nutzt die Stelle, die Ihr im Verschiebemodus festlegt (/eui move). Für Blizzards Fenster braucht das den Schalter „Verschieben“ und setzt die Spieloption „Beute unter dem Mauszeiger“.",
	["Off: Game colors"] = "Aus: Spielfarben",
	["Off: any debuff someone in the group can dispel."] = "Aus: jeder Schwächungszauber, den jemand in der Gruppe bannen kann.",
	["Off: dark health bars."] = "Aus: dunkle Gesundheitsleisten.",
	["Off: frames keep only the game's own Click Casting and the default target and menu clicks."] = "Aus: Rahmen behalten nur die eigenen Klickzauber des Spiels und die Standardklicks für Ziel und Menü.",
	["Off: friends coming online or going offline keep their own lines. On: they are folded with the guild."] = "Aus: Freunde, die online kommen oder offline gehen, behalten ihre eigenen Zeilen. An: Sie werden mit der Gilde zusammengefasst.",
	["Off: it appears when the first error is logged."] = "Aus: Es erscheint, sobald der erste Fehler protokolliert wird.",
	["Off: its items go to Other."] = "Aus: Ihre Gegenstände kommen unter „Anderes“.",
	["Off: right-click to show it"] = "Aus: Rechtsklick zum Anzeigen",
	["Off: routes your group sends are not listened to."] = "Aus: Routen, die Eure Gruppe sendet, werden nicht empfangen.",
	["Off: the action bars use the cooldown colors and thresholds of the Fonts and text page, like every other cooldown. On: the rows below set them for the action bars only."] = "Aus: Die Aktionsleisten verwenden die Abklingzeitfarben und Schwellenwerte der Seite Schriften und Text, wie jede andere Abklingzeit. An: Die Zeilen unten legen sie nur für die Aktionsleisten fest.",
	["Off: the bar steps out of sight and its keys keep working. It shows when you point at it out of combat, near your bags or the right edge, and hides in combat."] = "Aus: Die Leiste verschwindet aus dem Blickfeld, ihre Tasten funktionieren weiter. Sie erscheint, wenn Ihr außerhalb des Kampfes auf sie zeigt, nahe Euren Taschen oder am rechten Rand, und verschwindet im Kampf.",
	["Off: the windows, search and tooltips use only this character. Saved data stays until you forget it."] = "Aus: Die Fenster, die Suche und die Tooltips nutzen nur diesen Charakter. Gespeicherte Daten bleiben, bis Ihr sie vergesst.",
	["Off: these items go to their next section in the bag window."] = "Aus: Diese Gegenstände kommen in ihren nächsten Abschnitt im Taschenfenster.",
	["Off: these items go to their next section in the bank window."] = "Aus: Diese Gegenstände kommen in ihren nächsten Abschnitt im Bankfenster.",
	["Off: white names."] = "Aus: weiße Namen.",
	["Offer every node on every map."] = "Jedes Vorkommen auf jeder Karte anbieten.",
	["Offer rank upgrades"] = "Rangverbesserungen anbieten",
	["Offer the nodes of the map you are on."] = "Die Vorkommen der Karte anbieten, auf der Ihr seid.",
	["Offers this old disappear. The board keeps up to 300 offers."] = "Angebote dieses Alters verschwinden. Die Börse behält bis zu 300 Angebote.",
	["Offline guild members show in the tooltip line and the Crafters tab too, after the ones who are online."] = "Gildenmitglieder, die offline sind, erscheinen auch in der Tooltipzeile und im Reiter Handwerker, nach denen, die online sind.",
	["On WoW: Forever, DBM with DBM-Dungeons and DBM-Vanilla has the boss timers for the Forever and classic dungeons and raids. Install it like any addon; this page sets it up afterwards."] = "Für WoW: Forever enthält DBM mit DBM-Dungeons und DBM-Vanilla die Bosstimer für die Forever- und Classic-Dungeons und -Schlachtzüge. Installiert es wie jedes Addon; diese Seite richtet es danach ein.",
	["On a character that is not Hardcore the module does nothing. Messages go out only when you click Tell the guild."] = "Bei einem Charakter, der nicht Hardcore ist, tut das Modul nichts. Nachrichten gehen nur raus, wenn Ihr auf „Der Gilde sagen“ klickt.",
	["On a cooldown icon's label: the key bound to the action button that holds its spell. Empty everywhere else."] = "In der Beschriftung eines Abklingzeitsymbols: die Taste, die auf der Aktionstaste mit seinem Zauber liegt. Überall sonst leer.",
	["On a cooldown icon's label: the name of its spell or item. Empty everywhere else."] = "In der Beschriftung eines Abklingzeitsymbols: der Name seines Zaubers oder Gegenstands. Überall sonst leer.",
	["On a currency: how much of it each of your other characters has (Bags module)."] = "Bei einer Währung: wie viel davon jeder Eurer anderen Charaktere hat (Modul Taschen).",
	["On a flight path"] = "Auf einer Flugroute",
	["On a quest page, R hides the text so only the rewards show, and R again brings it back. With Shift or Alt held, R always goes on to the game. Off: R stays on your Reply key."] = "Auf einer Questseite blendet R den Text aus, sodass nur die Belohnungen zu sehen sind, und R holt ihn wieder zurück. Mit gehaltener Umschalt- oder Alt-Taste geht R immer an das Spiel weiter. Aus: R bleibt auf Eurer Taste zum Antworten.",
	["On cooldown"] = "Während der Abklingzeit",
	["On crafted items and recipes: the guild members who know the recipe, from the lists they shared (Alts module, Crafters tab)."] = "Auf hergestellten Gegenständen und Rezepten: die Gildenmitglieder, die das Rezept kennen, aus den Listen, die sie geteilt haben (Modul Twinks, Reiter Handwerker).",
	["On entering a zone, show one notice when your log contains at least ten deaths within three levels of you. Once per zone per session, outside combat and instances. Off by default."] = "Beim Betreten eines Gebiets einen Hinweis zeigen, wenn Euer Protokoll mindestens zehn Tode bis drei Stufen über oder unter Euch enthält. Einmal pro Gebiet und Sitzung, außerhalb von Kampf und Instanzen. Standardmäßig aus.",
	["On quest links: which of your characters are on the quest, ready to turn it in or completed it (Alts module)."] = "Auf Questlinks: welche Eurer Charaktere die Quest haben, sie abgeben können oder sie abgeschlossen haben (Modul Twinks).",
	["On recipes: which of your characters already know it, who can learn it now and who later (Alts module)."] = "Auf Rezepten: welche Eurer Charaktere es schon kennen, wer es jetzt lernen kann und wer später (Modul Twinks).",
	["On the blessing reminder"] = "Bei der Segenserinnerung",
	["On the minimap (bottom edge)"] = "Auf der Minikarte (unterer Rand)",
	["On the target's nameplate"] = "Auf der Namensplakette des Ziels",
	["On this quest"] = "Haben diese Quest",
	["On which great tree is Darnassus built?"] = "Auf welchem großen Baum ist Darnassus erbaut?",
	["On your unit and group frames: what each mouse button casts with the modifier you hold (Click Casting module)."] = "Auf Euren Einheiten- und Gruppenrahmen: was jede Maustaste mit dem gehaltenen Modifikator wirkt (Modul Klickzauber).",
	["On: %s"] = "An: %s",
	["On: after a layout click or a drag of the BigWigs movers, BigWigs asks in its own popup whether to take the new spots. Off: send them with the button below."] = "An: Nach einem Layoutklick oder einem Ziehen der BigWigs-Verschiebefelder fragt BigWigs in seinem eigenen Fenster, ob es die neuen Positionen übernehmen soll. Aus: Sendet sie mit der Schaltfläche unten.",
	["On: trinkets without a use effect stay out of the row. Off: both trinket slots always show."] = "An: Schmuckstücke ohne Benutzen-Effekt bleiben aus der Reihe heraus. Aus: Beide Schmuckstückplätze werden immer angezeigt.",
	["One addon message with the plan to your group, out of combat. Paladins with EldoUI see their part."] = "Eine Addon-Nachricht mit dem Plan an Eure Gruppe, außerhalb des Kampfes. Paladine mit EldoUI sehen ihren Teil.",
	["One bar"] = "Eine Leiste",
	["One bar with the buffs you keep up, your key cooldowns and the reagents you spend. Each icon shows once you know its spell."] = "Eine Leiste mit den Stärkungszaubern, die Ihr aufrechterhaltet, Euren wichtigsten Abklingzeiten und den Reagenzien, die Ihr verbraucht. Jedes Symbol erscheint, sobald Ihr seinen Zauber kennt.",
	["One bar, one segment per stack, or folded (the stacks above half color over the first half)."] = "Eine Leiste, ein Segment pro Stapel oder gefaltet (die Stapel über der Hälfte färben die erste Hälfte über).",
	["One block hanging under the main cooldown row, 2 px apart."] = "Ein Block, der 2 px entfernt unter der Hauptreihe der Abklingzeiten hängt.",
	["One button per set; click to equip it. The open set has an accent border, a set with missing items a red one."] = "Eine Schaltfläche pro Set; klickt, um es anzulegen. Das offene Set hat einen Rand in Akzentfarbe, ein Set mit fehlenden Gegenständen einen roten.",
	["One character in detail: summary with stats, items, gear, quests and reputation."] = "Ein Charakter im Detail: Übersicht mit Werten, Gegenständen, Ausrüstung, Quests und Ruf.",
	["One character's gold, or all characters added up."] = "Das Gold eines Charakters oder aller Charaktere zusammengerechnet.",
	["One chat line at log-in when a letter on any of your characters runs out soon. Only while the Mail block is on a bar or panel, and not when the Characters module's mail reminder says it."] = "Eine Chatzeile beim Einloggen, wenn ein Brief bei einem Eurer Charaktere bald abläuft. Nur solange der Block Post auf einer Leiste oder einem Panel ist, und nicht, wenn die Post-Erinnerung des Moduls Twinks es schon meldet.",
	["One class"] = "Eine Klasse",
	["One color for the countdown when Color by time left is off."] = "Eine Farbe für den Countdown, wenn „Nach Restzeit färben“ aus ist.",
	["One combined bag"] = "Eine kombinierte Tasche",
	["One equip per click; not in combat."] = "Ein Anlegen pro Klick; nicht im Kampf.",
	["One grid"] = "Ein Raster",
	["One grid of every slot, sections by item type (Categories), or one section per bag."] = "Ein Raster mit jedem Platz, Abschnitte nach Gegenstandsart (Kategorien) oder ein Abschnitt pro Tasche.",
	["One grid that fills from the bottom right, like the old bag windows."] = "Ein Raster, das sich von unten rechts füllt, wie die alten Taschenfenster.",
	["One grid, 12 columns, 38 px slots, every marker on."] = "Ein Raster, 12 Spalten, 38-px-Plätze, jede Markierung an.",
	["One grid, categories or bag by bag, and the bag bar that shows, hides and swaps single bags."] = "Ein Raster, Kategorien oder Tasche für Tasche und die Taschenleiste, die einzelne Taschen anzeigt, ausblendet und tauscht.",
	["One grid, categories or bag by bag, the bag bar and more."] = "Ein Raster, Kategorien oder Tasche für Tasche, die Taschenleiste und mehr.",
	["One icon for a big defensive cooldown, from Blizzard's defensive filter."] = "Ein Symbol für eine große defensive Abklingzeit, aus Blizzards Defensivfilter.",
	["One key casts Fishing and loots the bobber while it is out: one action per press. Combat clears the key. Also: /eui fish."] = "Eine Taste wirft die Angel aus und plündert den Schwimmer, solange er draußen ist: eine Aktion pro Tastendruck. Im Kampf wird die Taste freigegeben. Auch: /eui fish.",
	["One line in your chat after a reset: which instances were reset, and which weren't and why."] = "Eine Zeile in Eurem Chat nach einem Zurücksetzen: welche Instanzen zurückgesetzt wurden und welche nicht, und warum.",
	["One line per paladin in party or raid chat, out of combat."] = "Eine Zeile pro Paladin im Gruppen- oder Schlachtzugschat, außerhalb des Kampfes.",
	["One line with the winner in party or raid chat. Only the group leader has this button."] = "Eine Zeile mit dem Gewinner im Gruppen- oder Schlachtzugschat. Nur der Gruppenleiter hat diese Schaltfläche.",
	["One mover per bar (main hand, off hand, ranged) and the size below."] = "Ein Verschiebefeld pro Leiste (Waffenhand, Schildhand, Distanz) und die Größe unten.",
	["One pair"] = "Ein Paar",
	["One panel in your skin's material behind bars 1 and 2, so both rows sit in a single tray. Twin Orbs turns it on; Vanilla Original keeps its classic tray under bar 1."] = "Ein Panel im Material Eures Skins hinter Leiste 1 und 2, sodass beide Reihen in einer gemeinsamen Ablage sitzen. Twin Orbs schaltet es ein; Vanilla Original behält seine klassische Ablage unter Leiste 1.",
	["One place earlier in the bag window."] = "Eine Stelle früher im Taschenfenster.",
	["One place earlier in the group."] = "Eine Stelle früher in der Gruppe.",
	["One place later in the bag window."] = "Eine Stelle später im Taschenfenster.",
	["One place later in the group."] = "Eine Stelle später in der Gruppe.",
	["One rank less in the draft. Nothing is refunded."] = "Ein Rang weniger im Entwurf. Nichts wird erstattet.",
	["One rank more in the draft. Nothing is spent."] = "Ein Rang mehr im Entwurf. Nichts wird ausgegeben.",
	["One row per character: sort by any column, filter with the chips, hover for details, right-click for groups, bank marks and Forget."] = "Eine Zeile pro Charakter: Sortiert nach jeder Spalte, filtert mit den Chips, fahrt für Details mit der Maus darüber, Rechtsklick für Gruppen, Bankmarkierungen und Vergessen.",
	["One rune left, back in the starting hole!"] = "Eine Rune übrig, zurück im Startloch!",
	["One rune left, in the middle!"] = "Eine Rune übrig, in der Mitte!",
	["One sample for every source you have on, in the current look."] = "Ein Beispiel für jede Quelle, die Ihr eingeschaltet habt, in der aktuellen Optik.",
	["One search box for game panels, settings, mounts, toys, bag items, macros, places and EldoUI commands, with a small calculator. Using a mount, toy, item or macro is always your own click or key press."] = "Ein Suchfeld für Spiel-Panels, Einstellungen, Reittiere, Spielzeuge, Taschengegenstände, Makros, Orte und EldoUI-Befehle, mit einem kleinen Rechner. Ein Reittier, Spielzeug, Gegenstand oder Makro wird immer erst durch Euren eigenen Klick oder Tastendruck benutzt.",
	["One search term per line. Press Ctrl+C to copy; others paste it under Import."] = "Ein Suchbegriff pro Zeile. Drückt Strg+C zum Kopieren; andere fügen es unter Importieren ein.",
	["One segment per stack"] = "Ein Segment pro Stapel",
	["One session counts gold and XP for these blocks, the XP bar and My Adventure, and goes on over a reload. A longer log-out starts a new one. Right-click a rate block to start one yourself."] = "Eine Sitzung zählt Gold und Erfahrung für diese Blöcke, die Erfahrungsleiste und Mein Abenteuer und läuft über ein Neuladen hinweg weiter. Ein längerer Logout beginnt eine neue. Rechtsklickt auf einen Ratenblock, um selbst eine zu beginnen.",
	["One slot per bag type for free space"] = "Ein Platz pro Taschenart für freie Plätze",
	["One strip, counters side by side, with goals and session gain."] = "Ein Streifen, Zähler nebeneinander, mit Zielen und Sitzungsgewinn.",
	["One strip, counters stacked."] = "Ein Streifen, Zähler übereinander.",
	["One window per bag"] = "Ein Fenster pro Tasche",
	["One-grid view: the first bag slot sits at the bottom right instead of the top left."] = "Ein-Raster-Ansicht: Der erste Taschenplatz sitzt unten rechts statt oben links.",
	["One-grid view: the reagent bag gets its own section. Off puts its slots into the main grid."] = "Ein-Raster-Ansicht: Die Reagenzientasche erhält einen eigenen Abschnitt. Aus legt ihre Plätze ins Hauptraster.",
	["Ones"] = "Einser",
	["Online"] = "Online",
	["Online %d of %d"] = "Online: %d von %d",
	["Online only"] = "Nur online",
	["Only Alliance characters."] = "Nur Charaktere der Allianz.",
	["Only Disenchanting."] = "Nur Entzaubern.",
	["Only Horde characters."] = "Nur Charaktere der Horde.",
	["Only Pick Lock, in bags and trades."] = "Nur Schlossknacken, in Taschen und im Handel.",
	["Only PvP warnings and your own death card; a compact, see-through log."] = "Nur PvP-Warnungen und Eure eigene Todeskarte; ein kompaktes, durchsichtiges Protokoll.",
	["Only auras you cast. Off: the same spell from anyone counts."] = "Nur Auren, die Ihr wirkt. Aus: Derselbe Zauber von jedem zählt.",
	["Only auras you or your pet applied. Off: the same spell from anyone counts."] = "Nur Auren, die Ihr oder Euer Begleiter angewendet habt. Aus: Derselbe Zauber von jedem zählt.",
	["Only below"] = "Nur unter",
	["Only characters at the highest level."] = "Nur Charaktere auf der höchsten Stufe.",
	["Only characters below the highest level."] = "Nur Charaktere unter der höchsten Stufe.",
	["Only characters saved to an instance."] = "Nur Charaktere, die in einer Instanz gespeichert sind.",
	["Only characters that have the item"] = "Nur Charaktere, die den Gegenstand haben",
	["Only characters whose rested bar is full (estimate for offline characters)."] = "Nur Charaktere, deren Erholungsbonus voll ist (Schätzung für Charaktere, die offline sind).",
	["Only characters with items in the mailbox."] = "Nur Charaktere mit Gegenständen im Briefkasten.",
	["Only characters with mail that returns or is deleted within 5 days."] = "Nur Charaktere mit Post, die innerhalb von 5 Tagen zurückgeht oder gelöscht wird.",
	["Only combo points, no power bar (Blizzard's player frame or EldoUI's shows power)."] = "Nur Kombopunkte, keine Ressourcenleiste (Blizzards Spielerrahmen oder der von EldoUI zeigt die Ressource).",
	["Only damage and healing you take, small and fast."] = "Nur erlittener Schaden und erhaltene Heilung, klein und schnell.",
	["Only deals I can use"] = "Nur Schnäppchen, die ich nutzen kann",
	["Only deaths within three levels of your character, in both views."] = "Nur Tode bis drei Stufen über oder unter Eurem Charakter, in beiden Ansichten.",
	["Only debuffs you can dispel"] = "Nur Schwächungszauber, die Ihr bannen könnt",
	["Only fishing pools."] = "Nur Fischschwärme.",
	["Only for the shared strip, and Separate movers is on."] = "Nur für die gemeinsame Leiste, und Eigene Verschiebefelder ist an.",
	["Only from these players (comma separated), or the words friends / guild. Empty: anyone. During boss fights the sender is hidden and this check doesn't fire."] = "Nur von diesen Spielern (durch Kommas getrennt) oder den Wörtern friends / guild. Leer: jeder. Während Bosskämpfen ist der Absender verborgen, und diese Prüfung greift nicht.",
	["Only from this character level."] = "Nur ab dieser Charakterstufe.",
	["Only full stacks are grouped; a stack that is not full keeps its own slot."] = "Nur volle Stapel werden gruppiert; ein nicht voller Stapel behält seinen eigenen Platz.",
	["Only herb nodes, and only those you can gather."] = "Nur Kräutervorkommen, und nur solche, die Ihr sammeln könnt.",
	["Only hidden buttons"] = "Nur ausgeblendete Aktionstasten",
	["Only if"] = "Nur wenn",
	["Only in combat"] = "Nur im Kampf",
	["Only in fishing mode"] = "Nur im Angelmodus",
	["Only in or out of combat."] = "Nur im oder außerhalb des Kampfes.",
	["Only in the right panel"] = "Nur im rechten Panel",
	["Only in this kind of place."] = "Nur an dieser Art von Ort.",
	["Only in this stance or form"] = "Nur in dieser Haltung oder Gestalt",
	["Only in zones whose name contains one of these words (comma separated). Empty: anywhere."] = "Nur in Gebieten, deren Name eines dieser Wörter enthält (durch Kommas getrennt). Leer: überall.",
	["Only items of this quality or better."] = "Nur Gegenstände dieser Qualität oder besser.",
	["Only members the guild allows can change this text."] = "Nur Mitglieder, denen die Gilde es erlaubt, können diesen Text ändern.",
	["Only mine"] = "Nur meine",
	["Only near a camp"] = "Nur in der Nähe eines Lagers",
	["Only nodes that still give skill"] = "Nur Vorkommen, die noch Fertigkeit bringen",
	["Only on a Hardcore character."] = "Nur auf einem Hardcore-Charakter.",
	["Only ore and treasure, and only veins you can mine."] = "Nur Erz und Schätze, und nur Adern, die Ihr abbauen könnt.",
	["Only pulls in indoors, so walls don't block the view."] = "Zoomt nur in Innenräumen heran, damit Wände die Sicht nicht verdecken.",
	["Only quality borders: no item level, coins, tints, bind text or glow."] = "Nur Qualitätsränder: keine Gegenstandsstufe, Münzen, Tönungen, Bindungstext oder Leuchten.",
	["Only solo, in a party or in a raid."] = "Nur solo, in einer Gruppe oder in einem Schlachtzug.",
	["Only standing in bad stuff and its stacks, with the flash; breath, fatigue and AFK stay quiet."] = "Nur das Stehen in schädlichen Flächen und dessen Stapel, mit Aufblitzen; Atem, Erschöpfung und AFK bleiben still.",
	["Only the %s tree."] = "Nur der Baum %s.",
	["Only the game's own Click Casting, listed in the tooltip."] = "Nur die eigenen Klickzauber des Spiels, im Tooltip aufgeführt.",
	["Only the held modifier"] = "Nur der gehaltene Modifikator",
	["Only the next event counts down, so two countdowns never overlap. Off counts down every event."] = "Nur das nächste Ereignis zählt herunter, damit sich zwei Countdowns nie überlagern. Aus zählt jedes Ereignis herunter.",
	["Only the soonest event"] = "Nur das nächste Ereignis",
	["Only the track line and the icons: no background, no tick numbers, a smaller big icon without glow."] = "Nur die Spurlinie und die Symbole: kein Hintergrund, keine Skalenzahlen, ein kleineres großes Symbol ohne Leuchten.",
	["Only this character so far"] = "Bisher nur dieser Charakter",
	["Only trinkets with a use effect"] = "Nur Schmuckstücke mit Benutzen-Effekt",
	["Only undo and drafts; long messages are cut at 255 letters as the game does."] = "Nur Rückgängig und Entwürfe; lange Nachrichten werden wie im Spiel bei 255 Zeichen abgeschnitten.",
	["Only up to this character level."] = "Nur bis zu dieser Charakterstufe.",
	["Only what you don't have yet, as a small corner."] = "Nur, was Ihr noch nicht habt, als kleine Ecke.",
	["Only when something happened"] = "Nur, wenn etwas passiert ist",
	["Only when the Improve switch for party or raid frames is on (Blizzard UI page). Key and wheel bindings stay on EldoUI's frames."] = "Nur, wenn der Schalter „Verbessern“ für Gruppen- oder Schlachtzugsrahmen an ist (Seite Blizzard-UI). Tasten- und Mausradbelegungen bleiben auf den Rahmen von EldoUI.",
	["Only when the Move switch is on: Blizzard's frames then sit on EldoUI's party and raid movers at this scale."] = "Nur, wenn der Schalter „Verschieben“ an ist: Blizzards Rahmen sitzen dann in dieser Skalierung auf den Gruppen- und Schlachtzugs-Verschiebefeldern von EldoUI.",
	["Only when the Skin switch for party and raid frames is on (Blizzard UI page)."] = "Nur, wenn der Skin-Schalter für Gruppen- und Schlachtzugsrahmen an ist (Seite Blizzard-UI).",
	["Only when the game or EldoUI's tooltip doesn't show it already."] = "Nur, wenn das Spiel oder der Tooltip von EldoUI es nicht schon anzeigt.",
	["Only when there is threat"] = "Nur bei Bedrohung",
	["Only while it is your power"] = "Nur, solange es Eure Ressource ist",
	["Only while mounted or not."] = "Nur beritten oder nicht.",
	["Only while resting (inn, city) or not."] = "Nur beim Ausruhen (Gasthaus, Stadt) oder nicht.",
	["Only while up"] = "Nur solange aktiv",
	["Only zooms in while you talk to an NPC."] = "Zoomt nur heran, während Ihr mit einem NSC sprecht.",
	["Opacity of every line, in percent."] = "Deckkraft jeder Zeile, in Prozent.",
	["Opacity of members out of range. The game decides who is in range."] = "Deckkraft von Mitgliedern außer Reichweite. Das Spiel entscheidet, wer in Reichweite ist.",
	["Opacity of the bar while it is shown and not faded. At 0 % the bar takes no clicks and shows no tooltips, like a hidden bar."] = "Deckkraft der Leiste, solange sie angezeigt und nicht abgeblendet ist. Bei 0 % nimmt die Leiste keine Klicks an und zeigt keine Tooltips, wie eine ausgeblendete Leiste.",
	["Opacity of the box behind the meter windows, in percent."] = "Deckkraft des Kastens hinter den Messfenstern, in Prozent.",
	["Opacity of the crosshair, in percent."] = "Deckkraft des Fadenkreuzes, in Prozent.",
	["Opacity of the ring itself, in percent."] = "Deckkraft des Rings selbst, in Prozent.",
	["Opacity of the spell alerts while they use the EldoUI mover."] = "Deckkraft der Zauberwarnungen, solange sie das Verschiebefeld von EldoUI nutzen.",
	["Opacity of the window background, in percent."] = "Deckkraft des Fensterhintergrunds, in Prozent.",
	["Opacity while shown and not faded. At 0 % the bar takes no clicks and shows no tooltips, like a hidden bar."] = "Deckkraft, solange angezeigt und nicht abgeblendet. Bei 0 % nimmt die Leiste keine Klicks an und zeigt keine Tooltips, wie eine ausgeblendete Leiste.",
	["Open Alerts tab"] = "Reiter „Hinweise“ öffnen",
	["Open Blizzard UI > System and settings windows, where 'Edit Mode integration' is switched on."] = "Öffnet Blizzard-UI > System- und Einstellungsfenster, wo „Einbindung des Bearbeitungsmodus“ eingeschaltet wird.",
	["Open a lockbox someone puts in the trade window's \"Will not be traded\" slot."] = "Eine Kassette öffnen, die jemand in den Platz „Wird nicht gehandelt“ des Handelsfensters legt.",
	["Open a profession window once and its recipes show here."] = "Öffnet einmal ein Berufsfenster, und seine Rezepte erscheinen hier.",
	["Open and close with"] = "Öffnen und schließen mit",
	["Open at the mouse"] = "Am Mauszeiger öffnen",
	["Open every safe field; the numbers count the mines around."] = "Deckt jedes sichere Feld auf; die Zahlen zählen die Minen ringsum.",
	["Open in Bags"] = "In Taschen öffnen",
	["Open in Buy"] = "Im Reiter Kaufen öffnen",
	["Open loot history"] = "Beuteverlauf öffnen",
	["Open menu"] = "Menü öffnen",
	["Open on the first group roll"] = "Bei der ersten Würfelrunde der Gruppe öffnen",
	["Open on the map"] = "Auf der Karte öffnen",
	["Open the Alts window"] = "Twink-Fenster öffnen",
	["Open the Death Log window. /eui deaths does the same."] = "Öffnet das Fenster Todesprotokoll. /eui deaths tut dasselbe.",
	["Open the Dungeons window"] = "Fenster Dungeons öffnen",
	["Open the Finder with your key or /eui go. A result that uses a mount, toy, item or macro needs your click or Enter, out of combat."] = "Öffnet den Finder mit Eurer Taste oder /eui go. Ein Ergebnis, das ein Reittier, Spielzeug, einen Gegenstand oder ein Makro benutzt, braucht Euren Klick oder Enter, außerhalb des Kampfes.",
	["Open the Legacy Planner"] = "Vermächtnisplaner öffnen",
	["Open the Trade board"] = "Handelsbörse öffnen",
	["Open the auction house on"] = "Auktionshaus öffnen mit",
	["Open the bank, mail, trade or a vendor first."] = "Öffnet zuerst die Bank, die Post, den Handel oder einen Händler.",
	["Open the blessing plan"] = "Segensplan öffnen",
	["Open the chat (Enter): the emoji goes in there."] = "Öffnet den Chat (Enter): Das Emoji kommt dort hinein.",
	["Open the death log"] = "Todesprotokoll öffnen",
	["Open the error log in its own window, with filters and room for long errors."] = "Das Fehlerprotokoll in einem eigenen Fenster öffnen, mit Filtern und Platz für lange Fehler.",
	["Open the game's own bank window, e.g. to buy bank space."] = "Das eigene Bankfenster des Spiels öffnen, z. B. um Bankplatz zu kaufen.",
	["Open the games at take-off"] = "Spiele beim Abflug öffnen",
	["Open the guide list"] = "Guide-Liste öffnen",
	["Open the keys and spells preview at the spell ranks: check the buttons to move, then press Apply (out of combat). Same as /eui ranks."] = "Öffnet die Vorschau für Tasten und Zauber bei den Zauberrängen: Hakt die Aktionstasten an, die wechseln sollen, und drückt dann Übernehmen (außerhalb des Kampfes). Wie /eui ranks.",
	["Open the list of watched items and currencies, set goals and remove entries."] = "Die Liste der beobachteten Gegenstände und Währungen öffnen, Ziele setzen und Einträge entfernen.",
	["Open the run log"] = "Durchlaufprotokoll öffnen",
	["Open the window again when combat ends."] = "Das Fenster nach Kampfende wieder öffnen.",
	["Open window"] = "Fenster öffnen",
	["Open with the Legacy window"] = "Mit dem Vermächtnisfenster öffnen",
	["Open your guild bank and click through its tabs once; each tab you see is saved here."] = "Öffnet Eure Gildenbank und klickt einmal durch ihre Reiter; jeder Reiter, den Ihr seht, wird hier gespeichert.",
	["Opening"] = "Öffnen",
	["Opens Alerts and Banners > Ready check, where you set the ready sound and the countdown on Blizzard's queue pop-up."] = "Öffnet Hinweise und Banner > Bereitschaftscheck, wo Ihr den Bereitschaftston und den Countdown auf Blizzards Warteschlangenfenster einstellt.",
	["Opens Blizzard's Cooldown Manager settings: which spells show in which viewer."] = "Öffnet die Einstellungen von Blizzards Abklingzeitenmanager: welche Zauber in welcher Anzeige erscheinen.",
	["Opens Camera Situations, where Talking to an NPC sets the distance."] = "Öffnet Kamerasituationen, wo „Gespräch mit einem NSC“ die Entfernung festlegt.",
	["Opens EldoUI's Legacy Planner beside this window: a draft build, profiles and the challenge browser. It never spends points."] = "Öffnet EldoUIs Vermächtnisplaner neben diesem Fenster: ein Entwurf, Profile und der Herausforderungsbrowser. Er gibt nie Punkte aus.",
	["Opens Eldostar's page, where you pick the one guide that takes the layout's guide spot: Automatic, Eldostar, RestedXP, Guidelime or Off."] = "Öffnet die Seite von Eldostar, wo Ihr den einen Guide wählt, der den Guide-Platz des Layouts einnimmt: Automatisch, Eldostar, RestedXP, Guidelime oder Aus.",
	["Opens a whisper to the crafter you clicked, with the recipe link in the edit box. You press Enter."] = "Öffnet ein Flüstern an den angeklickten Handwerker, mit dem Rezeptlink im Eingabefeld. Enter drückt Ihr selbst.",
	["Opens after combat."] = "Öffnet sich nach dem Kampf.",
	["Opens on"] = "Öffnet mit",
	["Opens or closes Blizzard's loot history (also /eui loothistory)."] = "Öffnet oder schließt Blizzards Beuteverlauf (auch /eui loothistory).",
	["Opens the Alerts tab now (outside combat) and shows it."] = "Öffnet jetzt den Reiter „Hinweise“ (außerhalb des Kampfes) und zeigt ihn an.",
	["Opens the Dungeons window on this dungeon, to pick, edit and share routes. Out of combat."] = "Öffnet das Fenster Dungeons bei diesem Dungeon, um Routen zu wählen, zu bearbeiten und zu teilen. Außerhalb des Kampfes.",
	["Opens the Glows page, where the Bag actions glow gets its style and color."] = "Öffnet die Seite „Leuchteffekte“, wo das Leuchten der Taschenaktionen seinen Stil und seine Farbe erhält.",
	["Opens the Glows page, where the dispel and boss aura glows get their style and color."] = "Öffnet die Seite „Leuchteffekte“, wo das Leuchten für bannbare Schwächungszauber und Boss-Auren seinen Stil und seine Farbe erhält.",
	["Opens the binding window. Also /eui clickcast."] = "Öffnet das Belegungsfenster. Auch /eui clickcast.",
	["Opens the category editor: add, rename, color, order and share your categories, and turn the built-in sections on or off."] = "Öffnet den Kategorieeditor: Fügt Eure Kategorien hinzu, benennt, färbt, ordnet und teilt sie und schaltet die eingebauten Abschnitte ein oder aus.",
	["Opens the channel list; /chatlist and the social panel still work."] = "Öffnet die Kanalliste; /chatlist und das Kontaktfenster funktionieren weiterhin.",
	["Opens the game's own Click Casting window; its bindings work on EldoUI's frames too."] = "Öffnet das eigene Klickzauber-Fenster des Spiels; seine Belegungen funktionieren auch auf den Rahmen von EldoUI.",
	["Opens the game's own gold deposit."] = "Öffnet die eigene Goldeinzahlung des Spiels.",
	["Opens the game's own gold withdrawal."] = "Öffnet die eigene Goldabhebung des Spiels.",
	["Opens the games here and now, on a flight path or not. Typing /eui games does the same."] = "Öffnet die Spiele hier und jetzt, auf einer Flugroute oder nicht. /eui games tut dasselbe.",
	["Opens the guide list in the Journal, where you start another guide."] = "Öffnet die Guide-Liste im Tagebuch, wo Ihr einen anderen Guide startet.",
	["Opens the guide list in the Journal."] = "Öffnet die Guide-Liste im Tagebuch.",
	["Opens the plan window. Click a square to pick a blessing, right-click to clear it. Also /eui blessings."] = "Öffnet das Planfenster. Klickt auf ein Feld, um einen Segen zu wählen, Rechtsklick leert es. Auch /eui blessings.",
	["Opens the planner beside Blizzard's Legacy window whenever that window opens, and closes it again with it."] = "Öffnet den Planer neben Blizzards Vermächtnisfenster, sobald dieses Fenster aufgeht, und schließt ihn wieder mit ihm.",
	["Opens the roll window when someone in your group starts a round of rolls. The Rolls block opens it with a click."] = "Öffnet das Würfelfenster, wenn jemand in Eurer Gruppe eine Würfelrunde startet. Der Block Würfe öffnet es mit einem Klick.",
	["Opens the window (/eui alts)."] = "Öffnet das Fenster (/eui alts).",
	["Opens your bags when the %s window opens (by default %s)."] = "Öffnet Eure Taschen, wenn das Fenster %s aufgeht (standardmäßig %s).",
	["Optional: it never holds the step up."] = "Optional: Hält den Schritt nie auf.",
	["Or spell ID"] = "Oder Zauber-ID",
	["Or: items either side finds"] = "Oder: Gegenstände, die eine der beiden Seiten findet",
	["Orange"] = "Orange",
	["Order gained"] = "Reihenfolge des Erhalts",
	["Order of the buffs (the game sorts them, also in combat). Custom filter groups have their own sort."] = "Reihenfolge der Stärkungszauber (das Spiel sortiert sie, auch im Kampf). Eigene Filtergruppen haben ihre eigene Sortierung.",
	["Order of the debuffs (the game sorts them, also in combat). Custom filter groups have their own sort."] = "Reihenfolge der Schwächungszauber (das Spiel sortiert sie, auch im Kampf). Eigene Filtergruppen haben ihre eigene Sortierung.",
	["Order of the members. Role, Class, Name and Join order sort the whole raid, ignoring groups. Changes wait until combat ends."] = "Reihenfolge der Mitglieder. Rolle, Klasse, Name und Beitrittsreihenfolge sortieren den ganzen Schlachtzug ohne Rücksicht auf Gruppen. Änderungen warten bis zum Kampfende.",
	["Ore"] = "Erz",
	["Orgrimmar is named after which orc?"] = "Nach welchem Orc ist Orgrimmar benannt?",
	["Other addons (LibDataBroker)"] = "Andere Addons (LibDataBroker)",
	["Other bar addons"] = "Andere Leisten-Addons",
	["Other characters"] = "Andere Charaktere",
	["Other frames"] = "Andere Rahmen",
	["Other panels in the window"] = "Andere Panels im Fenster",
	["Other timers"] = "Andere Timer",
	["Out in the world"] = "Draußen in der Welt",
	["Out of breath"] = "Außer Atem",
	["Out of combat only"] = "Nur außerhalb des Kampfes",
	["Out of combat only."] = "Nur außerhalb des Kampfes.",
	["Out of combat, marks members who lack a group buff you can give (from Buff and Consumable Reminders, or the buffs you can cast). Hidden in combat."] = "Markiert außerhalb des Kampfes Mitglieder, denen ein Gruppen-Stärkungszauber fehlt, den Ihr geben könnt (aus den Erinnerungen an Stärkungszauber und Verbrauchsgüter oder den Stärkungszaubern, die Ihr wirken könnt). Im Kampf ausgeblendet.",
	["Out of range"] = "Außer Reichweite",
	["Out of range (all rows)"] = "Außer Reichweite (alle Reihen)",
	["Out of range color"] = "Farbe außer Reichweite",
	["Out-of-range tint"] = "Tönung außer Reichweite",
	["Outline around the big text, so it reads on any background."] = "Kontur um den großen Text, damit er auf jedem Hintergrund lesbar ist.",
	["Outline around the bubble text. Helps when the background is off."] = "Kontur um den Sprechblasentext. Hilft, wenn der Hintergrund aus ist.",
	["Outline around the chat text (skin switch)."] = "Kontur um den Chattext (Skin-Schalter).",
	["Outline around the item level (and the bind text)."] = "Kontur um die Gegenstandsstufe (und den Bindungstext).",
	["Outline around the stack count."] = "Kontur um die Stapelanzahl.",
	["Outline of Blizzard's combat text."] = "Kontur von Blizzards Kampftext.",
	["Outline of every button text. Theme follows the outline set on the Fonts and text page."] = "Kontur jedes Tastentexts. „Thema“ folgt der Kontur, die auf der Seite Schriften und Text eingestellt ist.",
	["Outline of the cooldown texts."] = "Kontur der Abklingzeittexte.",
	["Outline of the text. An outline keeps it readable over the world."] = "Kontur des Texts. Eine Kontur hält ihn über der Spielwelt lesbar.",
	["Outlines: %s, %s, %s, %s, %s. Run it again to turn off."] = "Konturen: %s, %s, %s, %s, %s. Führt es erneut aus, um sie abzuschalten.",
	["Over the tabs"] = "Über den Reitern",
	["Over the tabs: the box covers the tab strip while you type. Top of screen: centered near the top."] = "Über den Reitern: Das Feld verdeckt die Reiterleiste, während Ihr tippt. Oben am Bildschirm: zentriert nahe dem oberen Rand.",
	["Overwrite"] = "Überschreiben",
	["Own bar color"] = "Farbe der eigenen Leiste",
	["Own colors and thresholds"] = "Eigene Farben und Schwellenwerte",
	["Own groups"] = "Eigene Gruppen",
	["Own groups are on: the icons of every row are listed on the Groups tab."] = "Eigene Gruppen sind an: Die Symbole jeder Reihe sind auf dem Reiter Gruppen aufgeführt.",
	["Own groups on; every group and row lines its icons up from the center."] = "Eigene Gruppen an; jede Gruppe und Reihe reiht ihre Symbole von der Mitte aus auf.",
	["Own groups on; every group and row starts at the left edge of its mover and grows to the right."] = "Eigene Gruppen an; jede Gruppe und Reihe beginnt am linken Rand ihres Verschiebefelds und wächst nach rechts.",
	["Own label text"] = "Eigener Beschriftungstext",
	["Own mover (Tracking bars)"] = "Eigenes Verschiebefeld (Verfolgungsleisten)",
	["Own mover: drag it in move mode (%s). Otherwise the viewer follows the chosen frame."] = "Eigenes Verschiebefeld: Zieht es im Verschiebemodus (%s). Sonst folgt die Anzeige dem gewählten Rahmen.",
	["Own mover: drag it in move mode. The other choices follow the chat or the bag position."] = "Eigenes Verschiebefeld: Zieht es im Verschiebemodus. Die anderen Optionen folgen der Position des Chats oder der Taschen.",
	["Own movers for the mirror timers and the quest timer, and the size below."] = "Eigene Verschiebefelder für die Atem- und Erschöpfungsleisten und den Questtimer sowie die Größe unten.",
	["Own movers for the recap window and the Return to Graveyard button."] = "Eigene Verschiebefelder für das Rückblickfenster und die Schaltfläche „Zum Friedhof zurückkehren“.",
