	["Pass"] = "Passen",
	["Passed: %s"] = "Gepasst: %s",
	["Past 255 letters, Enter sends the first part and puts the rest back in the box for your next Enter. Parts end on a space and keep links whole."] = "Über 255 Zeichen sendet Enter den ersten Teil und legt den Rest für Euer nächstes Enter zurück ins Feld. Teile enden an einem Leerzeichen und lassen Links ganz.",
	["Paste a Legacy build string (Ctrl+V) and click Save. You see what it holds before it is saved as a profile; nothing is spent."] = "Fügt einen Vermächtnis-Build-String ein (Strg+V) und klickt auf Speichern. Ihr seht seinen Inhalt, bevor er als Profil gespeichert wird; nichts wird ausgegeben.",
	["Paste a Legacy build string. It is saved as a profile; nothing is spent."] = "Fügt einen Vermächtnis-Build-String ein. Er wird als Profil gespeichert; nichts wird ausgegeben.",
	["Paste a bag category string. You see what it holds before anything changes."] = "Fügt einen String mit Taschenkategorien ein. Ihr seht seinen Inhalt, bevor sich etwas ändert.",
	["Paste a list (one search term per line) and click Save."] = "Fügt eine Liste ein (ein Suchbegriff pro Zeile) und klickt auf Speichern.",
	["Paste a node string (Ctrl+V) and click Save. You see what it holds before anything is added."] = "Fügt einen Vorkommen-String ein (Strg+V) und klickt auf Speichern. Ihr seht seinen Inhalt, bevor etwas hinzugefügt wird.",
	["Paste a node string from a friend. You see what it holds first; the nodes are added to yours and nothing is removed."] = "Fügt einen Vorkommen-String von einem Freund ein. Ihr seht zuerst seinen Inhalt; die Vorkommen werden Euren hinzugefügt, und nichts wird entfernt.",
	["Paste a route string (!EUR1!...) and click Save. You see what it holds before anything is added."] = "Fügt einen Routen-String ein (!EUR1!...) und klickt auf Speichern. Ihr seht seinen Inhalt, bevor etwas hinzugefügt wird.",
	["Paste a route string someone shared (!EUR1!). You see what it holds before it is added."] = "Fügt einen Routen-String ein, den jemand geteilt hat (!EUR1!). Ihr seht seinen Inhalt, bevor er hinzugefügt wird.",
