	["Plain left and right clicks still target and open the menu."] = "Einfache Links- und Rechtsklicks wählen weiterhin das Ziel und öffnen das Menü.",
	["Plan from %s"] = "Plan von %s",
	["Plan which blessing each paladin keeps up on each class, and send it to the group or chat on your click. Nothing is cast for you."] = "Plant, welchen Segen jeder Paladin auf jeder Klasse aufrechterhält, und sendet ihn per Klick an die Gruppe oder in den Chat. Nichts wird für Euch gewirkt.",
	["Plan which blessing each paladin of your group keeps up on each class, then send the plan to the group or post it in chat with one click."] = "Plant, welchen Segen jeder Paladin Eurer Gruppe auf jeder Klasse aufrechterhält, und sendet den Plan dann mit einem Klick an die Gruppe oder postet ihn im Chat.",
	["Plan your Legacy points, keep named profiles for your characters and browse Legacy Challenges. You spend points in Blizzard's Legacy window."] = "Plant Eure Vermächtnispunkte, behaltet benannte Profile für Eure Charaktere und durchstöbert die Vermächtnis-Herausforderungen. Punkte gebt Ihr in Blizzards Vermächtnisfenster aus.",
	["Plan your Legacy points: a draft build next to your current one, named profiles for all your characters, a cost check against the season cap and a challenge browser. It never spends a point."] = "Plant Eure Vermächtnispunkte: ein Entwurf neben Eurem aktuellen Build, benannte Profile für alle Eure Charaktere, eine Kostenprüfung gegen die Saisonobergrenze und ein Herausforderungsbrowser. Er gibt nie einen Punkt aus.",
	["Planner button"] = "Planer-Schaltfläche",
	["Plate focus"] = "Plakettenfokus",
	["Plate hits"] = "Plakettentreffer",
	["Play a sound when a new hostile player appears. Off by default."] = "Einen Ton abspielen, wenn ein neuer feindlicher Spieler auftaucht. Standardmäßig aus.",
	["Play a sound with the flash, at most once every half second. Off by default."] = "Mit dem Aufblitzen einen Ton abspielen, höchstens einmal pro halbe Sekunde. Standardmäßig aus.",
	["Play now"] = "Jetzt spielen",
	["Play the danger alarm once."] = "Den Gefahrenalarm einmal abspielen.",
	["Play the fatigue alarm once."] = "Den Erschöpfungsalarm einmal abspielen.",
	["Play the game's cast and targeting animation on EldoUI buttons."] = "Die Zauber- und Zielanimation des Spiels auf EldoUI-Tasten abspielen.",
	["Play the stack sound each time the same bad aura gains another stack."] = "Den Stapelton jedes Mal abspielen, wenn dieselbe schädliche Aura einen weiteren Stapel erhält.",
	["Play the stack sound once."] = "Den Stapelton einmal abspielen.",
	["Play this trigger now with sample values, ignoring its conditions."] = "Diesen Auslöser jetzt mit Beispielwerten abspielen, ohne seine Bedingungen zu beachten.",
	["Play while you fly"] = "Spielen, während Ihr fliegt",
	["Played"] = "Gespielt",
	["Played %d, found %d, run %d"] = "Gespielt %d, gefunden %d, Serie %d",
	["Played instead when the first sound's addon is not installed."] = "Wird stattdessen abgespielt, wenn das Addon des ersten Tons nicht installiert ist.",
	["Played when a bad aura from the spell list stacks again."] = "Wird abgespielt, wenn eine schädliche Aura aus der Zauberliste erneut stapelt.",
	["Played when a line mentions your name. Every other keyword has its own sound in Edit keywords. At most one sound every 2 seconds."] = "Wird abgespielt, wenn eine Zeile Euren Namen erwähnt. Jedes andere Stichwort hat seinen eigenen Ton unter „Stichwörter bearbeiten“. Höchstens ein Ton alle 2 Sekunden.",
	["Played when someone else writes in %s chat."] = "Wird abgespielt, wenn jemand anderes in diesem Chat schreibt: %s.",
	["Played when you stand in something from the spell list, when your breath runs out and when something attacks you while you are AFK. Sound files only: the game plays aura sounds from a file."] = "Wird abgespielt, wenn Ihr in etwas aus der Zauberliste steht, wenn Euch die Luft ausgeht und wenn Euch etwas angreift, während Ihr AFK seid. Nur Tondateien: Das Spiel spielt Aurentöne aus einer Datei ab.",
	["Played when you swim into deep water fatigue."] = "Wird abgespielt, wenn Ihr in tiefes Wasser schwimmt und die Erschöpfung einsetzt.",
	["Played with each PvP warning."] = "Wird mit jeder PvP-Warnung abgespielt.",
	["Played with each death card."] = "Wird mit jeder Todeskarte abgespielt.",
	["Player vs. Player"] = "Spieler gegen Spieler",
	["Player, e.g. Name-Realm"] = "Spieler, z. B. Name-Realm",
	["Player, target and focus frames"] = "Spieler-, Ziel- und Fokusrahmen",
	["Player, target, focus, pet and target-of-target frames."] = "Spieler-, Ziel-, Fokus-, Begleiter- und Ziel-des-Ziels-Rahmen.",
	["Players"] = "Spieler",
	["Players hidden in one public channel only (up to 50). Also /eui chat mute <channel>; <name>, or right-click a sender in a channel line."] = "Spieler, die nur in einem öffentlichen Kanal ausgeblendet sind (bis zu 50). Auch /eui chat mute <channel>; <name> oder Rechtsklick auf einen Absender in einer Kanalzeile.",
	["Players of the other faction can attack you now."] = "Spieler der anderen Fraktion können Euch jetzt angreifen.",
	["Playing %s on the %s channel."] = "%s wird auf dem Kanal %s abgespielt.",
	["Plays a 3-second test cast on every enabled cast bar, each in the theme it would use (out of combat; also /eui castfx test)."] = "Spielt auf jeder aktivierten Zauberleiste einen 3-Sekunden-Testzauber ab, jeweils im Thema, das sie nutzen würde (außerhalb des Kampfes; auch /eui castfx test).",
	["Plays a busy sample raid boss: close timers in two lanes and waiting events. Click again to stop."] = "Spielt einen geschäftigen Beispiel-Schlachtzugsboss ab: dichte Timer in zwei Spuren und wartende Ereignisse. Erneut klicken zum Stoppen.",
	["Plays a pull countdown and a break timer. Click again to stop."] = "Spielt einen Pull-Countdown und einen Pausentimer ab. Erneut klicken zum Stoppen.",
	["Plays a sample dungeon boss on the timeline so you can judge the look and the place. Click again to stop."] = "Spielt einen Beispiel-Dungeonboss auf der Zeitleiste ab, damit Ihr Optik und Platz beurteilen könnt. Erneut klicken zum Stoppen.",
	["Plays the sounds you picked for single events (Events tab, the cog of an event)."] = "Spielt die Töne ab, die Ihr für einzelne Ereignisse gewählt habt (Reiter Ereignisse, das Zahnrad eines Ereignisses).",
	["Plays when a spell or item is ready."] = "Wird abgespielt, wenn ein Zauber oder Gegenstand bereit ist.",
	["Point at an item, spell, quest, achievement, currency or talent link in chat to see its tooltip, where your tooltips usually show."] = "Zeigt auf einen Gegenstands-, Zauber-, Quest-, Erfolgs-, Währungs- oder Talentlink im Chat, um seinen Tooltip dort zu sehen, wo Eure Tooltips sonst erscheinen.",
	["Points in this tree now %d, in the draft %d."] = "Punkte in diesem Baum jetzt %d, im Entwurf %d.",
