	["Profession"] = "Beruf",
	["Profession cooldowns"] = "Berufsabklingzeiten",
	["Profession cooldowns ready now, of those recorded."] = "Berufsabklingzeiten, die jetzt bereit sind, von den erfassten.",
	["Profession icons; small dots colored by kind (green herbs, orange ore, blue treasure, violet fishing); or bright dots with a white ring that stand out on any map."] = "Berufssymbole; kleine Punkte nach Art gefärbt (grün Kräuter, orange Erz, blau Schätze, violett Angeln); oder helle Punkte mit weißem Ring, die auf jeder Karte hervorstechen.",
	["Professions show here after each character logs in. Recipe lists fill in when a character opens its profession window."] = "Berufe erscheinen hier, nachdem sich jeder Charakter eingeloggt hat. Rezeptlisten füllen sich, wenn ein Charakter sein Berufsfenster öffnet.",
	["Profile"] = "Profil",
	["Profiles are saved for all your characters. Loading one only changes the draft; you spend points in Blizzard's Legacy window."] = "Profile werden für alle Eure Charaktere gespeichert. Das Laden eines Profils ändert nur den Entwurf; Punkte gebt Ihr in Blizzards Vermächtnisfenster aus.",
	["Progress"] = "Fortschritt",
	["Progress comes from the game's achievement data. Spend Legacy points in Blizzard's Legacy window."] = "Der Fortschritt stammt aus den Erfolgsdaten des Spiels. Gebt Vermächtnispunkte in Blizzards Vermächtnisfenster aus.",
	["Progression"] = "Fortschritt",
	["Prospect"] = "Sondieren",
	["Prospecting"] = "Sondieren",
	["Prowl uses its own page"] = "Eigene Seite für Schleichen",
	["Public channels"] = "Öffentliche Kanäle",
	["Public channels (Trade, General, LFG)"] = "Öffentliche Kanäle (Handel, Allgemein, SucheNachGruppe)",
	["Public channels and whispers from strangers"] = "Öffentliche Kanäle und Flüstern von Fremden",
	["Public channels, say and yell"] = "Öffentliche Kanäle, Sagen und Schreien",
	["Public channels, say, yell and emotes from members of these guilds are hidden, and their bubbles outside instances. EldoUI learns guilds from players you see (mouse-over, target, nameplates, group); a player not seen yet is shown."] = "Öffentliche Kanäle, Sagen, Schreien und Emotes von Mitgliedern dieser Gilden werden ausgeblendet, außerhalb von Instanzen auch ihre Sprechblasen. EldoUI erfährt Gilden von Spielern, die Ihr seht (Mouseover, Ziel, Namensplaketten, Gruppe); ein noch nicht gesehener Spieler wird angezeigt.",
	["Pull %d"] = "Pull %d",
