	["Show session gain"] = "Zuwachs der Sitzung anzeigen",
	["Show tabs only on mouse-over"] = "Reiter nur bei Mauskontakt anzeigen",
	["Show tenths of a second under ten seconds, or whole seconds only."] = "Unter zehn Sekunden Zehntelsekunden anzeigen oder nur ganze Sekunden.",
	["Show test timers"] = "Testtimer anzeigen",
	["Show texts, flashes and icons in combat for every trigger. When off, only triggers that allow it (ready check, queue pop, pull) show in combat. Sounds always play."] = "Texte, Aufblitzen und Symbole im Kampf für jeden Auslöser anzeigen. Wenn aus, erscheinen im Kampf nur Auslöser, die es erlauben (Bereitschaftscheck, Warteschlangenaufruf, Pull). Klänge werden immer abgespielt.",
	["Show the XP you gained and XP per hour."] = "Erhaltene EP und EP pro Stunde anzeigen.",
	["Show the bar also when no session runs, to start one with a click. On a flight path it steps aside for the flight bar. Move it in move mode (Farming Bar)."] = "Die Leiste auch anzeigen, wenn keine Sitzung läuft, um eine per Klick zu starten. Auf einer Flugroute macht sie der Flugleiste Platz. Verschiebt sie im Verschiebemodus (Farmleiste).",
	["Show the bar only while this is the power your character uses right now (a druid's energy only in cat form)."] = "Die Leiste nur anzeigen, solange Euer Charakter gerade diese Ressource nutzt (die Energie eines Druiden nur in Katzengestalt).",
	["Show the block"] = "Block anzeigen",
	["Show the buffs as icons with timers instead of rows."] = "Die Stärkungszauber als Symbole mit Timern statt als Zeilen anzeigen.",
	["Show the changes"] = "Änderungen anzeigen",
	["Show the count"] = "Anzahl anzeigen",
	["Show the countdown only once fewer seconds than this are left."] = "Den Countdown erst anzeigen, wenn weniger Sekunden als diese übrig sind.",
	["Show the game's spinning glow on pet abilities set to autocast."] = "Das kreisende Leuchten des Spiels auf Begleiterfähigkeiten mit automatischem Wirken anzeigen.",
	["Show the gold you looted and gold per hour."] = "Geplündertes Gold und Gold pro Stunde anzeigen.",
	["Show the icon faded"] = "Symbol verblasst anzeigen",
	["Show the icon in gray while it is on cooldown."] = "Das Symbol grau anzeigen, solange es Abklingzeit hat.",
	["Show the icon in gray while its action is on cooldown. The game says when; the global cooldown alone doesn't gray it."] = "Das Symbol grau anzeigen, solange seine Aktion Abklingzeit hat. Das Spiel meldet, wann; die globale Abklingzeit allein färbt es nicht grau.",
	["Show the icon in gray while you can't cast it."] = "Das Symbol grau anzeigen, solange Ihr es nicht wirken könnt.",
	["Show the items you looted, their value and value per hour."] = "Geplünderte Gegenstände, ihren Wert und den Wert pro Stunde anzeigen.",
	["Show the key bound to each button of this bar. On bars 1 to 3, Keybinds > Show the keys on bars 1 to 3 shows them even when this is off."] = "Die Tastenbelegung jedes Platzes dieser Leiste anzeigen. Auf den Leisten 1 bis 3 zeigt Tastenbelegungen > Tasten auf Leisten 1 bis 3 anzeigen sie auch dann, wenn dies aus ist.",
	["Show the key bound to each button. On bars 1 to 3, Keybinds > Show the keys on bars 1 to 3 shows them even when this is off."] = "Die Tastenbelegung jedes Platzes anzeigen. Auf den Leisten 1 bis 3 zeigt Tastenbelegungen > Tasten auf Leisten 1 bis 3 anzeigen sie auch dann, wenn dies aus ist.",
	["Show the last fight's time until the next fight starts."] = "Die Zeit des letzten Kampfes anzeigen, bis der nächste beginnt.",
	["Show the leader's resets"] = "Resets des Anführers anzeigen",
	["Show the list in five-player groups too."] = "Die Liste auch in Fünfergruppen anzeigen.",
	["Show the name"] = "Namen anzeigen",
	["Show the name icons in %s lines."] = "Die Namenssymbole in diesen Zeilen anzeigen: %s.",
	["Show the name icons in channel %d."] = "Die Namenssymbole in Kanal %d anzeigen.",
	["Show the name icons in chat tab %d (counted from the left in the chat settings)."] = "Die Namenssymbole in Chatreiter %d anzeigen (von links gezählt in den Chateinstellungen).",
	["Show the name of macros on their button."] = "Den Namen von Makros auf ihrem Platz anzeigen.",
	["Show the name of macros on this bar."] = "Den Namen von Makros auf dieser Leiste anzeigen.",
	["Show the nodes on the world map."] = "Die Vorkommen auf der Weltkarte anzeigen.",
	["Show the notes, arrows and free-hand lines of the route on the map. The editor always shows them."] = "Notizen, Pfeile und Freihandlinien der Route auf der Karte anzeigen. Der Editor zeigt sie immer.",
	["Show the number of stacks in the button's top right corner, as the game counts them."] = "Die Anzahl der Stapel in der oberen rechten Ecke des Platzes anzeigen, wie das Spiel sie zählt.",
	["Show the panel only near a campfire or while a camp buff is on you."] = "Das Panel nur in der Nähe eines Lagerfeuers anzeigen oder solange ein Lagereffekt auf Euch wirkt.",
	["Show the panels"] = "Panels anzeigen",
	["Show the right panel"] = "Rechtes Panel anzeigen",
	["Show the runs of your other characters too (in gray)."] = "Auch die Durchläufe Eurer anderen Charaktere anzeigen (grau).",
	["Show the saved bank of the selected character."] = "Die gespeicherte Bank des ausgewählten Charakters anzeigen.",
	["Show the sessions of one zone, or of all zones."] = "Die Sitzungen eines Gebiets oder aller Gebiete anzeigen.",
	["Show the tabs while one flashes"] = "Reiter anzeigen, während einer blinkt",
	["Show the time left on each bar."] = "Die verbleibende Zeit auf jeder Leiste anzeigen.",
	["Show the window"] = "Fenster anzeigen",
	["Show this area"] = "Diesen Bereich anzeigen",
	["Show this bar"] = "Diese Leiste anzeigen",
	["Show this buff on the bar."] = "Diesen Stärkungszauber auf der Leiste anzeigen.",
	["Show this cooldown on the bar once you know it."] = "Diese Abklingzeit auf der Leiste anzeigen, sobald Ihr den Zauber kennt.",
	["Show this group"] = "Diese Gruppe anzeigen",
	["Show this panel. Off keeps its settings without showing it."] = "Dieses Panel anzeigen. Aus behält seine Einstellungen, ohne es anzuzeigen.",
	["Show this section"] = "Diesen Abschnitt anzeigen",
	["Show this trigger's text, flash and icon in combat too. Sounds always play."] = "Text, Aufblitzen und Symbol dieses Auslösers auch im Kampf anzeigen. Klänge werden immer abgespielt.",
	["Show time"] = "Zeit anzeigen",
	["Show tooltip"] = "Tooltip anzeigen",
	["Show waiting events"] = "Wartende Ereignisse anzeigen",
	["Show what you gained or lost since login next to the count."] = "Neben der Anzahl anzeigen, was Ihr seit dem Einloggen gewonnen oder verloren habt.",
	["Show what you loot"] = "Beute anzeigen",
	["Show when solo"] = "Ohne Gruppe anzeigen",
	["Show when you can place your next camp feature (one per hour, shared by all features)."] = "Anzeigen, wann Ihr Euer nächstes Lagerelement platzieren könnt (eines pro Stunde, für alle Elemente gemeinsam).",
	["Show who is typing"] = "Anzeigen, wer schreibt",
	["Show your buffs in EldoUI's buff frame (mover: Buffs)."] = "Eure Stärkungszauber in EldoUIs Stärkungszauberrahmen anzeigen (Verschiebefeld: Stärkungszauber).",
	["Show your character"] = "Euren Charakter anzeigen",
	["Show your debuffs in EldoUI's debuff frame (mover: Debuffs)."] = "Eure Schwächungszauber in EldoUIs Schwächungszauberrahmen anzeigen (Verschiebefeld: Schwächungszauber).",
	["Show yourself"] = "Euch selbst anzeigen",
	["Show, fade or hide the bar while the aura is missing, the spell is ready or every charge is back."] = "Die Leiste anzeigen, verblassen lassen oder ausblenden, solange die Aura fehlt, der Zauber bereit ist oder jede Aufladung zurück ist.",
	["Showing test frames. Click the button again to hide them, or use /eui move to place them."] = "Testrahmen werden angezeigt. Klickt erneut auf die Schaltfläche, um sie auszublenden, oder nutzt /eui move, um sie zu platzieren.",
	["Shown"] = "Angezeigt",
	["Shown in front of the value when the label is set to \"My own text\"."] = "Wird vor dem Wert angezeigt, wenn die Beschriftung auf „Mein eigener Text“ steht.",
	["Shown name"] = "Angezeigter Name",
	["Shown now: %d. Secret values skipped this session: %d."] = "Jetzt angezeigt: %d. In dieser Sitzung übersprungene geheime Werte: %d.",
	["Shows 1/3 on the edit box while a message needs more than one part, and the letters used close to the 255 limit."] = "Zeigt 1/3 am Eingabefeld, solange eine Nachricht mehr als einen Teil braucht, und die verwendeten Zeichen nahe der Grenze von 255.",
	["Shows AFK in place of the health text."] = "Zeigt AFK anstelle des Gesundheitstexts.",
	["Shows Dodge, Parry, Miss and similar words on the plate."] = "Zeigt Ausweichen, Parieren, Verfehlt und ähnliche Wörter auf der Plakette.",
	["Shows EldoUI's map of this dungeon with its packs and your route again."] = "Zeigt wieder EldoUIs Karte dieses Dungeons mit seinen Gegnergruppen und Eurer Route.",
	["Shows a pulse now (the entry chosen below, or the first on the list)."] = "Zeigt jetzt einen Puls (den unten gewählten Eintrag oder den ersten der Liste).",
	["Shows a sample line in every scroll area and on your target's nameplate. Out of combat only."] = "Zeigt eine Beispielzeile in jedem Scrollbereich und auf der Namensplakette Eures Ziels. Nur außerhalb des Kampfes.",
	["Shows a small handle on every icon in move mode to drag it or open its settings."] = "Zeigt im Verschiebemodus einen kleinen Griff auf jedem Symbol, um es zu ziehen oder seine Einstellungen zu öffnen.",
	["Shows an arrow when all of the last 3 days are above or below the usual price by more than the chosen percentage."] = "Zeigt einen Pfeil, wenn alle der letzten 3 Tage um mehr als den gewählten Prozentsatz über oder unter dem üblichen Preis liegen.",
	["Shows at once at full size and fades, no pop."] = "Erscheint sofort in voller Größe und verblasst, ohne Aufploppen.",
	["Shows each Legacy node's icon in front of its name on the Build page."] = "Zeigt auf der Seite Build das Symbol jedes Vermächtnis-Knotens vor seinem Namen.",
	["Shows every section you hid on this character. Right-click a section's title in the bag or bank window to hide it; click a hidden title to show it again."] = "Zeigt jeden Abschnitt, den Ihr auf diesem Charakter ausgeblendet habt. Rechtsklickt im Taschen- oder Bankfenster auf den Titel eines Abschnitts, um ihn auszublenden; klickt auf einen ausgeblendeten Titel, um ihn wieder anzuzeigen.",
	["Shows faded icons in move mode where hidden icons would sit."] = "Zeigt im Verschiebemodus verblasste Symbole dort, wo ausgeblendete Symbole säßen.",
	["Shows heals the enemy receives."] = "Zeigt Heilungen, die der Gegner erhält.",
	["Shows how many looks of each set you have on the Loot Guide's Sets page, and marks the items in Loot Guide lists."] = "Zeigt auf der Seite Sets des Loot Guide, wie viele Aussehen jedes Sets Ihr habt, und markiert die Gegenstände in Listen des Loot Guide.",
	["Shows how much rested XP your offline characters have built up since logout, from the game's published rate. Estimates are marked with ~."] = "Zeigt, wie viel Erholungsbonus Eure Offline-Charaktere seit dem Ausloggen angesammelt haben, nach der vom Spiel veröffentlichten Rate. Schätzungen sind mit ~ markiert.",
	["Shows how much saved data each character uses (/eui alts size)."] = "Zeigt, wie viele gespeicherte Daten jeder Charakter belegt (/eui alts size).",
	["Shows item levels on equipped gear and in equipment flyouts."] = "Zeigt Gegenstandsstufen auf angelegter Ausrüstung und in Ausrüstungs-Ausklappmenüs.",
	["Shows links as [example.com]."] = "Zeigt Links als [example.com].",
	["Shows loot, money and currency lines even while EldoUI's loot toasts show them too."] = "Zeigt Beute-, Geld- und Währungszeilen, auch wenn EldoUIs Beutehinweise sie ebenfalls zeigen.",
	["Shows one bar of each kind for half a minute, so you can set up the look. Drag the bars in move mode."] = "Zeigt eine halbe Minute lang eine Leiste jeder Art, damit Ihr die Optik einstellen könnt. Zieht die Leisten im Verschiebemodus.",
	["Shows one decimal when less than a second is left."] = "Zeigt eine Nachkommastelle, wenn weniger als eine Sekunde übrig ist.",
	["Shows only the nodes your draft adds, removes or changes."] = "Zeigt nur die Knoten, die Euer Entwurf hinzufügt, entfernt oder ändert.",
	["Shows only the recipes whose name contains this text."] = "Zeigt nur die Rezepte, deren Name diesen Text enthält.",
	["Shows sample frames so you can size and place them while solo. Click again to hide them."] = "Zeigt Beispielrahmen, damit Ihr sie ohne Gruppe in Größe und Position anpassen könnt. Klickt erneut, um sie auszublenden.",
	["Shows the Eldostar guide window."] = "Zeigt das Guide-Fenster von Eldostar.",
	["Shows the Errors tab, or the log as text without the chat panel."] = "Zeigt den Reiter Fehler oder das Protokoll als Text ohne das Chat-Panel.",
	["Shows the account bank pages in the bank window when the game lets you view them."] = "Zeigt die Seiten der Accountbank im Bankfenster, wenn das Spiel sie Euch ansehen lässt.",
	["Shows the average item level the game reports for your gear."] = "Zeigt die durchschnittliche Gegenstandsstufe, die das Spiel für Eure Ausrüstung meldet.",
	["Shows the broom that runs the game's own bag and bank sort. Right-click it at the bank to sort the account bank."] = "Zeigt den Besen, der die eigene Taschen- und Banksortierung des Spiels startet. Rechtsklickt an der Bank darauf, um die Accountbank zu sortieren.",
	["Shows the challenges of one category."] = "Zeigt die Herausforderungen einer Kategorie.",
	["Shows the chat command that switches when spells cast, selected for copying. Paste it in chat and press Enter."] = "Zeigt den Chatbefehl, der umstellt, wann Zauber gewirkt werden, zum Kopieren markiert. Fügt ihn in den Chat ein und drückt die Eingabetaste.",
	["Shows the chat command that turns soft interact on for mouse, keyboard and gamepad, selected for copying. Paste it in chat and press Enter."] = "Zeigt den Chatbefehl, der die Soft-Interaktion für Maus, Tastatur und Gamepad einschaltet, zum Kopieren markiert. Fügt ihn in den Chat ein und drückt die Eingabetaste.",
	["Shows the game's minimap large here, with your arrow and your group as the game draws them. The mouse wheel zooms. Out of combat."] = "Zeigt die Minikarte des Spiels hier groß, mit Eurem Pfeil und Eurer Gruppe, wie das Spiel sie zeichnet. Das Mausrad zoomt. Außerhalb des Kampfes.",
	["Shows the game's own map until you close the map. The Dungeon map button on it brings this view back."] = "Zeigt die eigene Karte des Spiels, bis Ihr die Karte schließt. Die Schaltfläche Dungeonkarte darauf holt diese Ansicht zurück.",
	["Shows the group only while you are in this stance or form. Any: in every one."] = "Zeigt die Gruppe nur, solange Ihr in dieser Haltung oder Gestalt seid. Beliebig: in jeder.",
	["Shows the guide window again after you closed it. /eui eldostar show does the same."] = "Zeigt das Guide-Fenster wieder, nachdem Ihr es geschlossen habt. /eui eldostar show bewirkt dasselbe.",
	["Shows the keyring's slots in the bag window, in their own section."] = "Zeigt die Plätze des Schlüsselbunds im Taschenfenster, in einem eigenen Abschnitt.",
	["Shows the level-up trigger with sample values."] = "Zeigt den Auslöser für Stufenaufstiege mit Beispielwerten.",
	["Shows the middle price of up to 14 daily lows when at least 3 days have prices. Hold Shift for the last 7 days, oldest first. A dash means no saved price."] = "Zeigt den mittleren Preis von bis zu 14 Tagestiefstpreisen, sobald mindestens 3 Tage Preise haben. Haltet Umschalt für die letzten 7 Tage, die ältesten zuerst. Ein Strich bedeutet: kein gespeicherter Preis.",
	["Shows the month after."] = "Zeigt den nächsten Monat.",
	["Shows the month before."] = "Zeigt den vorherigen Monat.",
	["Shows the next page of characters."] = "Zeigt die nächste Seite mit Charakteren.",
	["Shows the planner window (also /eui legacy)."] = "Zeigt das Planer-Fenster (auch /eui legacy).",
	["Shows the previous page of characters."] = "Zeigt die vorherige Seite mit Charakteren.",
	["Shows the screen now (/eui afk test). Click to close."] = "Zeigt den Bildschirm jetzt (/eui afk test). Klickt zum Schließen.",
	["Shows the seconds on each icon from this many seconds."] = "Zeigt die Sekunden auf jedem Symbol ab so vielen Sekunden.",
	["Shows the set you captured for this class and spec, ready to paste into Blizzard's Import box."] = "Zeigt das Set, das Ihr für diese Klasse und Spezialisierung erfasst habt, bereit zum Einfügen in Blizzards Importfeld.",
	["Shows the spell or item icon next to the line when the game names it."] = "Zeigt das Zauber- oder Gegenstandssymbol neben der Zeile, wenn das Spiel ihn nennt.",
	["Shows the spell's tooltip and the timer type on mouse over. Off keeps the bar click-through."] = "Zeigt bei Mauskontakt den Tooltip des Zaubers und die Timerart. Aus lässt die Leiste durchklickbar.",
	["Shows the step and its next goal on two lines."] = "Zeigt den Schritt und sein nächstes Ziel auf zwei Zeilen.",
	["Shows the time left on oils, stones and poisons below your weapons while the character window is open."] = "Zeigt die Restdauer von Ölen, Steinen und Giften unter Euren Waffen, solange das Charakterfenster offen ist.",
	["Shows the whole step: its tip, every goal and the buttons."] = "Zeigt den ganzen Schritt: seinen Tipp, jedes Ziel und die Schaltflächen.",
	["Shows this character's bags in the Bags module's own window."] = "Zeigt die Taschen dieses Charakters im eigenen Fenster des Moduls Taschen.",
	["Shows this entry's pulse now, with its sound and speech."] = "Zeigt den Puls dieses Eintrags jetzt, mit seinem Klang und seiner Sprachausgabe.",
	["Shows this floor of the dungeon."] = "Zeigt diese Ebene des Dungeons.",
	["Shows this scroll area. Its events show nowhere while it is off."] = "Zeigt diesen Scrollbereich. Solange er aus ist, erscheinen seine Ereignisse nirgends.",
	["Shows whether aura alarms are running and how many spell IDs they watch."] = "Zeigt, ob Aurenalarme laufen und wie viele Zauber-IDs sie überwachen.",
	["Shows while the game marks you Away (/afk, or after a few idle minutes). You stay Away until you move or type, as always."] = "Erscheint, solange das Spiel Euch als abwesend markiert (/afk oder nach einigen Minuten Untätigkeit). Ihr bleibt wie immer abwesend, bis Ihr Euch bewegt oder schreibt.",
	["Shows worn gear as a percentage or a red tint."] = "Zeigt abgenutzte Ausrüstung als Prozentwert oder rote Tönung.",
	["Shows your killing blows, honorable kills and deaths in a battleground."] = "Zeigt Eure Todesstöße, ehrenhaften Siege und Tode auf einem Schlachtfeld.",
	["Shows your spell's or item's icon in the middle of the screen when the game says it is ready again, with an optional sound and spoken line."] = "Zeigt das Symbol Eures Zaubers oder Gegenstands in der Bildschirmmitte, wenn das Spiel meldet, dass er wieder bereit ist, mit optionalem Klang und gesprochener Zeile.",
	["Side by side"] = "Nebeneinander",
	["Side by side or stacked, for the shared strip."] = "Nebeneinander oder gestapelt, für die gemeinsame Leiste.",
	["Side panels"] = "Seitenpanels",
	["Silences every trigger's sound (texts and flashes still show). Also /eui fx mute."] = "Schaltet die Klänge aller Auslöser stumm (Texte und Aufblitzen erscheinen weiterhin). Auch /eui fx mute.",
	["Silent visual"] = "Lautlos, nur optisch",
	["Single mob"] = "Einzelner Gegner",
	["Sit by the fire"] = "Setzt Euch ans Feuer",
	["Sixes"] = "Sechser",
	["Size and layout"] = "Größe und Anordnung",
	["Size and look"] = "Größe und Optik",
	["Size of Blizzard's loot window while EldoUI moves it."] = "Größe von Blizzards Beutefenster, solange EldoUI es verschiebt.",
	["Size of Blizzard's roll frames on EldoUI's roll spot."] = "Größe von Blizzards Wurffenstern auf dem Wurfplatz von EldoUI.",
	["Size of Blizzard's start countdown on its EldoUI mover, in percent."] = "Größe von Blizzards Start-Countdown auf seinem EldoUI-Verschiebefeld, in Prozent.",
	["Size of EldoUI's leave-vehicle button."] = "Größe von EldoUIs Schaltfläche zum Verlassen des Fahrzeugs.",
	["Size of critical hits and other sticky lines."] = "Größe kritischer Treffer und anderer haftender Zeilen.",
	["Size of critical hits, in percent of normal."] = "Größe kritischer Treffer, in Prozent der normalen Größe.",
	["Size of each buff icon."] = "Größe jedes Stärkungszaubersymbols.",
	["Size of each counter's icon."] = "Größe des Symbols jedes Zählers.",
	["Size of each debuff icon."] = "Größe jedes Schwächungszaubersymbols.",
	["Size of each set button."] = "Größe jeder Set-Schaltfläche.",
	["Size of each slot in pixels."] = "Größe jedes Platzes in Pixeln.",
	["Size of names and values (Blizzard's text scale still applies on top)."] = "Größe von Namen und Werten (Blizzards Textskalierung gilt zusätzlich).",
	["Size of names and values."] = "Größe von Namen und Werten.",
	["Size of normal lines in this area. General uses the general size."] = "Größe normaler Zeilen in diesem Bereich. Allgemein verwendet die allgemeine Größe.",
	["Size of normal lines."] = "Größe normaler Zeilen.",
	["Size of plate numbers."] = "Größe der Plakettenzahlen.",
	["Size of sticky lines in this area. General uses the general size."] = "Größe haftender Zeilen in diesem Bereich. Allgemein verwendet die allgemeine Größe.",
	["Size of the BoE and BoU text."] = "Größe des BoE- und BoU-Texts.",
	["Size of the Cast, Lure and Swap buttons."] = "Größe der Schaltflächen Auswerfen, Köder und Wechseln.",
	["Size of the NPC's text and the choices. The name is a little larger."] = "Größe des NSC-Texts und der Auswahlmöglichkeiten. Der Name ist etwas größer.",
	["Size of the alert in percent (replaces Blizzard's Edit Mode size while Move is on)."] = "Größe der Warnung in Prozent (ersetzt die Größe aus Blizzards Bearbeitungsmodus, solange Verschieben an ist).",
	["Size of the bag, bank and guild bank windows, from 50 to 150 percent."] = "Größe der Taschen-, Bank- und Gildenbankfenster, von 50 bis 150 Prozent.",
	["Size of the big icon. 64 is the space the layouts keep for it."] = "Größe des großen Symbols. 64 ist der Platz, den die Layouts dafür freihalten.",
	["Size of the bubble text."] = "Größe des Sprechblasentexts.",
	["Size of the camp panel."] = "Größe des Lager-Panels.",
	["Size of the chat text (skin switch)."] = "Größe des Chattexts (Skin-Schalter).",
	["Size of the controller action bar while it uses the EldoUI mover (Move switch of Gamepad HUD)."] = "Größe der Controller-Aktionsleiste, solange sie das EldoUI-Verschiebefeld nutzt (Schalter Verschieben von Gamepad-HUD).",
	["Size of the count text."] = "Größe des Anzahltexts.",
	["Size of the emoji in chat lines, in pixels. Auto follows the chat font size."] = "Größe der Emojis in Chatzeilen, in Pixeln. Automatisch folgt der Schriftgröße des Chats.",
	["Size of the enchant icons."] = "Größe der Verzauberungssymbole.",
	["Size of the feedback text."] = "Größe des Rückmeldungstexts.",
	["Size of the goals; the step's title is one size larger."] = "Größe der Ziele; der Titel des Schritts ist eine Stufe größer.",
	["Size of the icon that pops next to the text."] = "Größe des Symbols, das neben dem Text aufspringt.",
	["Size of the icons on the bar. At most the thickness minus 4."] = "Größe der Symbole auf der Leiste. Höchstens die Dicke minus 4.",
	["Size of the info text; the name is a little bigger."] = "Größe des Infotexts; der Name ist etwas größer.",
	["Size of the item icons in the Quick Sell tab."] = "Größe der Gegenstandssymbole im Reiter Schnellverkauf.",
	["Size of the item level number."] = "Größe der Zahl für die Gegenstandsstufe.",
	["Size of the item names in EldoUI's window."] = "Größe der Gegenstandsnamen im Fenster von EldoUI.",
	["Size of the large average item level number."] = "Größe der großen Zahl für die durchschnittliche Gegenstandsstufe.",
	["Size of the mark."] = "Größe der Markierung.",
	["Size of the name icons compared with the chat text."] = "Größe der Namenssymbole im Vergleich zum Chattext.",
	["Size of the name, time and count on every bar."] = "Größe von Name, Zeit und Anzahl auf jeder Leiste.",
	["Size of the number of items in a stack."] = "Größe der Anzahl der Gegenstände in einem Stapel.",
	["Size of the numbers and names."] = "Größe der Zahlen und Namen.",
	["Size of the pack and boss markers."] = "Größe der Markierungen für Gegnergruppen und Bosse.",
	["Size of the part counter and the typing line."] = "Größe des Teilezählers und der Schreibzeile.",
	["Size of the pins."] = "Größe der Pins.",
	["Size of the possess buttons."] = "Größe der Tasten der Besessenheitsleiste.",
	["Size of the possess frame in percent."] = "Größe der Besessenheitsleiste in Prozent.",
