	["Small row without background or session gain."] = "Kleine Zeile ohne Hintergrund und ohne Zuwachs der Sitzung.",
	["Small rows and slim roll bars, fewer toasts."] = "Kleine Zeilen und schmale Wurfleisten, weniger Hinweise.",
	["Small rows, more nodes on screen."] = "Kleine Zeilen, mehr Knoten auf dem Bildschirm.",
	["Small rows, no icons, see-through."] = "Kleine Zeilen, keine Symbole, durchscheinend.",
	["Small sections (categories or bags) share a row instead of starting a new one."] = "Kleine Abschnitte (Kategorien oder Taschen) teilen sich eine Reihe, statt eine neue zu beginnen.",
	["Small slots in wide rows, for big bags."] = "Kleine Plätze in breiten Reihen, für große Taschen.",
	["Small sprites flying off the fill edge and drifting inside the bar. Off keeps colors, spark and flashes."] = "Kleine Partikel, die von der Füllkante wegfliegen und in der Leiste treiben. Aus behält Farben, Funken und Aufblitzen.",
	["Small straight"] = "Kleine Straße",
	["Small text and tight boxes for busy cities."] = "Kleiner Text und enge Sprechblasen für volle Städte.",
	["Small text, no tips and no goals along the way, in a see-through panel."] = "Kleiner Text, keine Tipps und keine Zwischenziele, in einem durchscheinenden Panel.",
	["Small, out-of-the-way frames: thin class-colored bars with names and role icons, no buff icons, and a slim mana bar on healers in the party. Good for damage dealers."] = "Kleine, unauffällige Rahmen: dünne Leisten in Klassenfarbe mit Namen und Rollensymbolen, keine Stärkungszaubersymbole und eine schmale Manaleiste bei Heilern in der Gruppe. Gut für Schadensverursacher.",
	["Smaller gray line under the text. Same tokens."] = "Kleinere graue Zeile unter dem Text. Dieselben Tokens.",
