	["Spells and items"] = "Zauber und Gegenstände",
	["Spells cast when the key comes back up. This is a protected game setting: no addon can change it, but your own chat command can."] = "Zauber werden gewirkt, wenn die Taste losgelassen wird. Dies ist eine geschützte Spieleinstellung: Kein Addon kann sie ändern, Euer eigener Chatbefehl aber schon.",
	["Spells cast when the key goes down. This is a protected game setting: no addon can change it, but your own chat command can."] = "Zauber werden gewirkt, wenn die Taste gedrückt wird. Dies ist eine geschützte Spieleinstellung: Kein Addon kann sie ändern, Euer eigener Chatbefehl aber schon.",
	["Spells with charges: gray while a charge comes back."] = "Zauber mit Aufladungen: grau, während eine Aufladung zurückkehrt.",
	["Spells with charges: how visible the icon is while a charge comes back and at least one is left."] = "Zauber mit Aufladungen: wie sichtbar das Symbol ist, während eine Aufladung zurückkehrt und mindestens eine übrig ist.",
