	["Turn on \"Let EldoUI change this\" for the damage meter first (Combat HUD > Damage meter)."] = "Schaltet zuerst „EldoUI dies ändern lassen“ für den Schadensmesser ein (Kampf-HUD > Schadensmesser).",
	["Turn on \"Let EldoUI change this\" on the Blizzard combat text tab first."] = "Schaltet zuerst auf dem Reiter Blizzard-Kampftext „EldoUI dies ändern lassen“ ein.",
	["Turn on \"Part counter\" or \"Show who is typing\" first."] = "Schaltet zuerst „Teilezähler“ oder „Anzeigen, wer schreibt“ ein.",
	["Turn on \"Share alt info with your guild\" in /eui > Alts first."] = "Schaltet zuerst „Twink-Infos mit Eurer Gilde teilen“ unter /eui > Twinks ein.",
	["Turn on \"Share alt info with your guild\" in /eui > Alts, then click Ask the guild. Lists you import show here too."] = "Schaltet „Twink-Infos mit Eurer Gilde teilen“ unter /eui > Twinks ein und klickt dann auf „Gilde fragen“. Listen, die Ihr importiert, erscheinen ebenfalls hier.",
	["Turn on \"Share your recipes with the guild\" in /eui > Alts first."] = "Schaltet zuerst „Eure Rezepte mit der Gilde teilen“ unter /eui > Twinks ein.",
	["Turn on \"Share your recipes with the guild\" in /eui > Alts, then click Ask the guild. Lists guild members send show here."] = "Schaltet „Eure Rezepte mit der Gilde teilen“ unter /eui > Twinks ein und klickt dann auf „Die Gilde fragen“. Listen, die Gildenmitglieder senden, erscheinen hier.",
	["Turn on \"Show what you loot\" to see the samples."] = "Schaltet „Eure Beute anzeigen“ ein, um die Beispiele zu sehen.",
	["Turn on Blizzard UI > Trade window > Improve first"] = "Schaltet zuerst Blizzard-UI > Handelsfenster > Verbessern ein",
	["Turn on Camera Situations first."] = "Schaltet zuerst Kamerasituationen ein.",
	["Turn on Cooldown Pulse first."] = "Schaltet zuerst Abklingzeitpuls ein.",
	["Turn on EldoUI Loot Data in the addon list, then reload."] = "Schaltet EldoUI Loot Data in der Addonliste ein und ladet dann neu.",
	["Turn on Improve for the Legacy window here to dock the planner beside Blizzard's window."] = "Schaltet hier „Verbessern“ für das Vermächtnisfenster ein, um den Planer neben Blizzards Fenster anzudocken.",
	["Turn on Own groups on the Groups tab to give single icons their own look."] = "Schaltet auf dem Reiter Gruppen „Eigene Gruppen“ ein, um einzelnen Symbolen eine eigene Optik zu geben.",
	["Turn on the Alts module (Items and Economy) to list your characters here."] = "Schaltet das Modul Twinks (Gegenstände und Wirtschaft) ein, um hier Eure Charaktere aufzulisten.",
	["Turn on the Alts module first"] = "Schaltet zuerst das Modul Twinks ein",
	["Turn on the Instances module first (Group > Instances)."] = "Schaltet zuerst das Modul Instanzen ein (Gruppe > Instanzen).",
	["Turn on the Trade board in Chat settings."] = "Schaltet die Handelsbörse in den Chateinstellungen ein.",
	["Turn over"] = "Aufdecken",
	["Turn saved chat history off?\n\nThe %d saved chat lines of this character are deleted."] = "Gespeicherten Chatverlauf ausschalten?\n\nDie %d gespeicherten Chatzeilen dieses Charakters werden gelöscht.",
	["Turn speed"] = "Drehgeschwindigkeit",
	["Turn text smileys into emoji"] = "Text-Smileys in Emoji umwandeln",
	["Turn the Cooldown Manager on"] = "Abklingzeitenmanager einschalten",
	["Turn the falling shapes and fill whole rows."] = "Dreht die fallenden Formen und füllt ganze Reihen.",
	["Turn the name icons off in single chat tabs."] = "Schaltet die Namenssymbole in einzelnen Chatreitern aus.",
	["Turn the name icons off in single numbered channels, for example a busy trade channel."] = "Schaltet die Namenssymbole in einzelnen nummerierten Kanälen aus, zum Beispiel in einem vollen Handelskanal.",
	["Turn the spell cues on. Off by default."] = "Schaltet die Zauberhinweise ein. Standardmäßig aus.",
	["Turn this extra resource bar on."] = "Schaltet diese zusätzliche Ressourcenleiste ein.",
	["Turn two cards at a time and find every pair."] = "Deckt jeweils zwei Karten auf und findet jedes Paar.",
	["Turn-in reminder"] = "Abgabe-Erinnerung",
	["Turns music and ambience down while fishing, so the splash stands out."] = "Dreht beim Angeln Musik und Umgebungsgeräusche leiser, damit das Platschen heraussticht.",
	["Turns on the game's own Cooldown Manager option while the master switch is on. Blizzard default puts back what it was before."] = "Schaltet die eigene Option Abklingzeitenmanager des Spiels ein, solange der Hauptschalter an ist. Blizzard-Standard stellt wieder her, was vorher eingestellt war.",
	["Turns the box off for every flight. The Flight Games options turn it back on."] = "Schaltet das Feld für jeden Flug aus. In den Optionen der Flugspiele schaltet Ihr es wieder ein.",
	["Turns the group on. Its mover appears in move mode while it is on."] = "Schaltet die Gruppe ein. Ihr Verschiebefeld erscheint im Verschiebemodus, solange sie an ist.",
	["Turns the right chat panel on. Move it with /eui move (EldoUI_ChatRight)."] = "Schaltet das rechte Chatpanel ein. Verschiebt es mit /eui move (EldoUI_ChatRight).",
	["Turns this bar on or off without deleting it."] = "Schaltet diese Leiste ein oder aus, ohne sie zu löschen.",
	["Turns your own groups off: EldoUI's own icons go back to the fixed rows (Main, Utility, Trinkets, Mobility, Items). Your groups are kept for later."] = "Schaltet Eure eigenen Gruppen aus: Die Symbole von EldoUI kehren in die festen Reihen zurück (Haupt, Nützlich, Schmuckstücke, Mobilität, Gegenstände). Eure Gruppen bleiben für später erhalten.",
	["Two Details windows stacked in the meter corner, each 440 x 200, with the EldoUI frame."] = "Zwei übereinander gestapelte Details-Fenster in der Ecke des Schadensmessers, je 440 x 200, mit dem EldoUI-Rahmen.",
	["Two bars"] = "Zwei Leisten",
	["Two lanes"] = "Zwei Spuren",
	["Two names and a count"] = "Zwei Namen und Anzahl",
	["Two pairs"] = "Zwei Paare",
	["Twos"] = "Zweier",
	["Type /eui in chat for the settings."] = "Gebt /eui im Chat ein, um die Einstellungen zu öffnen.",
	["Type a colon and two letters (such as :sm) to list matching emoji; Tab or a click puts one in. Without a colon, Tab works as before."] = "Gebt einen Doppelpunkt und zwei Buchstaben ein (etwa :sm), um passende Emoji aufzulisten; Tab oder ein Klick fügt eines ein. Ohne Doppelpunkt funktioniert Tab wie bisher.",
	["Type a guild name first."] = "Gebt zuerst einen Gildennamen ein.",
	["Type a macro name or /macro text."] = "Gebt einen Makronamen oder /macro-Text ein.",
	["Type a name, an item ID or bag search words."] = "Gebt einen Namen, eine Gegenstands-ID oder Suchwörter der Taschen ein.",
	["Type a name, or a filter: q:rare for rare items, ilvl>50 for item level above 50, t:cloth for a type, or junk, quest and new. Put - before a word to leave it out."] = "Gebt einen Namen oder einen Filter ein: q:rare für rare Gegenstände, ilvl>50 für Gegenstandsstufe über 50, t:cloth für einen Typ, oder junk, quest und new. Setzt - vor ein Wort, um es auszuschließen.",
	["Type a search first."] = "Gebt zuerst eine Suche ein.",
	["Type a search term, or pick a shopping list."] = "Gebt einen Suchbegriff ein oder wählt eine Einkaufsliste.",
	["Type a spell ID and press Enter to put that spell in the Spell row."] = "Gebt eine Zauber-ID ein und drückt die Eingabetaste, um diesen Zauber in das Feld Zauber zu setzen.",
	["Type a spell name or drag a spell here."] = "Gebt einen Zaubernamen ein oder zieht einen Zauber hierher.",
	["Type a word and press Enter."] = "Gebt ein Wort ein und drückt die Eingabetaste.",
	["Type a word or phrase first."] = "Gebt zuerst ein Wort oder eine Wortgruppe ein.",
	["Type an item ID or name, or paste an item link, and press Enter."] = "Gebt eine Gegenstands-ID oder einen Namen ein oder fügt einen Gegenstandslink ein und drückt die Eingabetaste.",
	["Type letters, Enter guesses, Backspace erases; the keys below work with a click."] = "Tippt Buchstaben, die Eingabetaste rät, die Rücktaste löscht; die Tasten unten funktionieren per Klick.",
	["Type to search"] = "Tippen zum Suchen",
	["Type to search. Pinned and recent results show here."] = "Tippt, um zu suchen. Angeheftete und letzte Ergebnisse erscheinen hier.",
	["Type: %s"] = "Typ: %s",
	["Typed lines"] = "Eingegebene Zeilen",
	["Typed lines kept"] = "Gemerkte Zeilen",
	["Typing a sum (\"= 12*35+4\" or \"12*35+4\") shows the answer; a click opens it ready to copy."] = "Eine eingetippte Rechnung („= 12*35+4“ oder „12*35+4“) zeigt das Ergebnis; ein Klick öffnet es zum Kopieren.",
	["U takes back your last move."] = "U nimmt Euren letzten Zug zurück.",
	["U: back. R: again."] = "U: zurück. R: neu.",
	["Uncheck the last pull: it is next again."] = "Entfernt den Haken beim letzten Pull: Er ist wieder als Nächstes dran.",
	["Uncommon"] = "Selten",
