	["Unknown option. Try /eui help legacy."] = "Unbekannte Option. Versucht /eui help legacy.",
	["Unlock EldoUI frames to drag the class bar (mover \"Class Bar\")."] = "Entsperrt die EldoUI-Rahmen, um die Klassenleiste zu ziehen (Verschiebefeld „Klassenleiste“).",
	["Unlock EldoUI frames to drag the counters."] = "Entsperrt die EldoUI-Rahmen, um die Zähler zu ziehen.",
	["Unlock EldoUI frames to drag the list."] = "Entsperrt die EldoUI-Rahmen, um die Liste zu ziehen.",
	["Unlock EldoUI frames to drag the panels (not attached ones)."] = "Entsperrt die EldoUI-Rahmen, um die Panels zu ziehen (nicht die angedockten).",
	["Unlocked"] = "Entsperrt",
	["Unlocks only the scroll areas, each with sample lines in its own look and a bar where new lines start. Drag a box to move it, its corner to resize it; right-click turns it on or off."] = "Entsperrt nur die Scrollbereiche, jeden mit Beispielzeilen in seiner eigenen Optik und einer Leiste, an der neue Zeilen beginnen. Zieht ein Feld, um es zu verschieben, oder seine Ecke, um die Größe zu ändern; ein Rechtsklick schaltet es ein oder aus.",
	["Unlocks only this area, with sample lines and its start edge marked, so you can drag or resize it."] = "Entsperrt nur diesen Bereich, mit Beispielzeilen und markiertem Startrand, damit Ihr ihn ziehen oder seine Größe ändern könnt.",
	["Unlocks the combat frames so you can drag the timeline. The big icon and the bar move together."] = "Entsperrt die Kampfrahmen, damit Ihr die Zeitleiste ziehen könnt. Das große Symbol und die Leiste bewegen sich gemeinsam.",
	["Unmute in %s"] = "Stummschaltung endet in %s",
