	["Unspent points"] = "Nicht verteilte Punkte",
	["Until setup is done, it waits under the player frame."] = "Bis die Einrichtung abgeschlossen ist, wartet es unter dem Spielerrahmen.",
	["Until then, the Cast button on the fishing bar casts."] = "Bis dahin wirft die Schaltfläche Auswerfen auf der Angelleiste aus.",
	["Up (columns)"] = "Nach oben (Spalten)",
	["Up (newest at the bottom)"] = "Nach oben (neueste unten)",
	["Up next"] = "Als Nächstes",
	["Up to 16 characters in front of whispers you receive. Empty uses >."] = "Bis zu 16 Zeichen vor Flüsternachrichten, die Ihr empfangt. Leer verwendet >.",
	["Up to 16 characters in front of whispers you send. Empty uses <."] = "Bis zu 16 Zeichen vor Flüsternachrichten, die Ihr sendet. Leer verwendet <.",
	["Up to 90 days shows one bar per day; the year shows one bar per week."] = "Bis zu 90 Tage zeigen einen Balken pro Tag; das Jahr zeigt einen Balken pro Woche.",
	["Up to eight datatext panels of your own, anywhere on screen with a mover, or docked in the chat window or on the minimap."] = "Bis zu acht eigene Datentextleisten, überall auf dem Bildschirm mit einem Verschiebefeld oder angedockt im Chatfenster oder an der Minikarte.",
	["Up to level"] = "Bis Stufe",
