	["Upward drift in pixels per second; negative values make particles fall."] = "Aufwärtsdrift in Pixeln pro Sekunde; negative Werte lassen Partikel fallen.",
	["Upward drift in pixels per second; negative values sink."] = "Aufwärtsdrift in Pixeln pro Sekunde; negative Werte sinken.",
	["Urgent timer"] = "Dringlichkeitstimer",
	["Usage: /eui alts [on | off | search <text> | agenda | log | size]"] = "Verwendung: /eui alts [on | off | search <text> | agenda | log | size]",
	["Usage: /eui chat %s <channel>; <name>, for example /eui chat mute Trade; Name-Realm"] = "Verwendung: /eui chat %s <channel>; <name>, zum Beispiel /eui chat mute Handel; Name-Realm",
	["Usage: /eui chat alert <word or phrase> (adds it, or removes it when it is on the list)"] = "Verwendung: /eui chat alert <word or phrase> (fügt es hinzu oder entfernt es, wenn es schon auf der Liste steht)",
