	["Warn on a flagged target"] = "Bei Ziel mit aktiviertem PvP warnen",
	["Warn this many minutes before"] = "So viele Minuten vorher warnen",
	["Warn when ammo runs low"] = "Warnen, wenn die Munition knapp wird",
	["Warn when both place a frame"] = "Warnen, wenn beide einen Rahmen platzieren",
	["Warn when you get flagged"] = "Warnen, wenn bei Euch PvP aktiviert wird",
	["Warning at"] = "Warnung bei",
	["Warning sound"] = "Warnsound",
	["Warning zones"] = "Warnzonen",
	["Warns in Quick Sell and the game's Sell tab when your unit price is this far below the usual price."] = "Warnt im Schnellverkauf und im Reiter Verkaufen des Spiels, wenn Euer Stückpreis so weit unter dem üblichen Preis liegt.",
	["Watch item"] = "Gegenstand beobachten",
	["Watch items, currencies and gold as small movable counters, with goals and the session gain."] = "Beobachtet Gegenstände, Währungen und Gold als kleine verschiebbare Zähler, mit Zielen und dem Zuwachs der Sitzung.",
	["Watch the float..."] = "Beobachtet den Schwimmer...",
	["Watch the runes..."] = "Beobachtet die Runen...",
	["Watched"] = "Beobachtet",
	["Watched offer"] = "Beobachtetes Angebot",
	["Watching %s (%d charges). Spend the charges; each one that comes back prints a line. /eui probe charges off stops."] = "Beobachte %s (%d Aufladungen). Verbraucht die Aufladungen; für jede, die zurückkommt, erscheint eine Zeile. /eui probe charges off beendet es.",
	["Water Elemental"] = "Wasserelementar",
	["Water drop"] = "Wassertropfen",
	["Wave %d"] = "Welle %d",
	["Wave %d of %d"] = "Welle %d von %d",
	["Wave %d reached"] = "Welle %d erreicht",
	["Wave %d, lives %d"] = "Welle %d, Leben %d",
	["Wave cleared!"] = "Welle geschafft!",
	["Waypoint to the goal"] = "Wegpunkt zum Ziel",
	["Weapon Enchants"] = "Waffenverzauberungen",
	["Weapon and profession skills going up."] = "Steigende Waffen- und Berufsfertigkeiten.",
	["Weapon buff time"] = "Dauer von Waffenverzauberungen",
	["Weapon enchants"] = "Waffenverzauberungen",
	["Weapons and armor"] = "Waffen und Rüstung",
	["Weapons and armor show their item level in the corner, in the quality color."] = "Waffen und Rüstung zeigen ihre Gegenstandsstufe in der Ecke, in der Qualitätsfarbe.",
	["Weapons and armor."] = "Waffen und Rüstung.",
	["Weapons back"] = "Waffen zurück",
	["Web addresses in chat become links. Click one, then press Ctrl+C to copy it. Shift+click puts it into an open chat edit box."] = "Webadressen im Chat werden zu Links. Klickt einen an und drückt dann Strg+C, um ihn zu kopieren. Umschalt+Klick fügt ihn in ein offenes Chat-Eingabefeld ein.",
	["Week starts on Monday"] = "Woche beginnt am Montag",
	["Week to %s"] = "Woche bis %s",
	["Weekly reset"] = "Wöchentlicher Reset",
	["Well below the usual price (%s)"] = "Weit unter dem üblichen Preis (%s)",
	["Well met!"] = "Seid gegrüßt!",
	["Well played!"] = "Gut gespielt!",
	["Whack-a-Gnoll"] = "Hau den Gnoll",
	["What EldoUI may change on Blizzard's own bars is set on the Blizzard UI page, bar by bar. A bar at Blizzard default stays exactly as it is."] = "Was EldoUI an Blizzards eigenen Leisten ändern darf, legt Ihr Leiste für Leiste auf der Seite Blizzard-UI fest. Eine Leiste auf Blizzard-Standard bleibt genau, wie sie ist.",
	["What EldoUI may do with Blizzard's chat is set on the Blizzard UI page. These settings shape what each switch does."] = "Was EldoUI mit Blizzards Chat tun darf, legt Ihr auf der Seite Blizzard-UI fest. Diese Einstellungen bestimmen, was jeder Schalter bewirkt.",
	["What EldoUI may do with bubbles is set on the Blizzard UI page. In instances the game locks them: only the font and which ones show apply."] = "Was EldoUI mit Sprechblasen tun darf, legt Ihr auf der Seite Blizzard-UI fest. In Instanzen sperrt das Spiel sie: Dann gelten nur die Schrift und die Auswahl, welche erscheinen.",
	["What EldoUI places"] = "Was EldoUI platziert",
	["What EldoUI sets in its DBM profile"] = "Was EldoUI in seinem DBM-Profil einstellt",
	["What Herbalism skill do you need to pick %s?"] = "Welche Kräuterkundefertigkeit braucht Ihr, um %s zu pflücken?",
	["What Mining skill is needed for %s?"] = "Welche Bergbaufertigkeit ist für %s nötig?",
	["What a spell's place shows while its aura is not on the unit. The place never moves."] = "Was der Platz eines Zaubers zeigt, solange seine Aura nicht auf der Einheit liegt. Der Platz bewegt sich nie.",
	["What a vendor pays for the looted stack, beside the name."] = "Was ein Händler für den geplünderten Stapel zahlt, neben dem Namen.",
	["What a vendor pays for the whole stack, at the right of the row."] = "Was ein Händler für den ganzen Stapel zahlt, rechts in der Zeile.",
	["What an item looks like when your bags hold none of it."] = "Wie ein Gegenstand aussieht, wenn Eure Taschen keinen davon enthalten.",
	["What color is the name of an item of %s quality?"] = "Welche Farbe hat der Name eines Gegenstands der Qualität %s?",
	["What do the playable undead call themselves?"] = "Wie nennen sich die spielbaren Untoten selbst?",
	["What does Bind on Pickup mean?"] = "Was bedeutet es, wenn ein Gegenstand beim Aufheben gebunden wird?",
	["What does a warlock gather with Drain Soul?"] = "Was sammelt ein Hexenmeister mit Seelendieb?",
	["What happens to Blizzard's own bar %d."] = "Was mit Blizzards eigener Leiste %d geschieht.",
	["What is read out. {name} becomes the spell's or item's name."] = "Was vorgelesen wird. {name} wird zum Namen des Zaubers oder Gegenstands.",
	["What is the highest level a character can reach?"] = "Welche Stufe kann ein Charakter höchstens erreichen?",
	["What it searches"] = "Was durchsucht wird",
	["What it shows"] = "Was angezeigt wird",
	["What kind of beast is Gahz'rilla?"] = "Was für ein Tier ist Gahz'rilla?",
	["What kind of creature is Hogger of Elwynn Forest?"] = "Was für eine Kreatur ist Hogger aus dem Wald von Elwynn?",
	["What party and raid members loot, with their name in class colors. A loot line the game hides adds nothing."] = "Was Gruppen- und Schlachtzugsmitglieder plündern, mit ihrem Namen in Klassenfarben. Eine Beutezeile, die das Spiel ausblendet, fügt nichts hinzu.",
	["What shows behind your character model."] = "Was hinter Eurem Charaktermodell erscheint.",
	["What sweeps over the filled part."] = "Was über den gefüllten Teil streicht.",
	["What the bar does when a cast completes: a short flash, and particles bursting from the edge."] = "Was die Leiste tut, wenn ein Zauber abgeschlossen ist: ein kurzes Aufblitzen und Partikel, die vom Rand aufstieben.",
	["What the bar does when a cast fails or is interrupted: a flash in the theme's fail color, and a short shake."] = "Was die Leiste tut, wenn ein Zauber fehlschlägt oder unterbrochen wird: ein Aufblitzen in der Fehlschlagfarbe des Themas und ein kurzes Wackeln.",
	["What the bar shows. Combo points show as one bar that fills per point."] = "Was die Leiste zeigt. Kombopunkte erscheinen als eine Leiste, die sich pro Punkt füllt.",
	["What the picker puts into your line. Shortcode (:smile:) reads fine for everyone and is a picture for EldoUI users. Unicode sends the character; others may see boxes."] = "Was die Auswahl in Eure Zeile einfügt. Kurzcode (:smile:) ist für alle lesbar und für EldoUI-Nutzer ein Bild. Unicode sendet das Zeichen; andere sehen eventuell Kästchen.",
	["What the stack shows for your class."] = "Was der Stapel für Eure Klasse zeigt.",
	["What they say and yell near you."] = "Was sie in Eurer Nähe sagen und schreien.",
	["What to warn about"] = "Wovor gewarnt wird",
	["What was hidden from muted guilds in the last 15 minutes. Also /eui chatguild hidden."] = "Was in den letzten 15 Minuten von stummgeschalteten Gilden ausgeblendet wurde. Auch /eui chatguild hidden.",
	["What was hidden in the last 15 minutes."] = "Was in den letzten 15 Minuten ausgeblendet wurde.",
	["What you gain"] = "Was Ihr erhaltet",
	["What you typed in the edit box comes back after a reload or the next login: Up and Down walk through it. Per character; secure commands are never saved. Off keeps them for this session only."] = "Was Ihr im Eingabefeld getippt habt, kommt nach einem Neuladen oder beim nächsten Einloggen zurück: Mit Pfeil hoch und runter blättert Ihr hindurch. Pro Charakter; sichere Befehle werden nie gespeichert. Aus behält sie nur für diese Sitzung.",
	["Wheel down"] = "Mausrad runter",
	["Wheel up"] = "Mausrad hoch",
	["When Blizzard's Cooldown Manager has no spells for your class, these rows stand in for its viewers. Always: they always show (hide Blizzard's viewers if both show)."] = "Wenn Blizzards Abklingzeitenmanager keine Zauber für Eure Klasse hat, ersetzen diese Reihen seine Anzeigen. Immer: Sie erscheinen immer (blendet Blizzards Anzeigen aus, wenn beide erscheinen).",
	["When Blizzard's is empty"] = "Wenn Blizzards Anzeige leer ist",
	["When Blizzard's is hidden"] = "Wenn Blizzards Schaltfläche ausgeblendet ist",
	["When EldoUI's cast bar for a checked unit is off, decorate Blizzard's own cast bar for that unit instead."] = "Ist die Zauberleiste von EldoUI für eine angehakte Einheit aus, wird stattdessen Blizzards eigene Zauberleiste dieser Einheit verziert.",
	["When a plan arrives from your group, one chat line names the blessings you keep up and on which classes. Paladins only."] = "Kommt ein Plan aus Eurer Gruppe, nennt eine Chatzeile die Segen, die Ihr aufrechterhaltet, und auf welchen Klassen. Nur Paladine.",
	["When an icon can't show (spell not known, item not in your bags), the others move up. Off keeps its spot empty."] = "Kann ein Symbol nicht erscheinen (Zauber nicht bekannt, Gegenstand nicht in Euren Taschen), rücken die anderen nach. Aus lässt seinen Platz leer.",
	["When another addon provides LibDataBroker, its feeds can be picked as \"LDB: name\" in any slot. Turning this off takes effect after a reload."] = "Stellt ein anderes Addon LibDataBroker bereit, lassen sich seine Feeds als „LDB: Name“ in jedem Platz wählen. Ausschalten wirkt erst nach einem Neuladen.",
	["When chat lines fade out. Scrolling or hovering shows them again."] = "Wann Chatzeilen ausgeblendet werden. Scrollen oder Zeigen mit der Maus bringt sie zurück.",
	["When durability turns red is set once for every module, on the General page (Clock and durability)."] = "Wann die Haltbarkeit rot wird, wird einmal für alle Module auf der Seite Allgemein festgelegt (Uhr und Haltbarkeit).",
	["When durability turns yellow and red is set once for every module, on the General page (Clock and durability)."] = "Wann die Haltbarkeit gelb und rot wird, wird einmal für alle Module auf der Seite Allgemein festgelegt (Uhr und Haltbarkeit).",
	["When fishing mode starts: whenever a fishing pole is in your main hand (the Fishing mode key binding pauses it), or only after you press that key binding (Key Bindings > AddOns)."] = "Wann der Angelmodus startet: immer, wenn eine Angelrute in Eurer Waffenhand ist (die Tastenbelegung Angelmodus pausiert ihn), oder erst, nachdem Ihr diese Tastenbelegung gedrückt habt (Tastaturbelegung > AddOns).",
	["When five or fewer ordinary slots are free, marks the lowest value eligible stack. Protected stacks stay unmarked."] = "Sind fünf oder weniger normale Plätze frei, wird der infrage kommende Stapel mit dem geringsten Wert markiert. Geschützte Stapel bleiben unmarkiert.",
	["When hovering a button shows its tooltip."] = "Wann das Zeigen auf eine Aktionstaste ihren Tooltip anzeigt.",
	["When inactive"] = "Wenn inaktiv",
	["When missing"] = "Wenn sie fehlt",
	["When no situation applies, zoom back to the distance you had before."] = "Trifft keine Situation zu, zoomt die Kamera auf die Entfernung zurück, die Ihr vorher hattet.",
	["When none are left"] = "Wenn keine mehr übrig sind",
	["When one of the spell IDs below lands on you."] = "Wenn einer der Zauber mit den IDs unten Euch trifft.",
	["When one of your listed spells or items is ready again, its icon pops up in the middle of the screen. The global cooldown never counts."] = "Ist einer Eurer aufgelisteten Zauber oder Gegenstände wieder bereit, erscheint sein Symbol in der Bildschirmmitte. Die globale Abklingzeit zählt nie.",
	["When someone asks"] = "Wenn jemand fragt",
	["When someone in your group clicks Send to group, their route shows here."] = "Klickt jemand in Eurer Gruppe auf An Gruppe senden, erscheint seine Route hier.",
	["When the Masque addon is loaded, let it skin EldoUI's buttons (one Masque group per bar). EldoUI's own button art steps aside."] = "Ist das Addon Masque geladen, darf es die Aktionstasten von EldoUI skinnen (eine Masque-Gruppe pro Leiste). EldoUIs eigene Tastengrafik tritt dann zurück.",
	["When the battleground is ready, a bar shows how long you have to enter. You still enter through Blizzard's pop-up."] = "Ist das Schlachtfeld bereit, zeigt eine Leiste, wie lange Ihr noch zum Betreten habt. Betreten müsst Ihr es weiterhin über Blizzards Fenster.",
	["When the breath bar runs out under water."] = "Wenn die Atemleiste unter Wasser abläuft.",
	["When the character was last online."] = "Wann der Charakter zuletzt online war.",
	["When the crosshair shows."] = "Wann das Fadenkreuz erscheint.",
	["When the feed is full, the oldest row makes room."] = "Ist der Ticker voll, macht die älteste Zeile Platz.",
	["When the game lights up a spell (a proc, or a spell you can use now), its buttons flash once. The game's own glow stays as set on the Buttons tab."] = "Hebt das Spiel einen Zauber hervor (ein Proc oder ein Zauber, den Ihr jetzt einsetzen könnt), blinken seine Aktionstasten einmal auf. Das eigene Leuchten des Spiels bleibt, wie auf dem Reiter Knöpfe eingestellt.",
	["When the game lights up one of your spells (the glow on the action button). In boss fights these move to the Incoming area so they don't cover boss warnings."] = "Wenn das Spiel einen Eurer Zauber hervorhebt (das Leuchten auf der Aktionstaste). In Bosskämpfen wandern diese in den Bereich Eingehend, damit sie keine Bosswarnungen verdecken.",
	["When the game says you landed the killing blow. In boss fights these move to the Incoming area."] = "Wenn das Spiel meldet, dass Ihr den Todesstoß versetzt habt. In Bosskämpfen wandern diese in den Bereich Eingehend.",
	["When the guide's spot is in the top half of the screen, its current step card opens under the guide, so the guide grows down from its spot. Lower on the screen RestedXP's own choice stays."] = "Liegt der Platz des Guides in der oberen Bildschirmhälfte, öffnet sich die Karte des aktuellen Schritts unter dem Guide, sodass der Guide von seinem Platz nach unten wächst. Weiter unten auf dem Bildschirm bleibt die eigene Wahl von RestedXP.",
	["When the ring shows."] = "Wann der Ring erscheint.",
	["When the window is on screen."] = "Wann das Fenster auf dem Bildschirm ist.",
	["When two categories' searches find the same item, the higher priority gets it."] = "Finden die Suchen zweier Kategorien denselben Gegenstand, erhält ihn die mit der höheren Priorität.",
	["When you are the master looter and click an item, a menu lists who can take it (by class in a raid) and Request roll. Items from Epic up ask before they are given."] = "Seid Ihr Plündermeister und klickt einen Gegenstand an, listet ein Menü auf, wer ihn nehmen kann (im Schlachtzug nach Klasse), dazu Würfeln anfordern. Gegenstände ab Episch fragen vor dem Vergeben nach.",
	["When you leave, one line with what the run gave you: time, XP kills, experience, gold and reputation."] = "Beim Verlassen eine Zeile mit dem, was Euch der Durchlauf gebracht hat: Zeit, Gegner mit EP, Erfahrung, Gold und Ruf.",
	["When you scrolled up and leave the chat alone this long, it jumps back to the newest line (not while the mouse is over it)."] = "Habt Ihr hochgescrollt und lasst den Chat so lange in Ruhe, springt er zur neuesten Zeile zurück (nicht, solange die Maus darüber ist).",
	["When you swim into deep water fatigue."] = "Wenn Ihr in tiefem Wasser in die Erschöpfung schwimmt.",
	["Where Is It?"] = "Wo ist das?",
	["Where Move puts Blizzard's totem timers. Own mover gives them their own box in move mode; With the totem bar keeps them next to the shaman totem bar. Other classes use the mover."] = "Wohin Verschieben Blizzards Totemtimer setzt. Eigenes Verschiebefeld gibt ihnen im Verschiebemodus ein eigenes Feld; Mit der Totemleiste hält sie neben der Schamanen-Totemleiste. Andere Klassen verwenden das Verschiebefeld.",
	["Where a new column (or row) starts once one is full."] = "Wo eine neue Spalte (oder Zeile) beginnt, sobald eine voll ist.",
	["Where a new line starts when a line is full."] = "Wo eine neue Zeile beginnt, wenn eine Zeile voll ist.",
	["Where a new row starts when one is full."] = "Wo eine neue Reihe beginnt, wenn eine voll ist.",
	["Where blocked phrases and the Cyrillic filter look. Friends, guild members, and group members are always shown."] = "Wo blockierte Phrasen und der Kyrillisch-Filter suchen. Freunde, Gildenmitglieder und Gruppenmitglieder werden immer angezeigt.",
	["Where can you find %s?"] = "Wo findet Ihr %s?",
	["Where do you set your hearthstone's home?"] = "Wo legt Ihr das Zuhause Eures Ruhesteins fest?",
	["Where does the boat from Booty Bay sail to?"] = "Wohin segelt das Schiff aus Beutebucht?",
	["Where each button sits on the bar. Key bindings stay with their button."] = "Wo jede Schaltfläche auf der Leiste sitzt. Tastenbelegungen bleiben bei ihrer Schaltfläche.",
	["Where is %s?"] = "Wo liegt %s?",
	["Where is the %s?"] = "Wo liegt %s?",
	["Where keywords are looked for."] = "Wo nach Stichwörtern gesucht wird.",
	["Where on the button the count sits on this bar. If the macro name uses the same row, the count moves to the opposite edge."] = "Wo auf der Aktionstaste die Anzahl sitzt, auf dieser Leiste. Nutzt der Makroname dieselbe Reihe, rückt die Anzahl an den gegenüberliegenden Rand.",
	["Where on the button the count sits. If the macro name uses the same row, the count moves to the opposite edge."] = "Wo auf der Aktionstaste die Anzahl sitzt. Nutzt der Makroname dieselbe Reihe, rückt die Anzahl an den gegenüberliegenden Rand.",
	["Where on the button the keybind sits on this bar."] = "Wo auf der Aktionstaste die Tastenbelegung sitzt, auf dieser Leiste.",
	["Where on the button the keybind sits."] = "Wo auf der Aktionstaste die Tastenbelegung sitzt.",
	["Where on the button the macro name sits on this bar."] = "Wo auf der Aktionstaste der Makroname sitzt, auf dieser Leiste.",
	["Where on the button the macro name sits."] = "Wo auf der Aktionstaste der Makroname sitzt.",
	["Where on the frame the text shows. Portrait falls back to the center when the frame has no portrait."] = "Wo auf dem Rahmen der Text erscheint. Porträt weicht auf die Mitte aus, wenn der Rahmen kein Porträt hat.",
	["Where the anchors sit."] = "Wo die Anker sitzen.",
	["Where the bars sit. Its own mover is Class Resources in move mode."] = "Wo die Leisten sitzen. Ihr eigenes Verschiebefeld heißt im Verschiebemodus Klassenressourcen.",
	["Where the character logged out."] = "Wo sich der Charakter ausgeloggt hat.",
	["Where the charge count (or the item count in the item row) sits on the icon."] = "Wo die Anzahl der Aufladungen (oder der Gegenstände in der Gegenstandsreihe) auf dem Symbol sitzt.",
	["Where the countdown sits on the icon."] = "Wo der Countdown auf dem Symbol sitzt.",
	["Where the extra text sits on the health bar."] = "Wo der zusätzliche Text auf der Gesundheitsleiste sitzt.",
	["Where the hearthstone is set."] = "Wo der Ruhestein gesetzt ist.",
	["Where the icon sits next to the text."] = "Wo das Symbol neben dem Text sitzt.",
	["Where the icon sits on each bar, or no icon."] = "Wo das Symbol auf jeder Leiste sitzt, oder kein Symbol.",
	["Where the icon sits."] = "Wo das Symbol sitzt.",
	["Where the next member goes."] = "Wohin das nächste Mitglied kommt.",
	["Where the next row (or bar) goes."] = "Wohin die nächste Reihe (oder Leiste) kommt.",
	["Where the panel's Announce button posts its one line. It only posts when you click it."] = "Wohin die Schaltfläche Ankündigen des Panels ihre eine Zeile sendet. Sie sendet nur, wenn Ihr darauf klickt.",
	["Where the player with the most threat sits."] = "Wo der Spieler mit der meisten Bedrohung sitzt.",
	["Where the private aura slots sit."] = "Wo die Plätze für private Auren sitzen.",
	["Where the ready check, resurrection, summon and phase icons sit."] = "Wo die Symbole für Bereitschaftscheck, Wiederbelebung, Beschwörung und Phase sitzen.",
	["Where the set buttons sit."] = "Wo die Set-Schaltflächen sitzen.",
	["Where the skull, cross and other markers sit."] = "Wo Totenschädel, Kreuz und die anderen Markierungen sitzen.",
	["Where the spell's icon sits."] = "Wo das Symbol des Zaubers sitzt.",
	["Where the tabs and the Errors, Find and Copy buttons sit: above or under the messages (move switch). The right panel's title follows."] = "Wo die Reiter und die Schaltflächen Fehler, Suchen und Kopieren sitzen: über oder unter den Nachrichten (Schalter Verschieben). Der Titel des rechten Panels folgt.",
	["Where the time text sits: under or over the icon, or on it."] = "Wo der Zeittext sitzt: unter oder über dem Symbol oder darauf.",
	["Where the timers come from. Automatic uses the boss mod EldoUI set up, so nothing shows twice. Both shows DBM and BigWigs and drops doubles."] = "Woher die Timer kommen. Automatisch verwendet den Bossmod, den EldoUI eingerichtet hat, damit nichts doppelt erscheint. Beide zeigt DBM und BigWigs und entfernt Doppelte.",
	["Where the tooltips of this panel's blocks open."] = "Wo sich die Tooltips der Blöcke dieses Panels öffnen.",
	["Where this label sits on or around the icon."] = "Wo diese Beschriftung auf oder um das Symbol sitzt.",
	["Whether bars empty or fill up while they count down."] = "Ob sich Leisten beim Herunterzählen leeren oder füllen.",
	["Whether the Alerts tab is ready, or why matches are waiting."] = "Ob der Reiter Hinweise bereit ist oder warum Treffer warten.",
	["Whether the limit below is in seconds or in percent of the whole time."] = "Ob die Grenze unten in Sekunden oder in Prozent der Gesamtzeit gilt.",
	["Whether the spell is looked for as a buff or a debuff."] = "Ob der Zauber als Stärkungs- oder als Schwächungszauber gesucht wird.",
	["Whether you have the item's appearance: collected, collected from another item, not collected, or not for your character."] = "Ob Ihr die Vorlage des Gegenstands habt: gesammelt, über einen anderen Gegenstand gesammelt, nicht gesammelt oder nicht für Euren Charakter.",
	["Which Alliance force fights in Arathi Basin?"] = "Welche Streitmacht der Allianz kämpft im Arathibecken?",
	["Which Alliance force fights in Warsong Gulch?"] = "Welche Streitmacht der Allianz kämpft in der Kriegshymnenschlucht?",
	["Which Horde force fights in Arathi Basin?"] = "Welche Streitmacht der Horde kämpft im Arathibecken?",
	["Which Horde force fights in Warsong Gulch?"] = "Welche Streitmacht der Horde kämpft in der Kriegshymnenschlucht?",
	["Which Legacy Challenges the Challenges page lists when it opens; its filter chips change this too."] = "Welche Vermächtnis-Herausforderungen die Seite Herausforderungen beim Öffnen auflistet; auch ihre Filterchips ändern dies.",
	["Which Old God waits deep in the Temple of Ahn'Qiraj?"] = "Welcher Alte Gott wartet tief im Tempel von Ahn'Qiraj?",
	["Which Spell?"] = "Welcher Zauber?",
	["Which ammunition does a bow fire?"] = "Welche Munition verschießt ein Bogen?",
	["Which ammunition does a gun fire?"] = "Welche Munition verschießt ein Gewehr?",
	["Which army of the undead obeys the Lich King?"] = "Welche Untotenarmee gehorcht dem Lichkönig?",
	["Which bag holds a hunter's arrows?"] = "Welche Tasche fasst die Pfeile eines Jägers?",
	["Which bag holds a hunter's bullets?"] = "Welche Tasche fasst die Kugeln eines Jägers?",
	["Which band of thieves operates in Alterac and Hillsbrad?"] = "Welche Diebesbande treibt im Alteracgebirge und im Vorgebirge des Hügellands ihr Unwesen?",
	["Which bars"] = "Welche Leisten",
	["Which black dragon hides in Stormwind as Lady Katrana Prestor?"] = "Welcher schwarze Drache verbirgt sich in Sturmwind als Lady Katrana Prestor?",
	["Which blood god do the Zandalari want stopped in Zul'Gurub?"] = "Welchen Blutgott wollen die Zandalari in Zul'Gurub aufhalten?",
	["Which blue dragon roams Azshara as a world boss?"] = "Welcher blaue Drache streift als Weltboss durch Azshara?",
	["Which bridge joins the Wetlands and the Arathi Highlands?"] = "Welche Brücke verbindet das Sumpfland mit dem Arathihochland?",
	["Which bubbles show"] = "Welche Sprechblasen erscheinen",
	["Which capital city is home to the %s race?"] = "Welche Hauptstadt ist die Heimat des Volks %s?",
	["Which characters the gold tooltip lists. Right-click the gold datatext to switch."] = "Welche Charaktere der Gold-Tooltip auflistet. Rechtsklickt auf den Datentext Gold, um umzuschalten.",
	["Which characters the window lists first. You can change it in the window's top bar too. On Forever, \"This realm\" means everyone on the same ruleset (PvE, PvP, RP or Hardcore)."] = "Welche Charaktere das Fenster zuerst auflistet. Ihr könnt es auch in der oberen Leiste des Fensters ändern. Auf Forever bedeutet „Dieser Realm“ alle mit demselben Regelwerk (PvE, PvP, RP oder Hardcore).",
	["Which characters the window lists: this character, this realm (on Forever: everyone on the same ruleset), this faction, or all. Groups you made show here too."] = "Welche Charaktere das Fenster auflistet: dieser Charakter, dieser Realm (auf Forever: alle mit demselben Regelwerk), diese Fraktion oder alle. Gruppen, die Ihr erstellt habt, erscheinen auch hier.",
	["Which chat types the edit box stays on after you send a line, one tick each. The ticks start as the game has them: everything but yell. Needs the Blizzard UI switch Improve."] = "Auf welchen Chatarten das Eingabefeld bleibt, nachdem Ihr eine Zeile gesendet habt, je ein Haken. Die Haken beginnen so, wie das Spiel sie setzt: alles außer Schreien. Braucht den Blizzard-UI-Schalter Verbessern.",
	["Which class can learn %s?"] = "Welche Klasse kann %s erlernen?",
	["Which creatures in the mines of Elwynn Forest are famous for guarding their candles?"] = "Welche Kreaturen in den Minen des Waldes von Elwynn sind dafür berühmt, ihre Kerzen zu bewachen?",
	["Which cult gathers in the Twilight camps of Silithus?"] = "Welcher Kult versammelt sich in den Lagern des Zwielichts in Silithus?",
