	["Width and height of each icon (an icon's own size wins)."] = "Breite und Höhe jedes Symbols (die eigene Größe eines Symbols hat Vorrang).",
	["Width and height of each icon."] = "Breite und Höhe jedes Symbols.",
	["Width and height of each potion, food or flask button."] = "Breite und Höhe jeder Schaltfläche für Tränke, Essen oder Fläschchen.",
	["Width in pixels. Full spans the whole screen."] = "Breite in Pixeln. Voll reicht über den ganzen Bildschirm.",
	["Width of EldoUI's loot window."] = "Breite des Beutefensters von EldoUI.",
	["Width of each EldoUI roll bar."] = "Breite jeder Würfelleiste von EldoUI.",
	["Width of each buff bar."] = "Breite jeder Stärkungszauberleiste.",
	["Width of each button in pixels. Square buttons are as high as they are wide."] = "Breite jeder Aktionstaste in Pixeln. Quadratische Tasten sind so hoch wie breit.",
	["Width of each mark in pixels."] = "Breite jeder Markierung in Pixeln.",
	["Width of each party or raid frame."] = "Breite jedes Gruppen- oder Schlachtzugsrahmens.",
	["Width of each timer bar in pixels."] = "Breite jeder Timerleiste in Pixeln.",
	["Width of each timer bar, icon included."] = "Breite jeder Timerleiste, Symbol eingeschlossen.",
	["Width of each timer bar."] = "Breite jeder Timerleiste.",
	["Width of every row. While Match the Cooldown Manager width is on, used only when that row is hidden."] = "Breite jeder Reihe. Solange Breite des Abklingzeitenmanagers übernehmen an ist, nur verwendet, wenn diese Reihe ausgeblendet ist.",
	["Width of every swing bar (also EldoUI's own bars)."] = "Breite jeder Schlagleiste (auch der eigenen Leisten von EldoUI).",
	["Width of the \"Boss Timers\" mover (BigWigs and DBM). With BigWigs' \"copy width of custom anchor\" on, the bars take this width; DBM's timer bars always do."] = "Breite des Verschiebefelds „Boss-Timer“ (BigWigs und DBM). Ist bei BigWigs „copy width of custom anchor“ an, übernehmen die Leisten diese Breite; die Timerleisten von DBM tun das immer.",
	["Width of the \"Boss Timers: Soon\" mover, where BigWigs' emphasized and DBM's enlarged timers go."] = "Breite des Verschiebefelds „Boss-Timer: Bald“, wohin die hervorgehobenen Timer von BigWigs und die vergrößerten von DBM kommen.",
	["Width of the \"Questie Tracker\" mover. Questie sizes the tracker itself; its corner sits at the mover's corner."] = "Breite des Verschiebefelds „Questie-Tracker“. Questie bestimmt die Größe des Trackers selbst; seine Ecke sitzt an der Ecke des Verschiebefelds.",
	["Width of the area box. Lines move inside it."] = "Breite des Bereichsfelds. Zeilen bewegen sich darin.",
	["Width of the chat panel."] = "Breite des Chatpanels.",
	["Width of the feed."] = "Breite des Tickers.",
	["Width of the list in pixels."] = "Breite der Liste in Pixeln.",
	["Width of the main meter window."] = "Breite des Hauptfensters des Schadensmessers.",
	["Width of the mirror timer bars."] = "Breite der Atem- und Erschöpfungsleisten.",
	["Width of the panel in pixels."] = "Breite des Panels in Pixeln.",
	["Width of the panel with your gold, items and XP."] = "Breite des Panels mit Eurem Gold, Euren Gegenständen und Euren EP.",
	["Width of the panel. It stays centered on its place (move mode: NPC Dialog)."] = "Breite des Panels. Es bleibt an seinem Platz zentriert (Verschiebemodus: NSC-Dialog).",
	["Width of the right panel."] = "Breite des rechten Panels.",
	["Width of the search box and its results."] = "Breite des Suchfelds und seiner Ergebnisse.",
	["Width of the text area. Long text shrinks to fit."] = "Breite des Textbereichs. Langer Text schrumpft, bis er passt.",
	["Width of the window."] = "Breite des Fensters.",
	["Width of window 1 in UI units, when \"Set the window size\" is on."] = "Breite von Fenster 1 in UI-Einheiten, wenn „Fenstergröße festlegen“ an ist.",
	["Width of window 2, when it is placed and sized by EldoUI."] = "Breite von Fenster 2, wenn EldoUI es platziert und seine Größe festlegt.",
	["Width on its own position. Stack is as wide as the stack."] = "Breite an eigener Position. Stapel ist so breit wie der Stapel.",
	["Width to height of the buttons. Wide shapes are lower than they are wide; the icon is cropped to fit, never stretched."] = "Verhältnis von Breite zu Höhe der Aktionstasten. Breite Formen sind niedriger als breit; das Symbol wird passend zugeschnitten, nie gestreckt.",
	["Wind rider"] = "Windreiter",
	["Window 1 height"] = "Höhe von Fenster 1",
