	["Words"] = "Wörter",
	["Words and quiz"] = "Wörter und Quiz",
	["Works on the game's chat edit box. Every part of a long message is sent by your own Enter press; EldoUI never sends a line by itself."] = "Funktioniert mit dem Chat-Eingabefeld des Spiels. Jeder Teil einer langen Nachricht wird durch Euren eigenen Druck auf die Eingabetaste gesendet; EldoUI sendet nie von selbst eine Zeile.",
	["World"] = "Welt",
	["World PvP"] = "Welt-PvP",
	["Write a line in chat after an upgrade: how many buttons changed and to which rank."] = "Nach einer Verbesserung eine Zeile in den Chat schreiben: wie viele Aktionstasten sich geändert haben und auf welchen Rang.",
	["Write how many mobs stand in each pack on its marker."] = "Schreibt auf die Markierung jeder Gegnergruppe, wie viele Gegner darin stehen.",
	["Write keys short: S for Shift, C for Ctrl, A for Alt, M4 for mouse button 4, MwU for wheel up."] = "Tasten kurz schreiben: S für Umschalt, C für Strg, A für Alt, M4 für Maustaste 4, MwU für Mausrad hoch.",
	["Write one line about your death in guild chat."] = "Eine Zeile über Euren Tod in den Gildenchat schreiben.",
	["Writes the free slots (or ammo left, on a quiver) on Blizzard's bag bar buttons of special bags."] = "Schreibt die freien Plätze (oder bei einem Köcher die restliche Munition) auf Blizzards Taschenleisten-Schaltflächen spezieller Taschen.",
	["Writes the settings below into the EldoUI DBM profile again, for example after you changed something in DBM's own options."] = "Schreibt die Einstellungen unten erneut in das EldoUI-Profil von DBM, zum Beispiel nachdem Ihr in den eigenen Optionen von DBM etwas geändert habt.",
