	["You can't forget the character you are logged in on."] = "Ihr könnt den Charakter, mit dem Ihr eingeloggt seid, nicht vergessen.",
	["You can't view this tab."] = "Ihr könnt diesen Reiter nicht ansehen.",
	["You carry none."] = "Ihr habt keine dabei.",
	["You carry these. Hand them in yourself; EldoUI never hands anything in."] = "Diese habt Ihr dabei. Gebt sie selbst ab; EldoUI gibt nie etwas für Euch ab.",
	["You died"] = "Ihr seid gestorben",
	["You don't have enough gold yet."] = "Ihr habt noch nicht genug Gold.",
