	["You lose control"] = "Ihr verliert die Kontrolle",
	["You may withdraw: %s"] = "Ihr dürft abheben: %s",
	["You may withdraw: unlimited"] = "Ihr dürft abheben: unbegrenzt",
	["You picked your own profile in DBM, so EldoUI leaves it alone. \"Set up\" switches back to EldoUI's."] = "Ihr habt in DBM Euer eigenes Profil gewählt, daher lässt EldoUI es in Ruhe. „Einrichten“ schaltet zurück auf das von EldoUI.",
	["You reached %s."] = "Ihr habt %s erreicht.",
	["You roll..."] = "Ihr würfelt...",
	["You rolled a 1: the murloc wins."] = "Ihr habt eine 1 gewürfelt: Der Murloc gewinnt.",
	["You shared a moment ago. Share again in %s."] = "Ihr habt gerade erst geteilt. Teilt in %s erneut.",
	["You win a loot roll"] = "Ihr gewinnt einen Beutewurf",
	["You win!"] = "Ihr gewinnt!",
	["You, a group member, a guild member, or anyone else on the realm."] = "Ihr, ein Gruppenmitglied, ein Gildenmitglied oder sonst jemand auf dem Realm.",
	["You: %s (1 to %s)"] = "Ihr: %s (1 bis %s)",
	["Your Corruption, Bane of Agony and Immolate on the enemy you target. Each joins the group once you know it."] = "Eure Verderbnis, Euer Gebrechen der Pein und Euer Feuerbrand auf dem Gegner, den Ihr anvisiert. Jeder Zauber kommt zur Gruppe hinzu, sobald Ihr ihn kennt.",
	["Your DBM profile comes back when the fight is over."] = "Euer DBM-Profil kommt zurück, wenn der Kampf vorbei ist.",
	["Your EldoUI_LootData has no dungeon packs yet. Update it together with EldoUI."] = "Euer EldoUI_LootData hat noch keine Gegnergruppen für Dungeons. Aktualisiert es zusammen mit EldoUI.",
	["Your EldoUI_LootData lists no dungeon packs."] = "Euer EldoUI_LootData listet keine Gegnergruppen für Dungeons.",
	["Your Flame Shock on the enemy you target, with the time it has left."] = "Euer Flammenschock auf dem Gegner, den Ihr anvisiert, mit seiner Restzeit.",
	["Your Legacy points don't change."] = "Eure Vermächtnispunkte ändern sich nicht.",
	["Your Legacy trees aren't loaded yet"] = "Eure Vermächtnisbäume sind noch nicht geladen",
	["Your Legacy trees aren't loaded yet."] = "Eure Vermächtnisbäume sind noch nicht geladen.",
	["Your Legacy trees aren't loaded yet. Open Blizzard's Legacy window once, then try again."] = "Eure Vermächtnisbäume sind noch nicht geladen. Öffnet einmal Blizzards Vermächtnisfenster und versucht es dann erneut.",
	["Your Legacy trees: ranks now and in your draft, with the changes marked."] = "Eure Vermächtnisbäume: Ränge jetzt und in Eurem Entwurf, mit markierten Änderungen.",
	["Your Moonfire, Insect Swarm and Faerie Fire on the enemy you target. Each joins the group once you know it."] = "Euer Mondfeuer, Insektenschwarm und Feenfeuer auf dem Gegner, den Ihr anvisiert. Jeder Zauber kommt zur Gruppe hinzu, sobald Ihr ihn kennt.",
	["Your Polymorph on your target, with the time it has left, so you see when to cast it again."] = "Eure Verwandlung auf Eurem Ziel, mit ihrer Restzeit, damit Ihr seht, wann Ihr sie erneut wirken müsst.",
	["Your Rejuvenation and Regrowth on the friendly player you target, each with its time left."] = "Eure Verjüngung und Euer Nachwachsen auf dem freundlichen Spieler, den Ihr anvisiert, jeweils mit Restzeit.",
	["Your Renew and Power Word: Shield on the friendly player you target, each with its time left."] = "Eure Erneuerung und Euer Machtwort: Schild auf dem freundlichen Spieler, den Ihr anvisiert, jeweils mit Restzeit.",
	["Your Serpent Sting and Hunter's Mark on the enemy you target. Each joins the group once you know it."] = "Euer Schlangenbiss und Euer Mal des Jägers auf dem Gegner, den Ihr anvisiert. Jeder Zauber kommt zur Gruppe hinzu, sobald Ihr ihn kennt.",
	["Your Shadow Word: Pain on the enemy you target, with the time it has left."] = "Euer Schattenwort: Schmerz auf dem Gegner, den Ihr anvisiert, mit seiner Restzeit.",
	["Your Slice and Dice with the time it has left, so you see when to refresh it."] = "Euer Zerhäckseln mit seiner Restzeit, damit Ihr seht, wann Ihr es erneuern müsst.",
	["Your Sunder Armor, Rend and Demoralizing Shout on the enemy you target. Each joins the group once you know it."] = "Euer Rüstung zerreißen, Verwunden und Demoralisierungsruf auf dem Gegner, den Ihr anvisiert. Jeder Zauber kommt zur Gruppe hinzu, sobald Ihr ihn kennt.",
	["Your account and character macros. Your click or Enter on the result runs it."] = "Eure Account- und Charaktermakros. Euer Klick oder die Eingabetaste auf dem Ergebnis führt es aus.",
	["Your alt list"] = "Eure Twinkliste",
	["Your alt list went to your guild."] = "Eure Twinkliste wurde an Eure Gilde gesendet.",
	["Your bar turns red and a note shows when you get close to pulling aggro. Never while you are the tank."] = "Eure Leiste wird rot und ein Hinweis erscheint, wenn Ihr kurz davor seid, Aggro zu ziehen. Nie, solange Ihr der Tank seid.",
	["Your bid"] = "Euer Gebot",
	["Your buffs (right-click to cancel), debuffs, weapon enchants and boss mechanic auras, plus Blizzard's buff frames."] = "Eure Stärkungszauber (Rechtsklick bricht ab), Schwächungszauber, Waffenverzauberungen und Auren von Bossmechaniken, dazu Blizzards Stärkungszauberrahmen.",
	["Your camp buffs are active for 1 hour."] = "Eure Lagereffekte sind 1 Stunde lang aktiv.",
	["Your camp buffs ended. Sit by the fire to get them back."] = "Eure Lagereffekte sind abgelaufen. Setzt Euch ans Feuer, um sie zurückzubekommen.",
	["Your casts get their spell school's theme (pinned spells first, then your class theme). Other units get one fixed theme each."] = "Eure Zauber erhalten das Thema ihrer Zauberschule (angeheftete Zauber zuerst, dann Euer Klassenthema). Andere Einheiten erhalten je ein festes Thema.",
	["Your categories"] = "Eure Kategorien",
	["Your character large on screen, no camera turn."] = "Euer Charakter groß auf dem Bildschirm, ohne Kameradrehung.",
	["Your character on the right side of the screen."] = "Euer Charakter auf der rechten Bildschirmseite.",
	["Your character's name counts as a keyword."] = "Der Name Eures Charakters zählt als Stichwort.",
	["Your characters on quest tooltips"] = "Eure Charaktere in Quest-Tooltips",
	["Your characters side by side: equipment, reputation, currencies, professions and lockouts."] = "Eure Charaktere nebeneinander: Ausrüstung, Ruf, Währungen, Berufe und Instanzsperren.",
	["Your class buffs, auras, armors, aspects or poisons: live with their time, faded while missing. Right-click one to pick the spell and rank; the reminders keep the same pick."] = "Eure Klassen-Stärkungszauber, Auren, Rüstungen, Aspekte oder Gifte: live mit ihrer Zeit, verblasst, solange sie fehlen. Rechtsklickt auf einen, um Zauber und Rang zu wählen; die Erinnerungen übernehmen dieselbe Wahl.",
	["Your class's key cooldowns, with the game's cooldown swipe. A click casts the highest rank you know unless you pick a rank with right-click. Each character keeps its own picks."] = "Die wichtigsten Abklingzeiten Eurer Klasse, mit der Abklingspirale des Spiels. Ein Klick wirkt den höchsten Rang, den Ihr kennt, sofern Ihr nicht per Rechtsklick einen Rang wählt. Jeder Charakter behält seine eigene Auswahl.",
	["Your class: %s"] = "Eure Klasse: %s",
	["Your click-cast bindings are kept too."] = "Eure Klickzauber-Belegungen bleiben ebenfalls erhalten.",
	["Your collected mounts. Your click or Enter on the result summons it."] = "Eure gesammelten Reittiere. Euer Klick oder die Eingabetaste auf dem Ergebnis ruft es herbei.",
	["Your combo points when they change."] = "Eure Kombopunkte, wenn sie sich ändern.",
	["Your computer's time"] = "Zeit Eures Computers",
	["Your computer's time and date."] = "Uhrzeit und Datum Eures Computers.",
	["Your cooldown rows"] = "Eure Abklingzeitreihen",
	["Your current step"] = "Euer aktueller Schritt",
	["Your damage numbers over enemies"] = "Eure Schadenszahlen über Gegnern",
	["Your dot: the game's position"] = "Euer Punkt: die Position laut Spiel",
	["Your draft matches your build. Click a node to add a rank, or load a profile."] = "Euer Entwurf entspricht Eurem Build. Klickt auf einen Knoten, um einen Rang hinzuzufügen, oder ladet ein Profil.",
	["Your dungeon data doesn't know this dungeon; the route is kept and shows once it does."] = "Eure Dungeondaten kennen diesen Dungeon nicht; die Route bleibt erhalten und erscheint, sobald sie ihn kennen.",
	["Your effects on their button"] = "Eure Effekte auf ihrer Aktionstaste",
	["Your equipped trinkets, with their cooldowns."] = "Eure angelegten Schmuckstücke, mit ihren Abklingzeiten.",
	["Your fishing key: %s. While the bobber is out it loots the bobber."] = "Eure Angeltaste: %s. Solange der Schwimmer draußen ist, plündert sie ihn.",
	["Your fleet"] = "Eure Flotte",
	["Your fleet is sunk."] = "Eure Flotte ist versenkt.",
	["Your focus's cast bar, in the focus theme."] = "Die Zauberleiste Eures Fokus, im Fokusthema.",
	["Your gold in the footer; hover it for every character's gold."] = "Euer Gold in der Fußzeile; zeigt darauf für das Gold jedes Charakters.",
	["Your gold over time: one character or all of them, per day or per week."] = "Euer Gold im Zeitverlauf: ein Charakter oder alle, pro Tag oder pro Woche.",
	["Your group in combat"] = "Eure Gruppe im Kampf",
	["Your group posts to the instance group, raid or party you are in."] = "Eure Gruppe: sendet an die Instanzgruppe, den Schlachtzug oder die Gruppe, in der Ihr seid.",
	["Your groups and bank marks are kept too."] = "Eure Gruppen und Bankmarkierungen bleiben ebenfalls erhalten.",
	["Your guide"] = "Euer Guide",
	["Your guild banks, and the alt lists of guild members who share theirs."] = "Eure Gildenbanken und die Twinklisten von Gildenmitgliedern, die ihre teilen.",
	["Your healing numbers"] = "Eure Heilungszahlen",
	["Your history"] = "Euer Verlauf",
	["Your looks"] = "Eure Optiken",
	["Your main cooldown row has no spells yet (Cooldown Manager > Own rows)."] = "Eure Hauptabklingzeitreihe hat noch keine Zauber (Abklingzeitenmanager > Eigene Reihen).",
	["Your mana, rage or energy."] = "Euer Mana, Eure Wut oder Energie.",
	["Your move."] = "Ihr seid am Zug.",
	["Your own bar in a fixed color."] = "Eure eigene Leiste in einer festen Farbe.",
	["Your own cast bar. Your casts get the theme of their spell school."] = "Eure eigene Zauberleiste. Eure Zauber erhalten das Thema ihrer Zauberschule.",
	["Your own categories and the section order as a string to share."] = "Eure eigenen Kategorien und die Reihenfolge der Abschnitte als String zum Teilen.",
	["Your own death"] = "Euer eigener Tod",
	["Your own deaths."] = "Eure eigenen Tode.",
	["Your own dungeon routes and the route picked per dungeon."] = "Eure eigenen Dungeonrouten und die pro Dungeon gewählte Route.",
	["Your own frame in the party frames."] = "Euer eigener Rahmen in den Gruppenrahmen.",
	["Your own health as a row in the stack."] = "Eure eigene Gesundheit als Zeile im Stapel.",
	["Your own list, separated by commas or spaces. Find an ID on Wowhead (the number in the link)."] = "Eure eigene Liste, durch Kommas oder Leerzeichen getrennt. Eine ID findet Ihr auf Wowhead (die Zahl im Link).",
	["Your own numbers from Blizzard's damage meter (current fight)."] = "Eure eigenen Werte aus Blizzards Schadensmesser (aktueller Kampf).",
	["Your own routes of every dungeon: open, rename, export and delete them."] = "Eure eigenen Routen für jeden Dungeon: öffnen, umbenennen, exportieren und löschen.",
	["Your own rows of aura icons, each with its own mover: pick the spells, the unit and whether only yours count. The game shows each aura; EldoUI only places and dresses the icons."] = "Eure eigenen Reihen von Aurensymbolen, jede mit eigenem Verschiebefeld: Wählt die Zauber, die Einheit und ob nur Eure zählen. Das Spiel zeigt jede Aura; EldoUI platziert und gestaltet nur die Symbole.",
